// GENERATED FILE. Source of truth: docs/data/biblia-emanus/*.json
import type { PublishedEmanusOtTextBook } from "../publishedEmanusOtText.js"

export const EMANUS_TEXT_BOOK: PublishedEmanusOtTextBook = {
  order: 1,
  code: "GEN",
  name: "Geneza",
  chapters: {
    1: ["La început, Dumnezeu a creat cerurile și pământul.", "Pământul era fără formă și gol. Întunericul acoperea suprafața adâncului, iar Duhul lui Dumnezeu plutea deasupra apelor.", "Dumnezeu a spus: „Să fie lumină!” Și a fost lumină.", "Dumnezeu a văzut că lumina era bună și a despărțit lumina de întuneric.", "Dumnezeu a numit lumina „zi”, iar întunericul l-a numit „noapte”. A fost seară, apoi a fost dimineață: ziua întâi.", "Dumnezeu a spus: „Să fie o întindere în mijlocul apelor, care să despartă apele de ape.”", "Dumnezeu a făcut întinderea și a despărțit apele de sub întindere de apele de deasupra întinderii. Și așa a fost.", "Dumnezeu a numit întinderea „cer”. A fost seară, apoi a fost dimineață: ziua a doua.", "Dumnezeu a spus: „Să se adune într-un singur loc apele de sub cer și să se arate uscatul.” Și așa a fost.", "Dumnezeu a numit uscatul „pământ”, iar adunarea apelor a numit-o „mări”. Dumnezeu a văzut că era bine.", "Dumnezeu a spus: „Să dea pământul verdeață: plante care produc sămânță și pomi roditori care fac, după felul lor, rod cu sămânță în el.” Și așa a fost.", "Pământul a dat verdeață: plante care produc sămânță după felul lor și pomi care fac rod cu sămânță în el, după felul lor. Dumnezeu a văzut că era bine.", "A fost seară, apoi a fost dimineață: ziua a treia.", "Dumnezeu a spus: „Să fie luminători în întinderea cerului, ca să despartă ziua de noapte. Ei să fie semne pentru vremuri rânduite, pentru zile și pentru ani.", "Să fie luminători în întinderea cerului, ca să lumineze pământul.” Și așa a fost.", "Dumnezeu a făcut cei doi luminători mari: luminătorul mai mare ca să stăpânească ziua și luminătorul mai mic ca să stăpânească noaptea. A făcut și stelele.", "Dumnezeu i-a așezat în întinderea cerului ca să lumineze pământul,", "să stăpânească ziua și noaptea și să despartă lumina de întuneric. Dumnezeu a văzut că era bine.", "A fost seară, apoi a fost dimineață: ziua a patra.", "Dumnezeu a spus: „Apele să mișune de viețuitoare, iar păsările să zboare deasupra pământului, pe întinderea cerului.”", "Dumnezeu a creat marile făpturi ale mării și toate ființele vii care se mișcă și de care mișună apele, după felul lor, precum și toate păsările înaripate, după felul lor. Dumnezeu a văzut că era bine.", "Dumnezeu le-a binecuvântat, spunând: „Fiți roditoare, înmulțiți-vă și umpleți apele mărilor, iar păsările să se înmulțească pe pământ.”", "A fost seară, apoi a fost dimineață: ziua a cincea.", "Dumnezeu a spus: „Să dea pământul viețuitoare după felul lor: animale domestice, vietăți care mișună și animale sălbatice ale pământului, după felul lor.” Și așa a fost.", "Dumnezeu a făcut animalele sălbatice ale pământului după felul lor, animalele domestice după felul lor și toate vietățile care mișună pe pământ, după felul lor. Dumnezeu a văzut că era bine.", "Dumnezeu a spus: „Să facem omul după chipul Nostru, după asemănarea Noastră. Ei să stăpânească peste peștii mării, peste păsările cerului, peste animalele domestice, peste tot pământul și peste orice vietate care mișună pe pământ.”", "Dumnezeu l-a creat pe om după chipul Său; după chipul lui Dumnezeu l-a creat; bărbat și femeie i-a creat.", "Dumnezeu i-a binecuvântat și le-a spus: „Fiți roditori, înmulțiți-vă, umpleți pământul și supuneți-l. Stăpâniți peste peștii mării, peste păsările cerului și peste orice viețuitoare care se mișcă pe pământ.”", "Dumnezeu a spus: „Iată, v-am dat orice plantă care produce sămânță pe toată suprafața pământului și orice pom care are rod cu sămânță în el. Acestea vă vor fi hrană.", "Tuturor animalelor pământului, tuturor păsărilor cerului și tuturor vietăților care mișună pe pământ și au viață le-am dat ca hrană orice plantă verde.” Și așa a fost.", "Dumnezeu a privit tot ce făcuse și, iată, era foarte bine. A fost seară, apoi a fost dimineață: ziua a șasea."],
    2: ["Astfel au fost încheiate cerurile, pământul și toată oștirea lor.", "În ziua a șaptea, Dumnezeu Și-a încheiat lucrarea pe care o făcuse și S-a odihnit în ziua a șaptea de toată lucrarea pe care o făcuse.", "Dumnezeu a binecuvântat ziua a șaptea și a sfințit-o, pentru că în ea S-a odihnit de toată lucrarea de creație pe care o făcuse.", "Aceasta este istoria cerurilor și a pământului, când au fost create, în ziua când DOMNUL Dumnezeu a făcut pământul și cerurile.", "Niciun arbust al câmpului nu era încă pe pământ și nicio plantă a câmpului nu răsărise încă, fiindcă DOMNUL Dumnezeu nu trimisese ploaie pe pământ și nu era niciun om care să lucreze pământul.", "Dar o ceață se ridica din pământ și uda toată suprafața solului.", "DOMNUL Dumnezeu l-a modelat pe om din țărâna pământului, i-a suflat în nări suflare de viață, iar omul a devenit o ființă vie.", "DOMNUL Dumnezeu a sădit o grădină în Eden, spre răsărit, și l-a așezat acolo pe omul pe care îl modelase.", "DOMNUL Dumnezeu a făcut să crească din pământ orice pom plăcut la vedere și bun de mâncat, precum și pomul vieții în mijlocul grădinii și pomul cunoașterii binelui și răului.", "Un râu ieșea din Eden ca să ude grădina, iar de acolo se despărțea în patru brațe.", "Numele celui dintâi este Pișon; el înconjoară toată țara Havila, unde se găsește aur.", "Aurul acelei țări este bun; acolo se găsesc și bedelion și piatră de onix.", "Numele celui de-al doilea râu este Ghihon; el înconjoară toată țara Cuș.", "Numele celui de-al treilea râu este Hidechel; el curge la răsărit de Asiria. Al patrulea râu este Eufratul.", "DOMNUL Dumnezeu l-a luat pe om și l-a așezat în grădina Edenului ca s-o lucreze și s-o păzească.", "DOMNUL Dumnezeu i-a poruncit omului: „Poți mânca în voie din orice pom al grădinii.”", "I-a spus însă: „Să nu mănânci din pomul cunoașterii binelui și răului, căci în ziua când vei mânca din el vei muri negreșit.”", "DOMNUL Dumnezeu a spus: „Nu este bine ca omul să fie singur. Îi voi face un ajutor care să-i corespundă.”", "DOMNUL Dumnezeu a modelat din pământ toate animalele câmpului și toate păsările cerului și le-a adus la om ca să vadă cum le va numi. Orice nume a dat omul fiecărei ființe vii, acela i-a rămas numele.", "Omul a pus nume tuturor animalelor domestice, păsărilor cerului și tuturor animalelor câmpului, dar pentru om nu s-a găsit un ajutor care să-i corespundă.", "Atunci DOMNUL Dumnezeu a făcut să cadă peste om un somn adânc. În timp ce omul dormea, a luat una dintre coastele lui și a închis carnea la loc.", "Din coasta pe care o luase din om, DOMNUL Dumnezeu a făcut o femeie și a adus-o la om.", "Omul a spus: „Aceasta este, în sfârșit, os din oasele mele și carne din carnea mea. Ea va fi numită «femeie», pentru că a fost luată din bărbat.”", "De aceea, bărbatul își va lăsa tatăl și mama, se va alipi de soția lui, iar ei vor fi un singur trup.", "Omul și soția lui erau amândoi goi și nu se rușinau."],
    3: ["Șarpele era mai viclean decât orice vietate a câmpului pe care o făcuse DOMNUL Dumnezeu. El i-a spus femeii: „Chiar a spus Dumnezeu: «Să nu mâncați din niciun pom al grădinii»?”", "Femeia i-a răspuns șarpelui: „Putem mânca din rodul pomilor grădinii.”", "Femeia a continuat: „Dar despre rodul pomului care este în mijlocul grădinii, Dumnezeu a spus: «Să nu mâncați din el și să nu vă atingeți de el, ca să nu muriți.»”", "Șarpele i-a spus femeii: „Nicidecum nu veți muri.”", "El a continuat: „Dumnezeu știe că, în ziua când veți mânca din el, vi se vor deschide ochii și veți fi ca Dumnezeu, cunoscând binele și răul.”", "Femeia a văzut că pomul era bun de mâncat, plăcut ochilor și de dorit pentru dobândirea înțelepciunii. A luat din rodul lui și a mâncat. I-a dat și soțului ei, care era cu ea, iar el a mâncat.", "Atunci li s-au deschis ochii amândurora și și-au dat seama că erau goi. Au cusut laolaltă frunze de smochin și și-au făcut cingători.", "Au auzit glasul DOMNULUI Dumnezeu, care umbla prin grădină în adierea zilei, iar omul și soția lui s-au ascuns de fața DOMNULUI Dumnezeu printre pomii grădinii.", "DOMNUL Dumnezeu l-a chemat pe om și i-a spus: „Unde ești?”", "Omul a răspuns: „Ți-am auzit glasul în grădină și m-am temut, fiindcă eram gol; de aceea m-am ascuns.”", "DOMNUL Dumnezeu i-a spus: „Cine ți-a spus că ești gol? Ai mâncat din pomul din care îți poruncisem să nu mănânci?”", "Omul a răspuns: „Femeia pe care mi-ai dat-o să fie cu mine mi-a dat din rodul pomului, iar eu am mâncat.”", "DOMNUL Dumnezeu i-a spus femeii: „Ce ai făcut?” Femeia a răspuns: „Șarpele m-a amăgit, iar eu am mâncat.”", "DOMNUL Dumnezeu i-a spus șarpelui: „Pentru că ai făcut aceasta, ești blestemat mai mult decât toate animalele domestice și decât toate vietățile câmpului. Vei umbla pe pântece și vei mânca țărână în toate zilele vieții tale.", "Voi pune dușmănie între tine și femeie, între sămânța ta și sămânța ei. El îți va lovi capul, iar tu îi vei lovi călcâiul.”", "Femeii i-a spus: „Voi înmulți foarte mult truda ta și sarcinile tale; cu durere vei naște copii. Dorința ta va fi pentru soțul tău, iar el va stăpâni peste tine.”", "Lui Adam i-a spus: „Pentru că ai ascultat glasul soției tale și ai mâncat din pomul despre care îți poruncisem: «Să nu mănânci din el», blestemat este pământul din pricina ta. Cu multă trudă vei mânca din el în toate zilele vieții tale.", "El îți va da spini și mărăcini, iar tu vei mânca plantele câmpului.", "Îți vei mânca pâinea în sudoarea feței până când te vei întoarce în pământ, căci din el ai fost luat. Pentru că țărână ești și în țărână te vei întoarce.”", "Omul i-a pus soției sale numele Eva, pentru că ea avea să fie mama tuturor celor vii.", "DOMNUL Dumnezeu a făcut haine de piele pentru Adam și soția lui și i-a îmbrăcat.", "DOMNUL Dumnezeu a spus: „Iată, omul a ajuns ca unul dintre Noi, cunoscând binele și răul. Acum, ca nu cumva să-și întindă mâna, să ia și din pomul vieții, să mănânce și să trăiască pentru totdeauna...”", "De aceea, DOMNUL Dumnezeu l-a trimis afară din grădina Edenului ca să lucreze pământul din care fusese luat.", "L-a alungat pe om și a așezat la răsărit de grădina Edenului heruvimii și flacăra sabiei care se rotea, ca să păzească drumul spre pomul vieții."],
    4: ["Adam a cunoscut-o pe Eva, soția lui. Ea a rămas însărcinată, l-a născut pe Cain și a spus: „Am dobândit un om cu ajutorul DOMNULUI.”", "Apoi l-a născut pe fratele lui, Abel. Abel a ajuns păstor de oi, iar Cain lucrător al pământului.", "După un timp, Cain I-a adus DOMNULUI o ofrandă din roadele pământului.", "Abel a adus și el din întâii născuți ai turmei sale și din părțile lor grase. DOMNUL a privit cu bunăvoință spre Abel și spre ofranda lui,", "dar spre Cain și spre ofranda lui nu a privit cu bunăvoință. Cain s-a mâniat foarte tare și i s-a posomorât fața.", "DOMNUL i-a spus lui Cain: „De ce te-ai mâniat și de ce ți s-a posomorât fața?", "Dacă faci bine, nu-ți vei putea ridica fața? Dar dacă nu faci bine, păcatul stă la pândă la ușă. Dorința lui este spre tine, însă tu trebuie să stăpânești peste el.”", "Cain i-a spus fratelui său Abel: „Să ieșim la câmp.” În timp ce erau pe câmp, Cain s-a ridicat împotriva fratelui său Abel și l-a ucis.", "DOMNUL i-a spus lui Cain: „Unde este fratele tău Abel?” El a răspuns: „Nu știu. Sunt eu păzitorul fratelui meu?”", "DOMNUL a spus: „Ce ai făcut? Glasul sângelui fratelui tău strigă către Mine din pământ.", "Acum ești blestemat și alungat de pământul care și-a deschis gura ca să primească din mâna ta sângele fratelui tău.", "Când vei lucra pământul, el nu-ți va mai da puterea lui. Vei fi fugar și rătăcitor pe pământ.”", "Cain I-a spus DOMNULUI: „Pedeapsa mea este prea mare ca s-o pot purta.", "Iată, astăzi mă izgonești de pe fața pământului și voi fi ascuns de fața Ta. Voi fi fugar și rătăcitor pe pământ, iar oricine mă va găsi mă va ucide.”", "DOMNUL i-a spus: „De aceea, dacă cineva îl ucide pe Cain, răzbunarea va veni asupra lui de șapte ori.” Apoi DOMNUL a pus un semn pentru Cain, ca nimeni dintre cei care îl vor găsi să nu-l lovească.", "Cain a plecat de la fața DOMNULUI și a locuit în țara Nod, la răsărit de Eden.", "Cain a cunoscut-o pe soția lui. Ea a rămas însărcinată și l-a născut pe Enoh. Cain construia o cetate și a numit cetatea după numele fiului său, Enoh.", "Lui Enoh i s-a născut Irad. Irad a devenit tatăl lui Mehuiael, Mehuiael a devenit tatăl lui Metușael, iar Metușael a devenit tatăl lui Lameh.", "Lameh și-a luat două soții. Numele celei dintâi era Ada, iar numele celei de-a doua era Țila.", "Ada l-a născut pe Iabal; el a fost strămoșul celor care locuiesc în corturi și cresc animale.", "Numele fratelui său era Iubal; el a fost strămoșul tuturor celor care cântă la liră și la fluier.", "Țila l-a născut și pe Tubal-Cain, făurarul tuturor uneltelor tăietoare de bronz și de fier. Sora lui Tubal-Cain era Naama.", "Lameh le-a spus soțiilor sale: „Ada și Țila, ascultați glasul meu! Soțiile lui Lameh, luați aminte la cuvintele mele! Am ucis un om pentru rana mea, un tânăr pentru vânătaia mea.", "Dacă pentru Cain răzbunarea este de șapte ori, pentru Lameh va fi de șaptezeci și șapte de ori.”", "Adam a cunoscut-o din nou pe soția lui. Ea a născut un fiu și i-a pus numele Set, spunând: „Dumnezeu mi-a rânduit un alt urmaș în locul lui Abel, fiindcă l-a ucis Cain.”", "Și lui Set i s-a născut un fiu, căruia i-a pus numele Enoș. Atunci oamenii au început să cheme Numele DOMNULUI."],
    5: ["Aceasta este cartea istoriei lui Adam. În ziua când Dumnezeu l-a creat pe om, l-a făcut după asemănarea lui Dumnezeu.", "I-a creat bărbat și femeie, i-a binecuvântat și, în ziua când au fost creați, le-a dat numele „om”.", "Adam a trăit 130 de ani și a avut un fiu după asemănarea sa, după chipul său, căruia i-a pus numele Set.", "După nașterea lui Set, Adam a mai trăit 800 de ani și a avut fii și fiice.", "Toate zilele vieții lui Adam au fost 930 de ani; apoi a murit.", "Set a trăit 105 ani și a avut un fiu, pe Enoș.", "După nașterea lui Enoș, Set a mai trăit 807 ani și a avut fii și fiice.", "Toate zilele vieții lui Set au fost 912 ani; apoi a murit.", "Enoș a trăit 90 de ani și a avut un fiu, pe Kenan.", "După nașterea lui Kenan, Enoș a mai trăit 815 ani și a avut fii și fiice.", "Toate zilele vieții lui Enoș au fost 905 ani; apoi a murit.", "Kenan a trăit 70 de ani și a avut un fiu, pe Mahalaleel.", "După nașterea lui Mahalaleel, Kenan a mai trăit 840 de ani și a avut fii și fiice.", "Toate zilele vieții lui Kenan au fost 910 ani; apoi a murit.", "Mahalaleel a trăit 65 de ani și a avut un fiu, pe Iared.", "După nașterea lui Iared, Mahalaleel a mai trăit 830 de ani și a avut fii și fiice.", "Toate zilele vieții lui Mahalaleel au fost 895 de ani; apoi a murit.", "Iared a trăit 162 de ani și a avut un fiu, pe Enoh.", "După nașterea lui Enoh, Iared a mai trăit 800 de ani și a avut fii și fiice.", "Toate zilele vieții lui Iared au fost 962 de ani; apoi a murit.", "Enoh a trăit 65 de ani și a avut un fiu, pe Metusala.", "După nașterea lui Metusala, Enoh a umblat cu Dumnezeu 300 de ani și a avut fii și fiice.", "Toate zilele vieții lui Enoh au fost 365 de ani.", "Enoh a umblat cu Dumnezeu; apoi nu a mai fost, pentru că Dumnezeu l-a luat.", "Metusala a trăit 187 de ani și a avut un fiu, pe Lameh.", "După nașterea lui Lameh, Metusala a mai trăit 782 de ani și a avut fii și fiice.", "Toate zilele vieții lui Metusala au fost 969 de ani; apoi a murit.", "Lameh a trăit 182 de ani și a avut un fiu.", "I-a pus numele Noe, spunând: „Acesta ne va mângâia în munca și în truda mâinilor noastre, venite din pământul pe care l-a blestemat DOMNUL.”", "După nașterea lui Noe, Lameh a mai trăit 595 de ani și a avut fii și fiice.", "Toate zilele vieții lui Lameh au fost 777 de ani; apoi a murit.", "Când Noe avea 500 de ani, i s-au născut Sem, Ham și Iafet."],
    6: ["Când oamenii au început să se înmulțească pe suprafața pământului și li s-au născut fiice,", "fiii lui Dumnezeu au văzut că fiicele oamenilor erau frumoase și și-au luat de soții pe oricare dintre ele au ales.", "DOMNUL a spus: „Duhul Meu nu va rămâne pentru totdeauna în om, fiindcă și el este carne; zilele lui vor fi de 120 de ani.”", "Nefilimii erau pe pământ în zilele acelea și chiar și după aceea, când fiii lui Dumnezeu au intrat la fiicele oamenilor, iar ele le-au născut copii. Aceștia au fost vitejii din vechime, oameni cu renume.", "DOMNUL a văzut că răutatea omului era mare pe pământ și că orice închipuire a gândurilor inimii lui era mereu îndreptată numai spre rău.", "DOMNULUI I-a părut rău că îl făcuse pe om pe pământ și S-a mâhnit în inima Lui.", "DOMNUL a spus: „Îl voi șterge de pe suprafața pământului pe omul pe care l-am creat — pe om împreună cu animalele, vietățile care mișună și păsările cerului — pentru că Îmi pare rău că i-am făcut.”", "Dar Noe a găsit bunăvoință în ochii DOMNULUI.", "Aceasta este istoria lui Noe. Noe era un om drept și integru printre cei din vremea lui. Noe umbla cu Dumnezeu.", "Noe a avut trei fii: Sem, Ham și Iafet.", "Pământul era corupt înaintea lui Dumnezeu și era plin de violență.", "Dumnezeu a privit pământul și, iată, era corupt, pentru că orice făptură își corupsese calea pe pământ.", "Dumnezeu i-a spus lui Noe: „Am hotărât sfârșitul oricărei făpturi, fiindcă pământul este plin de violență din cauza lor. Iată, îi voi nimici împreună cu pământul.", "Fă-ți o arcă din lemn de gofer. Să faci încăperi în arcă și s-o acoperi cu smoală pe dinăuntru și pe dinafară.", "Așa s-o construiești: lungimea arcei să fie de 300 de coți, lățimea ei de 50 de coți, iar înălțimea ei de 30 de coți.", "Să faci arcei un acoperiș și să-l înalți cu un cot. Să așezi ușa arcei într-o latură a ei și s-o faci cu un nivel de jos, unul mijlociu și unul de sus.", "Iată, Eu voi aduce potopul de ape peste pământ, ca să nimicesc de sub cer orice făptură în care este suflare de viață. Tot ce este pe pământ va pieri.", "Dar Îmi voi întemeia legământul cu tine. Vei intra în arcă: tu, fiii tăi, soția ta și soțiile fiilor tăi împreună cu tine.", "Din orice vietate, din orice făptură, să aduci în arcă câte două, ca să le păstrezi în viață împreună cu tine; să fie parte bărbătească și parte femeiască.", "Din păsări după felul lor, din animale după felul lor și din orice vietate care mișună pe pământ după felul ei, câte două din fiecare vor veni la tine, ca să le păstrezi în viață.", "Ia cu tine din orice hrană care se mănâncă și adun-o la tine; ea va fi hrană pentru tine și pentru ele.”", "Noe a făcut întocmai; a făcut tot ce îi poruncise Dumnezeu."],
    7: ["DOMNUL i-a spus lui Noe: „Intră în arcă, tu și toată casa ta, pentru că te-am văzut drept înaintea Mea în generația aceasta.", "Din fiecare animal curat să iei cu tine câte șapte perechi, masculul și perechea lui; iar din animalele care nu sunt curate, câte o pereche, masculul și perechea lui.", "Și din păsările cerului, câte șapte perechi, parte bărbătească și parte femeiască, pentru ca urmașii lor să rămână vii pe suprafața întregului pământ.", "Pentru că peste șapte zile voi face să plouă pe pământ 40 de zile și 40 de nopți și voi șterge de pe suprafața pământului orice făptură vie pe care am făcut-o.”", "Noe a făcut tot ce îi poruncise DOMNUL.", "Noe avea 600 de ani când a venit potopul de ape peste pământ.", "Noe a intrat în arcă împreună cu fiii lui, cu soția lui și cu soțiile fiilor lui, din cauza apelor potopului.", "Din animalele curate, din animalele necurate, din păsări și din tot ce mișună pe pământ,", "au intrat la Noe în arcă două câte două, parte bărbătească și parte femeiască, așa cum îi poruncise Dumnezeu lui Noe.", "După cele șapte zile, apele potopului au venit peste pământ.", "În al șase sutelea an al vieții lui Noe, în luna a doua, în ziua a șaptesprezecea a lunii, chiar în ziua aceea au izbucnit toate izvoarele marelui adânc și s-au deschis ferestrele cerului.", "Ploaia a căzut pe pământ 40 de zile și 40 de nopți.", "Chiar în ziua aceea au intrat în arcă Noe, Sem, Ham și Iafet, fiii lui Noe, împreună cu soția lui Noe și cu cele trei soții ale fiilor lui.", "Au intrat ei și toate animalele după felul lor, toate vitele după felul lor, toate vietățile care mișună pe pământ după felul lor și toate păsările după felul lor, orice pasăre, orice făptură înaripată.", "Au venit la Noe în arcă două câte două din orice făptură în care era suflare de viață.", "Cele care au intrat erau parte bărbătească și parte femeiască din orice făptură, așa cum îi poruncise Dumnezeu. Apoi DOMNUL a închis după el.", "Potopul a ținut 40 de zile pe pământ. Apele au crescut, au ridicat arca și ea s-a înălțat deasupra pământului.", "Apele au devenit tot mai puternice și au crescut foarte mult pe pământ, iar arca plutea pe suprafața apelor.", "Apele s-au ridicat nespus de mult pe pământ și au fost acoperiți toți munții înalți de sub întregul cer.", "Apele s-au ridicat cu 15 coți deasupra lor, iar munții au fost acoperiți.", "A pierit orice făptură care se mișca pe pământ: păsări, vite, animale, toate vietățile care mișună pe pământ și toți oamenii.", "Tot ce era pe uscat și avea în nări suflarea duhului de viață a murit.", "A fost ștearsă orice făptură de pe suprafața pământului: omul, vitele, vietățile care mișună și păsările cerului. Au fost șterse de pe pământ. A rămas numai Noe și cei care erau cu el în arcă.", "Apele au stăpânit peste pământ 150 de zile."],
    8: ["Dumnezeu Și-a adus aminte de Noe, de toate animalele și de toate vitele care erau cu el în arcă. Dumnezeu a făcut să treacă un vânt peste pământ, iar apele au început să scadă.", "Izvoarele adâncului și ferestrele cerului au fost închise, iar ploaia din cer a fost oprită.", "Apele s-au retras treptat de pe pământ și, după 150 de zile, au scăzut.", "În luna a șaptea, în ziua a șaptesprezecea a lunii, arca s-a oprit pe munții Ararat.", "Apele au continuat să scadă până în luna a zecea. În luna a zecea, în prima zi a lunii, s-au văzut vârfurile munților.", "După 40 de zile, Noe a deschis fereastra arcei pe care o făcuse", "și a trimis un corb. Acesta a zburat încoace și încolo până când apele au secat de pe pământ.", "Apoi a trimis o porumbiță, ca să vadă dacă apele scăzuseră de pe suprafața pământului.", "Dar porumbița nu a găsit unde să-și odihnească piciorul și s-a întors la el în arcă, pentru că apele erau încă pe suprafața întregului pământ. Noe și-a întins mâna, a luat-o și a adus-o la el în arcă.", "A mai așteptat încă șapte zile și a trimis din nou porumbița din arcă.", "Porumbița s-a întors la el spre seară și, iată, avea în cioc o frunză de măslin proaspăt ruptă. Atunci Noe a înțeles că apele scăzuseră de pe pământ.", "A mai așteptat încă șapte zile și a trimis porumbița, dar ea nu s-a mai întors la el.", "În anul 601, în luna întâi, în prima zi a lunii, apele secaseră de pe pământ. Noe a îndepărtat învelitoarea arcei, a privit și, iată, suprafața pământului era uscată.", "În luna a doua, în ziua a douăzeci și șaptea a lunii, pământul era uscat pe deplin.", "Dumnezeu i-a vorbit lui Noe:", "„Ieși din arcă, tu, soția ta, fiii tăi și soțiile fiilor tăi împreună cu tine.", "Scoate împreună cu tine orice vietate care este cu tine, din orice făptură: păsări, vite și orice vietate care mișună pe pământ. Să se răspândească pe pământ, să fie roditoare și să se înmulțească pe pământ.”", "Noe a ieșit împreună cu fiii lui, cu soția lui și cu soțiile fiilor lui.", "Toate animalele, toate vietățile care mișună și toate păsările, tot ce se mișcă pe pământ, au ieșit din arcă după familiile lor.", "Noe a construit un altar DOMNULUI. A luat din fiecare animal curat și din fiecare pasăre curată și a adus arderi-de-tot pe altar.", "DOMNUL a primit mireasma plăcută și a spus în inima Lui: „Nu voi mai blestema din nou pământul din cauza omului, deși înclinația inimii omului este rea din tinerețea lui; și nu voi mai lovi din nou orice făptură vie, așa cum am făcut.", "Cât timp va rămâne pământul, semănatul și seceratul, frigul și căldura, vara și iarna, ziua și noaptea nu vor înceta.”"],
    9: ["Dumnezeu i-a binecuvântat pe Noe și pe fiii lui și le-a spus: „Fiți roditori, înmulțiți-vă și umpleți pământul.", "Frica și groaza de voi vor fi peste orice animal al pământului, peste orice pasăre a cerului, peste tot ce mișună pe pământ și peste toți peștii mării. Ele sunt date în mâna voastră.", "Orice vietate care se mișcă vă va fi hrană. Așa cum v-am dat plantele verzi, acum vi le dau pe toate.", "Dar să nu mâncați carnea împreună cu viața ei, adică sângele ei.", "Voi cere socoteală pentru sângele vieții voastre. Îl voi cere de la orice animal și de la orice om; de la fiecare voi cere socoteală pentru viața fratelui său.", "Cine varsă sângele omului, de către om îi va fi vărsat sângele, pentru că Dumnezeu l-a făcut pe om după chipul Său.", "Iar voi, fiți roditori și înmulțiți-vă; răspândiți-vă din belșug pe pământ și înmulțiți-vă pe el.”", "Dumnezeu le-a vorbit lui Noe și fiilor lui care erau cu el:", "„Iată, Eu Îmi întemeiez legământul cu voi și cu urmașii voștri după voi,", "precum și cu orice vietate care este cu voi: păsările, vitele și toate animalele pământului împreună cu voi, toate cele care au ieșit din arcă, orice animal al pământului.", "Îmi întemeiez legământul cu voi: nicio făptură nu va mai fi nimicită de apele potopului și nu va mai fi niciodată un potop care să distrugă pământul.”", "Dumnezeu a spus: „Acesta este semnul legământului pe care îl pun între Mine și voi și orice vietate care este cu voi, pentru toate generațiile viitoare:", "Îmi așez curcubeul în nor și el va fi semnul legământului dintre Mine și pământ.", "Când voi aduce nori peste pământ și curcubeul se va vedea în nor,", "Îmi voi aduce aminte de legământul Meu, care este între Mine și voi și orice vietate din orice făptură; apele nu vor mai deveni un potop care să nimicească orice făptură.", "Curcubeul va fi în nor, iar Eu îl voi privi ca să-Mi aduc aminte de legământul veșnic dintre Dumnezeu și orice vietate din orice făptură care este pe pământ.”", "Dumnezeu i-a spus lui Noe: „Acesta este semnul legământului pe care l-am întemeiat între Mine și orice făptură care este pe pământ.”", "Fiii lui Noe care au ieșit din arcă erau Sem, Ham și Iafet. Ham era tatăl lui Canaan.", "Aceștia trei erau fiii lui Noe, iar din ei s-a răspândit populația întregului pământ.", "Noe, lucrător al pământului, a început să sădească o vie.", "A băut din vin, s-a îmbătat și a rămas dezgolit în cortul său.", "Ham, tatăl lui Canaan, a văzut goliciunea tatălui său și le-a spus celor doi frați ai săi care erau afară.", "Sem și Iafet au luat o haină, au pus-o pe umerii amândurora și au mers cu spatele ca să acopere goliciunea tatălui lor. Fețele le erau întoarse, astfel încât nu au văzut goliciunea tatălui lor.", "Când Noe s-a trezit din vin și a aflat ce îi făcuse fiul său cel mai mic,", "a spus: „Blestemat să fie Canaan! Să fie robul robilor fraților lui!”", "A mai spus: „Binecuvântat să fie DOMNUL, Dumnezeul lui Sem, iar Canaan să-i fie rob!", "Dumnezeu să-i lărgească hotarele lui Iafet. Să locuiască în corturile lui Sem, iar Canaan să-i fie rob!”", "După potop, Noe a mai trăit 350 de ani.", "Toate zilele lui Noe au fost de 950 de ani; apoi a murit."],
    10: ["Aceasta este istoria fiilor lui Noe: Sem, Ham și Iafet. După potop li s-au născut fii.", "Fiii lui Iafet au fost: Gomer, Magog, Madai, Iavan, Tubal, Meșec și Tiras.", "Fiii lui Gomer au fost: Așchenaz, Rifat și Togarma.", "Fiii lui Iavan au fost: Elișa, Tarșiș, Chitim și Dodanim.", "Din aceștia s-au răspândit popoarele ținuturilor de coastă, fiecare în țara sa, după limba sa, după familiile și națiunile lor.", "Fiii lui Ham au fost: Cuș, Mițraim, Put și Canaan.", "Fiii lui Cuș au fost: Seba, Havila, Sabta, Raema și Sabteca. Fiii lui Raema au fost: Șeba și Dedan.", "Cuș a devenit tatăl lui Nimrod. El a început să fie un viteaz pe pământ.", "Era un vânător puternic înaintea DOMNULUI. De aceea se spune: „Ca Nimrod, vânător puternic înaintea DOMNULUI.”", "Începutul împărăției lui a fost Babel, Erec, Acad și Calne, în țara Șinear.", "Din țara aceea a ieșit în Asiria și a construit Ninive, Rehobot-Ir și Calah,", "precum și Resen, între Ninive și Calah; aceasta este cetatea cea mare.", "Mițraim a devenit tatăl ludimilor, anamimilor, lehabimilor, naftuhimilor,", "patrusimilor, casluhimilor — din care au ieșit filistenii — și caftorimilor.", "Canaan a devenit tatăl lui Sidon, întâiul său născut, și al lui Het,", "precum și al iebusiților, amoriților, ghirgașiților,", "hiviților, archiților, siniților,", "arvadiților, țemariților și hamatiților. După aceea, familiile canaaniților s-au răspândit.", "Hotarul canaaniților se întindea de la Sidon, în direcția Gherarului, până la Gaza, apoi în direcția Sodomei, Gomorei, Admei și Țeboimului, până la Lașa.", "Aceștia sunt fiii lui Ham, după familiile lor, după limbile lor, în țările și națiunile lor.", "Și lui Sem, fratele mai mare al lui Iafet și tatăl tuturor fiilor lui Eber, i s-au născut fii.", "Fiii lui Sem au fost: Elam, Așur, Arpacșad, Lud și Aram.", "Fiii lui Aram au fost: Uț, Hul, Gheter și Maș.", "Arpacșad a devenit tatăl lui Șelah, iar Șelah a devenit tatăl lui Eber.", "Lui Eber i s-au născut doi fii. Numele unuia era Peleg, pentru că în zilele lui s-a împărțit pământul, iar numele fratelui său era Ioctan.", "Ioctan a devenit tatăl lui Almodad, Șelef, Hațarmavet, Ierah,", "Hadoram, Uzal, Dicla,", "Obal, Abimael, Șeba,", "Ofir, Havila și Iobab. Toți aceștia au fost fiii lui Ioctan.", "Locuințele lor se întindeau de la Meșa, în direcția Sefarului, până la muntele de la răsărit.", "Aceștia sunt fiii lui Sem, după familiile lor, după limbile lor, în țările și națiunile lor.", "Acestea sunt familiile fiilor lui Noe, după generațiile și națiunile lor. Din aceștia s-au răspândit națiunile pe pământ după potop."],
    11: ["Întregul pământ avea o singură limbă și aceleași cuvinte.", "În timp ce călătoreau spre răsărit, au găsit o câmpie în țara Șinear și s-au așezat acolo.", "Și-au spus unul altuia: „Haideți să facem cărămizi și să le ardem bine.” Cărămida le-a slujit drept piatră, iar bitumul drept mortar.", "Apoi au spus: „Haideți să ne construim o cetate și un turn cu vârful până la ceruri și să ne facem un nume, ca să nu fim împrăștiați pe suprafața întregului pământ.”", "DOMNUL a coborât să vadă cetatea și turnul pe care le construiau fiii oamenilor.", "DOMNUL a spus: „Iată, sunt un singur popor și toți au o singură limbă. Acesta este doar începutul a ceea ce vor face; de acum, nimic din ceea ce își propun nu le va fi cu neputință.", "Haideți să coborâm și să le încurcăm acolo limba, ca să nu mai înțeleagă unul vorbirea celuilalt.”", "Astfel, DOMNUL i-a împrăștiat de acolo pe suprafața întregului pământ, iar ei au încetat să construiască cetatea.", "De aceea cetatea a fost numită Babel, pentru că acolo DOMNUL a încurcat limba întregului pământ și de acolo DOMNUL i-a împrăștiat pe suprafața întregului pământ.", "Aceasta este istoria urmașilor lui Sem. Sem avea o sută de ani când a devenit tatăl lui Arpacșad, la doi ani după potop.", "După nașterea lui Arpacșad, Sem a mai trăit cinci sute de ani și a avut fii și fiice.", "Arpacșad a trăit treizeci și cinci de ani și a devenit tatăl lui Șelah.", "După nașterea lui Șelah, Arpacșad a mai trăit patru sute trei ani și a avut fii și fiice.", "Șelah a trăit treizeci de ani și a devenit tatăl lui Eber.", "După nașterea lui Eber, Șelah a mai trăit patru sute trei ani și a avut fii și fiice.", "Eber a trăit treizeci și patru de ani și a devenit tatăl lui Peleg.", "După nașterea lui Peleg, Eber a mai trăit patru sute treizeci de ani și a avut fii și fiice.", "Peleg a trăit treizeci de ani și a devenit tatăl lui Reu.", "După nașterea lui Reu, Peleg a mai trăit două sute nouă ani și a avut fii și fiice.", "Reu a trăit treizeci și doi de ani și a devenit tatăl lui Serug.", "După nașterea lui Serug, Reu a mai trăit două sute șapte ani și a avut fii și fiice.", "Serug a trăit treizeci de ani și a devenit tatăl lui Nahor.", "După nașterea lui Nahor, Serug a mai trăit două sute de ani și a avut fii și fiice.", "Nahor a trăit douăzeci și nouă de ani și a devenit tatăl lui Terah.", "După nașterea lui Terah, Nahor a mai trăit o sută nouăsprezece ani și a avut fii și fiice.", "Terah a trăit șaptezeci de ani și a devenit tatăl lui Avram, Nahor și Haran.", "Aceasta este istoria urmașilor lui Terah. Terah a devenit tatăl lui Avram, Nahor și Haran, iar Haran a devenit tatăl lui Lot.", "Haran a murit în țara în care se născuse, în Urul caldeenilor, pe când tatăl său, Terah, era încă în viață.", "Avram și Nahor și-au luat soții. Numele soției lui Avram era Sarai, iar numele soției lui Nahor era Milca, fiica lui Haran, tatăl Milcăi și al Iscăi.", "Sarai era stearpă și nu avea copii.", "Terah i-a luat pe fiul său Avram, pe Lot, fiul lui Haran și nepotul său, și pe nora sa Sarai, soția fiului său Avram. Au ieșit împreună din Urul caldeenilor ca să meargă în țara Canaanului, dar au ajuns la Haran și s-au așezat acolo.", "Zilele lui Terah au fost de două sute cinci ani; apoi Terah a murit în Haran."],
    12: ["DOMNUL i-a spus lui Avram: „Pleacă din țara ta, din rudenia ta și din casa tatălui tău și mergi în țara pe care ți-o voi arăta.", "Voi face din tine o națiune mare, te voi binecuvânta și îți voi face numele mare. Fii o binecuvântare!", "Îi voi binecuvânta pe cei care te binecuvântează, iar pe cel care te disprețuiește îl voi blestema. Prin tine vor fi binecuvântate toate familiile pământului.”", "Avram a plecat așa cum îi spusese DOMNUL, iar Lot a mers cu el. Avram avea șaptezeci și cinci de ani când a plecat din Haran.", "Avram a luat-o pe Sarai, soția lui, pe Lot, fiul fratelui său, toate bunurile pe care le strânseseră și oamenii pe care îi dobândiseră în Haran. Au plecat ca să meargă în țara Canaanului și au ajuns în țara Canaanului.", "Avram a străbătut țara până la locul numit Sihem, la stejarul lui More. În vremea aceea, canaaniții erau în țară.", "DOMNUL i S-a arătat lui Avram și a spus: „Urmașilor tăi le voi da țara aceasta.” Avram a construit acolo un altar DOMNULUI, care i Se arătase.", "De acolo a mers spre muntele aflat la răsărit de Betel și și-a întins cortul, având Betelul la apus și Aiul la răsărit. A construit acolo un altar DOMNULUI și a chemat Numele DOMNULUI.", "Apoi Avram și-a continuat călătoria, mergând din popas în popas spre Neghev.", "În țară a venit o foamete. Avram a coborât în Egipt ca să locuiască acolo ca străin, pentru că foametea era grea în țară.", "Când s-a apropiat să intre în Egipt, i-a spus soției sale, Sarai: „Iată, știu că ești o femeie frumoasă la înfățișare.", "Când te vor vedea egiptenii, vor spune: «Aceasta este soția lui.» Atunci pe mine mă vor ucide, iar pe tine te vor lăsa în viață.", "Te rog, spune că ești sora mea, ca să-mi fie bine datorită ție și să rămân în viață prin tine.”", "Când Avram a intrat în Egipt, egiptenii au văzut că femeia era foarte frumoasă.", "Dregătorii faraonului au văzut-o și au lăudat-o înaintea faraonului, iar femeia a fost luată în casa faraonului.", "El s-a purtat bine cu Avram datorită ei, iar Avram a primit oi, vite, măgari, slujitori, slujitoare, măgărițe și cămile.", "Dar DOMNUL a lovit cu urgii mari pe faraon și casa lui din cauza lui Sarai, soția lui Avram.", "Faraonul l-a chemat pe Avram și i-a spus: „Ce mi-ai făcut? De ce nu mi-ai spus că este soția ta?", "De ce ai spus: «Este sora mea», astfel încât am luat-o ca soție? Acum, iată-ți soția! Ia-o și pleacă!”", "Faraonul le-a dat oamenilor săi porunci cu privire la Avram, iar ei l-au însoțit afară împreună cu soția lui și cu tot ce avea."],
    13: ["Avram a urcat din Egipt spre Neghev, el, soția lui și tot ce avea, iar Lot era împreună cu el.", "Avram era foarte bogat în vite, argint și aur.", "Din Neghev a mers din popas în popas până la Betel, la locul unde îi fusese cortul la început, între Betel și Ai,", "la locul altarului pe care îl construise acolo mai înainte. Acolo Avram a chemat Numele DOMNULUI.", "Și Lot, care mergea împreună cu Avram, avea turme, cirezi și corturi.", "Țara nu-i putea cuprinde ca să locuiască împreună, pentru că averile lor erau atât de mari, încât nu puteau locui împreună.", "S-a iscat o ceartă între păstorii vitelor lui Avram și păstorii vitelor lui Lot. În vremea aceea, canaaniții și fereziții locuiau în țară.", "Avram i-a spus lui Lot: „Te rog, să nu fie ceartă între mine și tine și între păstorii mei și păstorii tăi, pentru că suntem rude.", "Nu este întreaga țară înaintea ta? Te rog, desparte-te de mine. Dacă mergi la stânga, eu voi merge la dreapta; iar dacă mergi la dreapta, eu voi merge la stânga.”", "Lot și-a ridicat ochii și a văzut că întreaga câmpie a Iordanului era bine udată pretutindeni. Înainte ca DOMNUL să distrugă Sodoma și Gomora, ea era ca grădina DOMNULUI și ca țara Egiptului, în direcția Țoarului.", "Lot și-a ales întreaga câmpie a Iordanului și a plecat spre răsărit. Astfel, s-au despărțit unul de celălalt.", "Avram a locuit în țara Canaanului, iar Lot a locuit în cetățile câmpiei și și-a mutat corturile până aproape de Sodoma.", "Oamenii din Sodoma erau foarte răi și mari păcătoși împotriva DOMNULUI.", "După ce Lot s-a despărțit de el, DOMNUL i-a spus lui Avram: „Ridică-ți ochii și privește din locul în care ești spre nord, spre sud, spre răsărit și spre apus,", "pentru că toată țara pe care o vezi ți-o voi da ție și urmașilor tăi pentru totdeauna.", "Îți voi face urmașii asemenea pulberii pământului, astfel încât, dacă cineva poate număra pulberea pământului, atunci și urmașii tăi vor putea fi numărați.", "Ridică-te și străbate țara în lungimea și în lățimea ei, pentru că ție ți-o voi da.”", "Avram și-a mutat corturile, a venit și a locuit lângă stejarii lui Mamre, care sunt în Hebron, și a construit acolo un altar DOMNULUI."],
    14: ["În zilele lui Amrafel, regele Șinearului, ale lui Arioc, regele Elasarului, ale lui Chedorlaomer, regele Elamului, și ale lui Tidal, regele Goiimului,", "aceștia au făcut război cu Bera, regele Sodomei, cu Birșa, regele Gomorei, cu Șinab, regele Admei, cu Șemeber, regele Țeboimului, și cu regele Belei, adică Țoar.", "Toți aceștia s-au adunat în Valea Sidim, adică Marea Sărată.", "Timp de doisprezece ani îi slujiseră lui Chedorlaomer, dar în al treisprezecelea an s-au răzvrătit.", "În al paisprezecelea an, Chedorlaomer și regii care erau cu el au venit și i-au învins pe refaimi la Așterot-Carnaim, pe zuzimi la Ham și pe emimi la Șave-Chiriataim,", "iar pe horiți în muntele lor Seir, până la El-Paran, care este lângă pustiu.", "Apoi s-au întors și au venit la En-Mișpat, adică Cades, și au lovit întregul ținut al amaleciților, precum și pe amoriții care locuiau în Hațațon-Tamar.", "Atunci regele Sodomei, regele Gomorei, regele Admei, regele Țeboimului și regele Belei, adică Țoar, au ieșit și s-au așezat în linie de luptă în Valea Sidim", "împotriva lui Chedorlaomer, regele Elamului, a lui Tidal, regele Goiimului, a lui Amrafel, regele Șinearului, și a lui Arioc, regele Elasarului: patru regi împotriva a cinci.", "Valea Sidim era plină de puțuri de bitum. Regii Sodomei și Gomorei au fugit și au căzut acolo, iar cei rămași au fugit spre munți.", "Biruitorii au luat toate bunurile Sodomei și Gomorei, precum și toată hrana lor, și au plecat.", "L-au luat și pe Lot, fiul fratelui lui Avram, care locuia în Sodoma, împreună cu bunurile lui, și au plecat.", "Un fugar a venit și i-a dat de veste lui Avram, evreul. Avram locuia atunci lângă stejarii lui Mamre, amoritul, fratele lui Eșcol și al lui Aner. Aceștia erau aliații lui Avram.", "Când Avram a auzit că ruda lui fusese luată captivă, i-a mobilizat pe cei trei sute optsprezece oameni instruiți, născuți în casa lui, și i-a urmărit pe dușmani până la Dan.", "Noaptea, și-a împărțit oamenii împotriva lor, el și slujitorii lui, i-a lovit și i-a urmărit până la Hoba, care este la nord de Damasc.", "A adus înapoi toate bunurile. L-a adus înapoi și pe ruda lui, Lot, împreună cu bunurile lui, cu femeile și cu ceilalți oameni.", "După ce Avram s-a întors de la înfrângerea lui Chedorlaomer și a regilor care erau cu el, regele Sodomei i-a ieșit în întâmpinare în Valea Șave, adică Valea Regelui.", "Melchisedec, regele Salemului, a adus pâine și vin. El era preot al Dumnezeului Preaînalt.", "Melchisedec l-a binecuvântat și a spus: „Binecuvântat să fie Avram de Dumnezeul Preaînalt, Stăpânul cerurilor și al pământului!", "Și binecuvântat să fie Dumnezeul Preaînalt, care i-a dat pe dușmanii tăi în mâna ta!” Iar Avram i-a dat a zecea parte din toate.", "Regele Sodomei i-a spus lui Avram: „Dă-mi oamenii, iar bunurile păstrează-le pentru tine.”", "Avram i-a spus regelui Sodomei: „Mi-am ridicat mâna către DOMNUL, Dumnezeul Preaînalt, Stăpânul cerurilor și al pământului,", "că nu voi lua nici măcar un fir, nici o curea de sandală și nimic din ce este al tău, ca să nu poți spune: «Eu l-am îmbogățit pe Avram.»", "Nu voi lua nimic, în afară de ceea ce au mâncat tinerii și de partea bărbaților care au mers cu mine: Aner, Eșcol și Mamre. Ei să-și ia partea.”"],
    15: ["După aceste lucruri, cuvântul DOMNULUI a venit la Avram într-o vedenie: „Nu te teme, Avram! Eu sunt scutul tău; răsplata ta va fi nespus de mare.”", "Avram a spus: „Stăpâne DOMNULE, ce-mi vei da, de vreme ce rămân fără copii, iar administratorul casei mele este Eliezer din Damasc?”", "Avram a mai spus: „Iată, nu mi-ai dat niciun urmaș și, iată, un om născut în casa mea va fi moștenitorul meu.”", "Atunci cuvântul DOMNULUI a venit la el: „Nu acesta va fi moștenitorul tău, ci cel care va ieși din tine va fi moștenitorul tău.”", "DOMNUL l-a dus afară și i-a spus: „Privește spre cer și numără stelele, dacă le poți număra.” Apoi i-a spus: „Așa vor fi urmașii tăi.”", "Avram a crezut în DOMNUL, iar DOMNUL i-a socotit aceasta ca dreptate.", "DOMNUL i-a spus: „Eu sunt DOMNUL, care te-am scos din Urul caldeenilor ca să-ți dau țara aceasta s-o moștenești.”", "Avram a întrebat: „Stăpâne DOMNULE, prin ce voi ști că o voi moșteni?”", "DOMNUL i-a spus: „Adu-Mi o juncană de trei ani, o capră de trei ani, un berbec de trei ani, o turturică și un pui de porumbel.”", "Avram I le-a adus pe toate, le-a despicat pe mijloc și a așezat fiecare jumătate în fața celeilalte, dar păsările nu le-a despicat.", "Păsările de pradă s-au coborât peste trupurile moarte, însă Avram le-a alungat.", "Când soarele era pe cale să apună, peste Avram a căzut un somn adânc și, iată, l-au cuprins o spaimă și un întuneric mare.", "DOMNUL i-a spus lui Avram: „Să știi sigur că urmașii tăi vor locui ca străini într-o țară care nu va fi a lor. Le vor sluji, iar aceștia îi vor asupri patru sute de ani.", "Dar Eu voi judeca națiunea căreia îi vor sluji, iar după aceea vor ieși cu mari bogății.", "Tu vei merge în pace la părinții tăi și vei fi îngropat la o bătrânețe fericită.", "În a patra generație se vor întoarce aici, pentru că nelegiuirea amoriților nu a ajuns încă la măsura deplină.”", "După ce soarele a apus și s-a făcut întuneric, iată, un cuptor fumegând și o torță aprinsă au trecut printre bucățile acelea.", "În ziua aceea, DOMNUL a încheiat un legământ cu Avram și a spus: „Urmașilor tăi le-am dat țara aceasta, de la râul Egiptului până la râul cel mare, râul Eufrat:", "țara cheniților, a cheniziților, a cadmoniților,", "a hetiților, a fereziților, a refaimilor,", "a amoriților, a canaaniților, a ghirgașiților și a iebusiților.”"],
    16: ["Sarai, soția lui Avram, nu îi născuse copii. Ea avea o slujitoare egipteancă, al cărei nume era Agar.", "Sarai i-a spus lui Avram: „Iată, DOMNUL m-a împiedicat să nasc. Te rog, intră la slujitoarea mea; poate că voi avea copii prin ea.” Avram a ascultat glasul lui Sarai.", "După ce Avram locuise zece ani în țara Canaanului, Sarai, soția lui Avram, a luat-o pe Agar, egipteanca, slujitoarea ei, și i-a dat-o de soție lui Avram, soțul ei.", "El a intrat la Agar, iar ea a rămas însărcinată. Când a văzut că rămăsese însărcinată, stăpâna ei a ajuns disprețuită în ochii ei.", "Sarai i-a spus lui Avram: „Nedreptatea făcută mie să cadă asupra ta! Eu am dat-o pe slujitoarea mea în brațele tale, iar când a văzut că a rămas însărcinată, m-a disprețuit. DOMNUL să judece între mine și tine.”", "Avram i-a răspuns lui Sarai: „Iată, slujitoarea ta este în mâna ta. Fă-i ce crezi de cuviință.” Sarai s-a purtat aspru cu ea, iar Agar a fugit dinaintea ei.", "Îngerul DOMNULUI a găsit-o lângă un izvor de apă în pustiu, lângă izvorul de pe drumul spre Șur.", "El a spus: „Agar, slujitoarea lui Sarai, de unde vii și unde te duci?” Ea a răspuns: „Fug dinaintea stăpânei mele, Sarai.”", "Îngerul DOMNULUI i-a spus: „Întoarce-te la stăpâna ta și supune-te sub mâna ei.”", "Îngerul DOMNULUI i-a mai spus: „Îți voi înmulți atât de mult urmașii, încât nu vor putea fi numărați din cauza mulțimii lor.”", "Îngerul DOMNULUI i-a spus: „Iată, ești însărcinată și vei naște un fiu. Îi vei pune numele Ismael, pentru că DOMNUL a auzit suferința ta.", "El va fi un om asemenea măgarului sălbatic. Mâna lui va fi împotriva tuturor, iar mâna tuturor va fi împotriva lui. Va locui în fața tuturor fraților săi.”", "Ea L-a numit pe DOMNUL, care îi vorbise: „Tu ești Dumnezeul care mă vede”, pentru că a spus: „Oare chiar L-am văzut aici pe Cel care mă vede?”", "De aceea fântâna a fost numită Beer-Lahai-Roi. Iată, ea este între Cades și Bered.", "Agar i-a născut lui Avram un fiu, iar Avram i-a pus fiului pe care i-l născuse Agar numele Ismael.", "Avram avea optzeci și șase de ani când Agar i l-a născut pe Ismael."],
    17: ["Când Avram avea nouăzeci și nouă de ani, DOMNUL i S-a arătat și i-a spus: „Eu sunt Dumnezeul Atotputernic. Umblă înaintea Mea și fii integru.", "Voi așeza legământul Meu între Mine și tine și te voi înmulți nespus de mult.”", "Avram a căzut cu fața la pământ, iar Dumnezeu i-a vorbit:", "„Cât despre Mine, iată, legământul Meu este cu tine: vei fi tatăl unei mulțimi de națiuni.", "Nu te vei mai numi Avram, ci numele tău va fi Avraam, pentru că te-am făcut tatăl unei mulțimi de națiuni.", "Te voi face nespus de roditor, voi face din tine națiuni, iar din tine vor ieși regi.", "Voi întemeia legământul Meu între Mine și tine și urmașii tăi după tine, de-a lungul generațiilor lor, ca legământ veșnic, ca să fiu Dumnezeul tău și al urmașilor tăi după tine.", "Îți voi da ție și urmașilor tăi după tine țara în care locuiești ca străin, toată țara Canaanului, ca stăpânire veșnică, și Eu voi fi Dumnezeul lor.”", "Dumnezeu i-a mai spus lui Avraam: „Cât despre tine, să păzești legământul Meu, tu și urmașii tăi după tine, de-a lungul generațiilor lor.", "Acesta este legământul Meu pe care să-l păziți între Mine și voi și urmașii tăi după tine: orice persoană de parte bărbătească dintre voi să fie circumcisă.", "Să fiți circumciși în carnea prepuțului vostru, iar acesta va fi semnul legământului dintre Mine și voi.", "La vârsta de opt zile, orice persoană de parte bărbătească dintre voi să fie circumcisă de-a lungul generațiilor voastre, atât cel născut în casă, cât și cel cumpărat cu bani de la orice străin care nu este dintre urmașii tăi.", "Atât cel născut în casa ta, cât și cel cumpărat cu banii tăi trebuie să fie circumcis. Legământul Meu va fi în carnea voastră ca legământ veșnic.", "Orice persoană de parte bărbătească necircumcisă, a cărei carne a prepuțului nu a fost circumcisă, va fi înlăturată dintre ai săi; a încălcat legământul Meu.”", "Dumnezeu i-a spus lui Avraam: „Cât despre Sarai, soția ta, să nu o mai numești Sarai, ci numele ei va fi Sara.", "O voi binecuvânta și, mai mult, îți voi da un fiu prin ea. O voi binecuvânta și din ea vor veni națiuni; din ea vor ieși regi ai unor popoare.”", "Atunci Avraam a căzut cu fața la pământ, a râs și a spus în inima lui: „I se va naște oare un copil unui om de o sută de ani? Și Sara, care are nouăzeci de ani, va naște?”", "Avraam I-a spus lui Dumnezeu: „O, de ar trăi Ismael înaintea Ta!”", "Dumnezeu a spus: „Nu, ci Sara, soția ta, îți va naște un fiu, iar tu îi vei pune numele Isaac. Voi întemeia legământul Meu cu el ca legământ veșnic pentru urmașii lui după el.", "Cât despre Ismael, te-am ascultat. Iată, l-am binecuvântat, îl voi face roditor și îl voi înmulți nespus de mult. Va deveni tatăl a doisprezece conducători și voi face din el o națiune mare.", "Dar legământul Meu îl voi întemeia cu Isaac, pe care Sara ți-l va naște la vremea stabilită, anul viitor.”", "Când a terminat de vorbit cu el, Dumnezeu S-a înălțat de la Avraam.", "În aceeași zi, Avraam i-a luat pe Ismael, fiul său, pe toți cei născuți în casa lui și pe toți cei cumpărați cu banii lui, orice persoană de parte bărbătească dintre oamenii casei lui Avraam, și le-a circumcis carnea prepuțului, așa cum îi spusese Dumnezeu.", "Avraam avea nouăzeci și nouă de ani când i-a fost circumcisă carnea prepuțului.", "Ismael, fiul său, avea treisprezece ani când i-a fost circumcisă carnea prepuțului.", "În aceeași zi au fost circumciși Avraam și Ismael, fiul său.", "Toți bărbații casei lui, atât cei născuți în casă, cât și cei cumpărați cu bani de la străini, au fost circumciși împreună cu el."],
    18: ["DOMNUL i S-a arătat lui Avraam lângă stejarii lui Mamre, pe când el stătea la intrarea cortului în arșița zilei.", "Avraam și-a ridicat ochii, a privit și, iată, trei bărbați stăteau aproape de el. Când i-a văzut, a alergat de la intrarea cortului ca să-i întâmpine și s-a plecat până la pământ.", "El a spus: „Stăpâne, dacă am găsit bunăvoință în ochii Tăi, te rog, nu trece pe lângă slujitorul Tău.", "Să se aducă puțină apă, să vă spălați picioarele și să vă odihniți sub copac.", "Voi aduce o bucată de pâine, ca să vă întăriți inimile; după aceea vă veți continua drumul, fiindcă de aceea ați trecut pe la slujitorul vostru.” Ei au spus: „Fă așa cum ai spus.”", "Avraam s-a grăbit să intre în cort la Sara și a spus: „Ia repede trei măsuri de făină fină, frământă și fă turte.”", "Avraam a alergat la cireadă, a luat un vițel fraged și bun și l-a dat slujitorului, care s-a grăbit să-l pregătească.", "Apoi a luat lapte prins, lapte proaspăt și vițelul pe care îl pregătise și le-a pus înaintea lor. El a stat lângă ei, sub copac, în timp ce ei mâncau.", "Ei l-au întrebat: „Unde este Sara, soția ta?” El a răspuns: „Acolo, în cort.”", "Unul dintre ei a spus: „Mă voi întoarce negreșit la tine pe vremea aceasta, anul viitor, și, iată, Sara, soția ta, va avea un fiu.” Sara asculta la intrarea cortului, în spatele lui.", "Avraam și Sara erau bătrâni și înaintați în vârstă, iar Sara trecuse de vârsta la care femeile pot avea copii.", "Sara a râs în sinea ei și a spus: „Acum, când am îmbătrânit, voi mai avea oare această plăcere? Și stăpânul meu este bătrân.”", "DOMNUL i-a spus lui Avraam: „De ce a râs Sara și a spus: «Oare voi mai naște cu adevărat, acum că am îmbătrânit?»", "Este ceva prea greu pentru DOMNUL? La vremea stabilită Mă voi întoarce la tine, pe vremea aceasta, anul viitor, iar Sara va avea un fiu.”", "Sara a tăgăduit și a spus: „Nu am râs”, pentru că îi era frică. Dar El a spus: „Ba da, ai râs.”", "Bărbații s-au ridicat de acolo și au privit spre Sodoma, iar Avraam a mers împreună cu ei ca să-i conducă.", "DOMNUL a spus: „Să ascund Eu oare de Avraam ceea ce urmează să fac,", "de vreme ce Avraam va deveni cu siguranță o națiune mare și puternică, iar prin el vor fi binecuvântate toate națiunile pământului?", "Căci l-am ales ca să le poruncească fiilor săi și casei sale după el să păzească drumul DOMNULUI, făcând dreptate și judecată, astfel încât DOMNUL să împlinească pentru Avraam ceea ce i-a promis.”", "DOMNUL a spus: „Strigătul împotriva Sodomei și Gomorei este mare, iar păcatul lor este foarte greu.", "Voi coborî acum să văd dacă purtarea lor corespunde întru totul strigătului care a ajuns la Mine; iar dacă nu, voi ști.”", "Bărbații s-au întors de acolo și au mers spre Sodoma, dar Avraam a rămas înaintea DOMNULUI.", "Avraam s-a apropiat și a spus: „Îl vei nimici oare pe cel drept împreună cu cel rău?", "Poate că sunt cincizeci de oameni drepți în cetate. O vei nimici și nu vei cruța locul de dragul celor cincizeci de oameni drepți care sunt în el?", "Departe de Tine să faci un astfel de lucru: să-l omori pe cel drept împreună cu cel rău, astfel încât celui drept să-i fie ca celui rău! Departe de Tine! Judecătorul întregului pământ nu va face oare dreptate?”", "DOMNUL a spus: „Dacă voi găsi în Sodoma cincizeci de oameni drepți în cetate, voi cruța întregul loc de dragul lor.”", "Avraam a răspuns: „Iată, am îndrăznit să vorbesc Stăpânului, deși sunt pulbere și cenușă.", "Poate că din cei cincizeci de oameni drepți vor lipsi cinci. Vei distruge întreaga cetate din cauza celor cinci?” El a spus: „Nu o voi distruge dacă voi găsi acolo patruzeci și cinci.”", "Avraam I-a vorbit din nou și a spus: „Poate că se vor găsi acolo patruzeci.” El a răspuns: „Nu o voi face de dragul celor patruzeci.”", "Avraam a spus: „Te rog, să nu Se mânie Stăpânul și voi mai vorbi. Poate că se vor găsi acolo treizeci.” El a răspuns: „Nu o voi face dacă voi găsi acolo treizeci.”", "Avraam a spus: „Iată, am îndrăznit să vorbesc Stăpânului. Poate că se vor găsi acolo douăzeci.” El a răspuns: „Nu o voi distruge de dragul celor douăzeci.”", "Avraam a spus: „Te rog, să nu Se mânie Stăpânul și voi mai vorbi numai de data aceasta. Poate că se vor găsi acolo zece.” El a răspuns: „Nu o voi distruge de dragul celor zece.”", "După ce a terminat de vorbit cu Avraam, DOMNUL a plecat, iar Avraam s-a întors la locul său."],
    19: ["Cei doi îngeri au ajuns la Sodoma seara. Lot stătea la poarta Sodomei. Când i-a văzut, Lot s-a ridicat ca să-i întâmpine și s-a plecat cu fața la pământ.", "El a spus: „Vă rog, domnii mei, veniți în casa slujitorului vostru, rămâneți peste noapte și spălați-vă picioarele. Apoi vă veți scula dis-de-dimineață și vă veți continua drumul.” Ei au răspuns: „Nu, ci vom rămâne peste noapte în piață.”", "Dar Lot a stăruit mult, iar ei au venit cu el și au intrat în casa lui. El le-a pregătit un ospăț, a copt azime și ei au mâncat.", "Înainte să se culce, oamenii cetății, oamenii Sodomei, au înconjurat casa, de la tânăr până la bătrân, tot poporul, din toate părțile.", "L-au strigat pe Lot și i-au spus: „Unde sunt bărbații care au venit la tine în noaptea aceasta? Scoate-i la noi ca să avem relații sexuale cu ei.”", "Lot a ieșit la ei la intrare și a închis ușa în urma lui.", "El a spus: „Vă rog, frații mei, nu faceți un asemenea rău!", "Iată, am două fiice care nu au avut relații cu vreun bărbat. Vă rog, lăsați-mă să vi le aduc și faceți-le ce vi se pare bine. Numai acestor bărbați să nu le faceți nimic, pentru că au intrat sub adăpostul acoperișului meu.”", "Ei au spus: „Dă-te la o parte!” Apoi au spus: „Omul acesta a venit să locuiască aici ca străin și acum vrea să fie judecător! Îți vom face ție mai rău decât lor.” L-au împins cu putere pe Lot și s-au apropiat ca să spargă ușa.", "Dar bărbații și-au întins mâinile, l-au tras pe Lot în casă la ei și au închis ușa.", "I-au lovit cu orbire pe oamenii care erau la intrarea casei, de la cel mai mic până la cel mai mare, astfel încât aceștia au obosit căutând intrarea.", "Bărbații i-au spus lui Lot: „Mai ai pe cineva aici? Gineri, fii, fiice sau pe oricine mai ai în cetate — scoate-i din locul acesta,", "pentru că noi vom distruge locul acesta. Strigătul împotriva locuitorilor lui a ajuns atât de mare înaintea DOMNULUI, încât DOMNUL ne-a trimis să-l distrugem.”", "Lot a ieșit și le-a vorbit ginerilor săi, cei care urmau să le ia de soții pe fiicele lui, și le-a spus: „Ridicați-vă și ieșiți din locul acesta, pentru că DOMNUL va distruge cetatea!” Dar ginerilor lui li s-a părut că glumește.", "Când s-au ivit zorile, îngerii l-au grăbit pe Lot și au spus: „Ridică-te! Ia-ți soția și cele două fiice care sunt aici, ca să nu pieri din cauza nelegiuirii cetății.”", "Dar el întârzia. Atunci bărbații l-au apucat de mână pe el, pe soția lui și pe cele două fiice ale lui, pentru că DOMNUL avea milă de el. L-au scos și l-au așezat în afara cetății.", "După ce i-au scos afară, unul dintre ei a spus: „Fugi ca să-ți salvezi viața! Nu privi înapoi și nu te opri nicăieri în câmpie. Fugi la munte, ca să nu pieri!”", "Lot le-a spus: „Nu așa, te rog, Stăpâne!", "Iată, slujitorul Tău a găsit bunăvoință în ochii Tăi și ai arătat o mare îndurare față de mine, salvându-mi viața. Dar eu nu pot fugi la munte, ca nu cumva nenorocirea să mă ajungă și să mor.", "Iată, cetatea aceasta este destul de aproape ca să fug acolo și este mică. Te rog, lasă-mă să fug acolo — nu este ea mică? — și voi rămâne în viață.”", "El i-a spus: „Iată, îți împlinesc și această cerere și nu voi răsturna cetatea despre care ai vorbit.", "Grăbește-te și fugi acolo, pentru că nu pot face nimic până când nu ajungi.” De aceea cetatea a fost numită Țoar.", "Soarele răsărise peste pământ când Lot a ajuns la Țoar.", "Atunci DOMNUL a făcut să plouă peste Sodoma și Gomora sulf și foc de la DOMNUL, din cer.", "A răsturnat cetățile acelea, întreaga câmpie, pe toți locuitorii cetăților și tot ce creștea din pământ.", "Dar soția lui Lot, care venea în urma lui, a privit înapoi și a devenit un stâlp de sare.", "Avraam s-a sculat dis-de-dimineață și s-a dus la locul unde stătuse înaintea DOMNULUI.", "A privit spre Sodoma și Gomora și spre întregul ținut al câmpiei și a văzut că fumul țării se ridica asemenea fumului unui cuptor.", "Când Dumnezeu a distrus cetățile câmpiei, Și-a adus aminte de Avraam și l-a scos pe Lot din mijlocul distrugerii, când a răsturnat cetățile în care locuise Lot.", "Lot a urcat din Țoar și a locuit la munte împreună cu cele două fiice ale lui, pentru că se temea să locuiască în Țoar. A locuit într-o peșteră împreună cu cele două fiice ale lui.", "Fiica întâi născută i-a spus celei mai tinere: „Tatăl nostru este bătrân și nu este niciun bărbat în țara aceasta care să intre la noi după obiceiul întregului pământ.", "Haide să-i dăm tatălui nostru să bea vin și să ne culcăm cu el, ca să păstrăm urmași din tatăl nostru.”", "În noaptea aceea i-au dat tatălui lor să bea vin, iar cea întâi născută a intrat și s-a culcat cu tatăl ei. El nu a știut când s-a culcat ea, nici când s-a ridicat.", "A doua zi, cea întâi născută i-a spus celei mai tinere: „Iată, noaptea trecută m-am culcat cu tatăl meu. Să-i dăm să bea vin și în noaptea aceasta, apoi intră și culcă-te cu el, ca să păstrăm urmași din tatăl nostru.”", "Și în noaptea aceea i-au dat tatălui lor să bea vin. Cea mai tânără s-a dus și s-a culcat cu el. El nu a știut când s-a culcat ea, nici când s-a ridicat.", "Astfel, amândouă fiicele lui Lot au rămas însărcinate de la tatăl lor.", "Cea întâi născută a născut un fiu și i-a pus numele Moab. El este strămoșul moabiților de astăzi.", "Cea mai tânără a născut și ea un fiu și i-a pus numele Ben-Ami. El este strămoșul amoniților de astăzi."],
    20: ["Avraam a plecat de acolo spre ținutul Neghevului, a locuit între Cades și Șur și a trăit ca străin în Gherar.", "Avraam a spus despre Sara, soția lui: „Este sora mea.” Atunci Abimelec, regele Gherarului, a trimis să fie luată Sara.", "Dar Dumnezeu a venit la Abimelec într-un vis, noaptea, și i-a spus: „Iată, ești ca și mort din cauza femeii pe care ai luat-o, pentru că este soția unui bărbat.”", "Abimelec nu se apropiase de ea. El a spus: „Stăpâne, vei ucide chiar și o națiune dreaptă?", "Nu mi-a spus el: «Este sora mea»? Și chiar ea a spus: «Este fratele meu.» Am făcut aceasta cu inimă integră și cu mâini nevinovate.”", "Dumnezeu i-a spus în vis: „Da, știu că ai făcut aceasta cu inimă integră. Tot Eu te-am oprit să păcătuiești împotriva Mea; de aceea nu ți-am îngăduit să te atingi de ea.", "Acum, dă-i omului soția înapoi, pentru că el este profet și se va ruga pentru tine, iar tu vei trăi. Dar dacă nu i-o dai înapoi, să știi sigur că vei muri, tu și toți ai tăi.”", "Abimelec s-a sculat dis-de-dimineață, i-a chemat pe toți slujitorii lui și le-a spus toate aceste lucruri. Oamenii s-au temut foarte mult.", "Apoi Abimelec l-a chemat pe Avraam și i-a spus: „Ce ne-ai făcut? Cu ce am păcătuit împotriva ta, de ai adus asupra mea și asupra regatului meu un păcat atât de mare? Mi-ai făcut lucruri care nu trebuie făcute!”", "Abimelec i-a mai spus lui Avraam: „Ce ai urmărit când ai făcut lucrul acesta?”", "Avraam a răspuns: „Mi-am spus: «Cu siguranță nu există frică de Dumnezeu în locul acesta și mă vor ucide din cauza soției mele.»", "De altfel, ea este cu adevărat sora mea: este fiica tatălui meu, dar nu fiica mamei mele, și a devenit soția mea.", "Când Dumnezeu m-a făcut să pribegesc departe de casa tatălui meu, i-am spus: «Aceasta este bunătatea pe care să mi-o arăți: oriunde vom merge, spune despre mine: Este fratele meu.»”", "Abimelec a luat oi, vite, slujitori și slujitoare, i le-a dat lui Avraam și i-a dat-o înapoi pe Sara, soția lui.", "Abimelec a spus: „Iată, țara mea este înaintea ta. Locuiește oriunde îți place.”", "Iar Sarei i-a spus: „Iată, i-am dat fratelui tău o mie de arginți. Aceasta îți este o acoperire a ochilor înaintea tuturor celor care sunt cu tine; și înaintea tuturor ai fost îndreptățită.”", "Avraam s-a rugat lui Dumnezeu, iar Dumnezeu i-a vindecat pe Abimelec, pe soția lui și pe slujitoarele lui, astfel încât au putut avea din nou copii.", "Pentru că DOMNUL închisese cu totul orice pântece din casa lui Abimelec din cauza Sarei, soția lui Avraam."],
    21: ["DOMNUL a cercetat-o pe Sara, așa cum spusese, și DOMNUL a făcut pentru Sara ceea ce promisese.", "Sara a rămas însărcinată și i-a născut lui Avraam un fiu la bătrânețe, la vremea hotărâtă despre care îi vorbise Dumnezeu.", "Avraam i-a pus fiului care i se născuse, pe care Sara i-l născuse, numele Isaac.", "Avraam l-a circumcis pe fiul său Isaac când avea opt zile, așa cum îi poruncise Dumnezeu.", "Avraam avea o sută de ani când i s-a născut fiul său Isaac.", "Sara a spus: „Dumnezeu mi-a dat prilej de râs; oricine va auzi va râde împreună cu mine.”", "Și a mai spus: „Cine i-ar fi spus lui Avraam că Sara va alăpta copii? Totuși, i-am născut un fiu la bătrânețe.”", "Copilul a crescut și a fost înțărcat. În ziua înțărcării lui Isaac, Avraam a făcut un ospăț mare.", "Sara l-a văzut râzând pe fiul pe care Agar, egipteanca, i-l născuse lui Avraam.", "Atunci i-a spus lui Avraam: „Alungă această slujitoare și pe fiul ei, pentru că fiul acestei slujitoare nu va moșteni împreună cu fiul meu, cu Isaac.”", "Lucrul acesta l-a mâhnit foarte mult pe Avraam din cauza fiului său.", "Dar Dumnezeu i-a spus lui Avraam: „Să nu te mâhnească lucrul acesta din cauza băiatului și a slujitoarei tale. Ascultă de glasul Sarei în tot ce îți spune, pentru că prin Isaac îți vor purta numele urmașii.", "Dar și din fiul slujitoarei voi face o națiune, pentru că și el este urmașul tău.”", "Avraam s-a sculat dis-de-dimineață, a luat pâine și un burduf cu apă, i le-a dat Agarei, punându-i-le pe umăr, i-a dat copilul și a trimis-o. Ea a plecat și a rătăcit prin pustiul Beer-Șeba.", "Când s-a terminat apa din burduf, ea a așezat copilul sub unul dintre arbuști.", "Apoi s-a dus și s-a așezat în fața lui, la o depărtare de o aruncătură de arc, pentru că spunea: „Să nu văd moartea copilului!” S-a așezat în fața lui, și-a ridicat glasul și a plâns.", "Dumnezeu a auzit glasul băiatului, iar Îngerul lui Dumnezeu a chemat-o pe Agar din cer și i-a spus: „Ce ai, Agar? Nu te teme, pentru că Dumnezeu a auzit glasul băiatului acolo unde este.", "Ridică-te, ia băiatul și ține-l bine de mână, pentru că voi face din el o națiune mare.”", "Dumnezeu i-a deschis ochii și ea a văzut o fântână cu apă. S-a dus, a umplut burduful cu apă și i-a dat băiatului să bea.", "Dumnezeu a fost cu băiatul. El a crescut, a locuit în pustiu și a devenit arcaș.", "A locuit în pustiul Paran, iar mama lui i-a luat o soție din țara Egiptului.", "În vremea aceea, Abimelec și Picol, comandantul armatei lui, i-au spus lui Avraam: „Dumnezeu este cu tine în tot ce faci.", "Acum jură-mi aici, pe Dumnezeu, că nu mă vei înșela nici pe mine, nici pe fiul meu, nici pe urmașul meu, ci te vei purta față de mine și față de țara în care ai locuit ca străin cu aceeași bunătate cu care m-am purtat eu față de tine.”", "Avraam a spus: „Jur.”", "Apoi Avraam i-a cerut socoteală lui Abimelec pentru o fântână cu apă pe care slujitorii lui Abimelec o luaseră cu forța.", "Abimelec a răspuns: „Nu știu cine a făcut lucrul acesta. Nici tu nu mi-ai spus, iar eu am auzit despre el abia astăzi.”", "Avraam a luat oi și vite și i le-a dat lui Abimelec, iar cei doi au încheiat un legământ.", "Avraam a pus deoparte șapte mielușele din turmă.", "Abimelec l-a întrebat pe Avraam: „Ce înseamnă aceste șapte mielușele pe care le-ai pus deoparte?”", "El a răspuns: „Să primești din mâna mea aceste șapte mielușele, ca ele să-mi fie mărturie că eu am săpat fântâna aceasta.”", "De aceea locul acela a fost numit Beer-Șeba, pentru că acolo au jurat amândoi.", "Astfel au încheiat un legământ la Beer-Șeba. Apoi Abimelec și Picol, comandantul armatei lui, s-au ridicat și s-au întors în țara filistenilor.", "Avraam a plantat un tamarisc la Beer-Șeba și acolo a chemat Numele DOMNULUI, Dumnezeul Veșnic.", "Avraam a locuit ca străin în țara filistenilor multe zile."],
    22: ["După aceste lucruri, Dumnezeu l-a pus la încercare pe Avraam și i-a spus: „Avraam!” El a răspuns: „Iată-mă!”", "Dumnezeu a spus: „Ia-l, te rog, pe fiul tău, pe singurul tău fiu, pe Isaac, pe care îl iubești, și mergi în țara Moria. Acolo adu-l ca ardere-de-tot pe unul dintre munții despre care îți voi spune.”", "Avraam s-a sculat dis-de-dimineață, și-a înșeuat măgarul și a luat cu el doi dintre slujitorii săi și pe fiul său Isaac. A despicat lemnele pentru arderea-de-tot, apoi s-a ridicat și a plecat spre locul despre care îi spusese Dumnezeu.", "În a treia zi, Avraam și-a ridicat ochii și a văzut locul de departe.", "Avraam le-a spus slujitorilor săi: „Rămâneți aici cu măgarul. Eu și băiatul vom merge până acolo, ne vom închina și ne vom întoarce la voi.”", "Avraam a luat lemnele pentru arderea-de-tot și le-a pus pe fiul său Isaac, iar el a luat în mână focul și cuțitul. Și au mers amândoi împreună.", "Isaac i-a vorbit tatălui său, Avraam, și i-a spus: „Tată!” El a răspuns: „Iată-mă, fiul meu.” Isaac a spus: „Iată focul și lemnele, dar unde este mielul pentru arderea-de-tot?”", "Avraam a răspuns: „Dumnezeu Însuși va purta de grijă pentru mielul arderii-de-tot, fiul meu.” Și au mers amândoi împreună.", "Când au ajuns la locul despre care îi spusese Dumnezeu, Avraam a construit acolo altarul și a așezat lemnele. L-a legat pe fiul său Isaac și l-a pus pe altar, deasupra lemnelor.", "Apoi Avraam și-a întins mâna și a luat cuțitul ca să-și înjunghie fiul.", "Dar Îngerul DOMNULUI l-a chemat din cer și a spus: „Avraam! Avraam!” El a răspuns: „Iată-mă!”", "Îngerul a spus: „Să nu-ți întinzi mâna asupra băiatului și să nu-i faci nimic, pentru că acum știu că te temi de Dumnezeu, fiindcă nu l-ai cruțat pentru Mine pe fiul tău, pe singurul tău fiu.”", "Avraam și-a ridicat ochii, a privit și, iată, în spatele lui era un berbec prins cu coarnele într-un tufiș. Avraam s-a dus, a luat berbecul și l-a adus ca ardere-de-tot în locul fiului său.", "Avraam a numit locul acela „DOMNUL va purta de grijă”. De aceea se spune până astăzi: „Pe muntele DOMNULUI se va purta de grijă.”", "Îngerul DOMNULUI l-a chemat pe Avraam a doua oară din cer", "și a spus: „Mă jur pe Mine Însumi, zice DOMNUL: pentru că ai făcut lucrul acesta și nu l-ai cruțat pe fiul tău, pe singurul tău fiu,", "te voi binecuvânta din belșug și îți voi înmulți nespus de mult urmașii, ca stelele cerului și ca nisipul de pe țărmul mării. Urmașii tăi vor stăpâni poarta dușmanilor lor.", "Prin urmașii tăi vor fi binecuvântate toate națiunile pământului, pentru că ai ascultat de glasul Meu.”", "Avraam s-a întors la slujitorii lui, iar ei s-au ridicat și au mers împreună la Beer-Șeba. Avraam a locuit la Beer-Șeba.", "După aceste lucruri, lui Avraam i s-a spus: „Iată, și Milca i-a născut fii fratelui tău Nahor:", "pe Uț, întâiul lui născut, pe Buz, fratele acestuia, pe Chemuel, tatăl lui Aram,", "pe Chesed, Hazo, Pildaș, Iidlaf și Betuel.”", "Betuel a devenit tatăl Rebecăi. Pe acești opt fii i-a născut Milca lui Nahor, fratele lui Avraam.", "Concubina lui, al cărei nume era Reuma, i-a născut și ea pe Tebah, Gaham, Tahaș și Maaca."],
    23: ["Sara a trăit o sută douăzeci și șapte de ani; aceștia au fost anii vieții Sarei.", "Sara a murit la Chiriat-Arba, adică Hebron, în țara Canaanului. Avraam a venit s-o jelească pe Sara și s-o plângă.", "Apoi Avraam s-a ridicat de lângă trupul soției sale și le-a vorbit fiilor lui Het:", "„Eu sunt străin și locuitor temporar printre voi. Dați-mi în mijlocul vostru un loc de înmormântare în proprietate, ca să-mi îngrop soția moartă, care este înaintea mea.”", "Fiii lui Het i-au răspuns lui Avraam:", "„Ascultă-ne, domnul nostru! Tu ești un prinț al lui Dumnezeu în mijlocul nostru. Îngroapă-ți soția în cel mai ales dintre mormintele noastre. Niciunul dintre noi nu-și va opri mormântul de la tine, ca să nu-ți poți îngropa soția.”", "Avraam s-a ridicat și s-a plecat înaintea poporului țării, înaintea fiilor lui Het.", "El le-a spus: „Dacă este voia voastră să-mi îngrop soția, care este înaintea mea, ascultați-mă și mijlociți pentru mine înaintea lui Efron, fiul lui Țohar,", "ca să-mi vândă pe preț întreg peștera Macpela, care îi aparține și se află la marginea ogorului său. Să mi-o vândă în prezența voastră, ca loc de înmormântare în proprietate.”", "Efron ședea în mijlocul fiilor lui Het. Efron, hetitul, i-a răspuns lui Avraam în auzul fiilor lui Het și al tuturor celor care intrau pe poarta cetății lui:", "„Nu, domnul meu, ascultă-mă! Îți dau ogorul și îți dau și peștera care este în el. Ți le dau înaintea fiilor poporului meu. Îngroapă-ți soția.”", "Avraam s-a plecat înaintea poporului țării", "și i-a vorbit lui Efron în auzul poporului țării: „Te rog, ascultă-mă! Îți voi da prețul ogorului. Primește-l de la mine, iar eu îmi voi îngropa soția acolo.”", "Efron i-a răspuns lui Avraam:", "„Domnul meu, ascultă-mă! Un pământ de patru sute de șecheli de argint — ce este aceasta între mine și tine? Îngroapă-ți soția.”", "Avraam l-a ascultat pe Efron și i-a cântărit argintul pe care îl spusese în auzul fiilor lui Het: patru sute de șecheli de argint, după greutatea recunoscută între negustori.", "Astfel, ogorul lui Efron din Macpela, care se afla în fața lui Mamre — ogorul, peștera din el și toți copacii din ogor, de pe tot cuprinsul hotarelor lui —", "a trecut în proprietatea lui Avraam, în prezența fiilor lui Het și a tuturor celor care intrau pe poarta cetății lui.", "După aceea, Avraam a îngropat-o pe Sara, soția lui, în peștera ogorului Macpela, în fața lui Mamre, adică Hebron, în țara Canaanului.", "Ogorul și peștera din el au fost confirmate lui Avraam de fiii lui Het ca loc de înmormântare în proprietate."],
    24: ["Avraam era bătrân și înaintat în zile, iar DOMNUL îl binecuvântase pe Avraam în toate.", "Avraam i-a spus slujitorului său, cel mai bătrân din casa lui, care administra tot ce avea: „Te rog, pune-ți mâna sub coapsa mea.", "Te voi pune să juri pe DOMNUL, Dumnezeul cerurilor și Dumnezeul pământului, că nu vei lua pentru fiul meu o soție dintre fiicele canaaniților în mijlocul cărora locuiesc,", "ci vei merge în țara mea și la rudele mele și vei lua de acolo o soție pentru fiul meu Isaac.”", "Slujitorul l-a întrebat: „Poate că femeia nu va dori să mă urmeze în țara aceasta. Va trebui atunci să-l duc pe fiul tău înapoi în țara din care ai plecat?”", "Avraam i-a răspuns: „Ai grijă să nu-l duci pe fiul meu înapoi acolo!", "DOMNUL, Dumnezeul cerurilor, care m-a luat din casa tatălui meu și din țara în care m-am născut, care mi-a vorbit și mi-a jurat: «Urmașilor tăi le voi da țara aceasta», El Își va trimite îngerul înaintea ta și vei lua de acolo o soție pentru fiul meu.", "Iar dacă femeia nu va dori să te urmeze, vei fi eliberat de jurământul acesta față de mine. Numai să nu-l duci pe fiul meu înapoi acolo.”", "Slujitorul și-a pus mâna sub coapsa lui Avraam, stăpânul său, și i-a jurat cu privire la acest lucru.", "Slujitorul a luat zece dintre cămilele stăpânului său și a plecat, având sub răspunderea lui tot felul de bunuri ale stăpânului său. S-a ridicat și a mers în Aram-Naharaim, la cetatea lui Nahor.", "A pus cămilele să îngenuncheze în afara cetății, lângă fântâna cu apă, spre seară, la vremea când femeile ieșeau să scoată apă.", "El a spus: „DOMNULE, Dumnezeul stăpânului meu Avraam, Te rog, fă să-mi reușească astăzi și arată bunătate față de stăpânul meu Avraam.", "Iată, stau lângă izvorul de apă, iar fiicele oamenilor din cetate ies să scoată apă.", "Fă ca tânăra căreia îi voi spune: «Te rog, lasă-ți vasul jos ca să beau», iar ea îmi va răspunde: «Bea, și voi da apă și cămilelor tale», să fie cea pe care ai hotărât-o pentru slujitorul Tău Isaac. Prin aceasta voi ști că ai arătat bunătate față de stăpânul meu.”", "Înainte să termine de vorbit, iată că a ieșit Rebeca, fiica lui Betuel, fiul Milcăi, soția lui Nahor, fratele lui Avraam, cu vasul pe umăr.", "Tânăra era foarte frumoasă la înfățișare, era fecioară și nu avusese relații cu niciun bărbat. Ea a coborât la izvor, și-a umplut vasul și a urcat.", "Slujitorul a alergat în întâmpinarea ei și i-a spus: „Te rog, dă-mi să beau puțină apă din vasul tău.”", "Ea a răspuns: „Bea, domnul meu.” S-a grăbit, și-a coborât vasul pe mână și i-a dat să bea.", "După ce a terminat să-i dea să bea, a spus: „Voi scoate apă și pentru cămilele tale, până vor termina de băut.”", "S-a grăbit, și-a golit vasul în adăpătoare, a alergat din nou la fântână să scoată apă și a scos pentru toate cămilele lui.", "Bărbatul o privea cu atenție, tăcând, ca să afle dacă DOMNUL îi făcuse călătoria reușită sau nu.", "După ce cămilele au terminat de băut, bărbatul a luat un inel de aur pentru nas, în greutate de o jumătate de șechel, și două brățări de aur pentru mâinile ei, în greutate de zece șecheli.", "El a întrebat: „A cui fiică ești? Te rog, spune-mi: este în casa tatălui tău loc pentru noi ca să rămânem peste noapte?”", "Ea i-a răspuns: „Sunt fiica lui Betuel, fiul Milcăi, pe care ea i l-a născut lui Nahor.”", "Apoi a adăugat: „Avem și paie, și hrană din belșug, precum și loc pentru găzduire.”", "Bărbatul și-a plecat capul și s-a închinat DOMNULUI.", "El a spus: „Binecuvântat să fie DOMNUL, Dumnezeul stăpânului meu Avraam, care nu Și-a retras bunătatea și credincioșia față de stăpânul meu! Pe mine, DOMNUL m-a călăuzit pe drum până la casa rudelor stăpânului meu.”", "Tânăra a alergat și a povestit în casa mamei sale cele întâmplate.", "Rebeca avea un frate, al cărui nume era Laban. Laban a alergat afară la bărbat, la izvor.", "Când a văzut inelul pentru nas și brățările pe mâinile surorii sale și a auzit cuvintele Rebecăi, sora lui, care spunea: „Așa mi-a vorbit bărbatul”, s-a dus la el. Iată, acesta stătea lângă cămile, la izvor.", "Laban i-a spus: „Intră, tu, cel binecuvântat de DOMNUL! De ce stai afară? Am pregătit casa și un loc pentru cămile.”", "Bărbatul a intrat în casă. Cămilele au fost descărcate, li s-au dat paie și hrană, iar lui și oamenilor care erau cu el li s-a adus apă ca să-și spele picioarele.", "I s-a pus înainte mâncare, dar el a spus: „Nu voi mânca până nu-mi voi spune însărcinarea.” Laban a răspuns: „Vorbește.”", "El a spus: „Eu sunt slujitorul lui Avraam.", "DOMNUL l-a binecuvântat foarte mult pe stăpânul meu, iar el a ajuns puternic. I-a dat turme și cirezi, argint și aur, slujitori și slujitoare, cămile și măgari.", "Sara, soția stăpânului meu, i-a născut stăpânului meu un fiu la bătrânețe, iar el i-a dat acestuia tot ce are.", "Stăpânul meu m-a pus să jur și a spus: «Să nu iei pentru fiul meu o soție dintre fiicele canaaniților în a căror țară locuiesc,", "ci să mergi la casa tatălui meu și la rudele mele și să iei de acolo o soție pentru fiul meu.»", "Eu i-am spus stăpânului meu: «Poate că femeia nu mă va urma.»", "El mi-a răspuns: «DOMNUL, înaintea căruia am umblat, Își va trimite îngerul cu tine și îți va face călătoria reușită. Vei lua pentru fiul meu o soție dintre rudele mele și din casa tatălui meu.", "Vei fi eliberat de jurământul meu când vei ajunge la rudele mele. Iar dacă nu ți-o vor da, vei fi eliberat de jurământul meu.»", "Astăzi am ajuns la izvor și am spus: «DOMNULE, Dumnezeul stăpânului meu Avraam, Te rog, dacă faci reușită calea pe care merg,", "iată, stau lângă izvorul de apă. Fă ca tânăra care va ieși să scoată apă și căreia îi voi spune: „Te rog, dă-mi să beau puțină apă din vasul tău”,", "iar ea îmi va spune: „Bea, și voi scoate apă și pentru cămilele tale”, să fie femeia pe care DOMNUL a hotărât-o pentru fiul stăpânului meu.»", "Înainte să termin de vorbit în inima mea, iată că a ieșit Rebeca, având vasul pe umăr. A coborât la izvor și a scos apă, iar eu i-am spus: «Te rog, dă-mi să beau.»", "Ea s-a grăbit, și-a coborât vasul de pe umăr și a spus: «Bea, și voi da apă și cămilelor tale.» Am băut, iar ea a dat apă și cămilelor.", "Am întrebat-o: «A cui fiică ești?» Ea a răspuns: «Fiica lui Betuel, fiul lui Nahor, pe care Milca i l-a născut.» Atunci i-am pus inelul în nas și brățările pe mâini.", "Mi-am plecat capul și m-am închinat DOMNULUI. L-am binecuvântat pe DOMNUL, Dumnezeul stăpânului meu Avraam, care m-a călăuzit pe calea cea dreaptă ca s-o iau pe fiica din familia fratelui stăpânului meu pentru fiul lui.", "Acum, dacă vreți să vă purtați cu bunătate și credincioșie față de stăpânul meu, spuneți-mi; iar dacă nu, spuneți-mi, ca să mă îndrept la dreapta sau la stânga.”", "Laban și Betuel au răspuns: „Lucrul acesta vine de la DOMNUL; noi nu-ți putem spune nici rău, nici bine.", "Iată, Rebeca este înaintea ta. Ia-o și pleacă, iar ea să fie soția fiului stăpânului tău, așa cum a vorbit DOMNUL.”", "Când slujitorul lui Avraam a auzit cuvintele lor, s-a plecat până la pământ înaintea DOMNULUI.", "Slujitorul a scos obiecte de argint, obiecte de aur și haine și i le-a dat Rebecăi. De asemenea, i-a dat lucruri prețioase fratelui și mamei ei.", "Apoi au mâncat și au băut, el și oamenii care erau cu el, și au rămas peste noapte. Când s-au sculat dimineața, el a spus: „Lăsați-mă să mă întorc la stăpânul meu.”", "Fratele și mama ei au spus: „Să mai rămână tânăra cu noi câteva zile, poate zece; după aceea va pleca.”", "El le-a răspuns: „Nu mă întârziați, de vreme ce DOMNUL mi-a făcut călătoria reușită. Lăsați-mă să plec la stăpânul meu.”", "Ei au spus: „S-o chemăm pe tânără și s-o întrebăm chiar pe ea.”", "Au chemat-o pe Rebeca și au întrebat-o: „Vei merge cu bărbatul acesta?” Ea a răspuns: „Voi merge.”", "Astfel au trimis-o pe Rebeca, sora lor, împreună cu doica ei, cu slujitorul lui Avraam și cu oamenii lui.", "Au binecuvântat-o pe Rebeca și i-au spus: „Sora noastră, să ajungi mama miilor de zeci de mii, iar urmașii tăi să stăpânească poarta celor care îi urăsc!”", "Rebeca și slujitoarele ei s-au ridicat, au încălecat pe cămile și l-au urmat pe bărbat. Slujitorul a luat-o pe Rebeca și a plecat.", "Isaac venea dinspre Beer-Lahai-Roi și locuia în ținutul Neghevului.", "Spre seară, Isaac a ieșit pe câmp ca să mediteze. Și-a ridicat ochii, a privit și, iată, veneau niște cămile.", "Rebeca și-a ridicat ochii, l-a văzut pe Isaac și a coborât repede de pe cămilă.", "Ea l-a întrebat pe slujitor: „Cine este bărbatul acela care vine pe câmp în întâmpinarea noastră?” Slujitorul a răspuns: „Este stăpânul meu.” Atunci ea și-a luat vălul și s-a acoperit.", "Slujitorul i-a povestit lui Isaac toate lucrurile pe care le făcuse.", "Isaac a dus-o pe Rebeca în cortul mamei sale, Sara. A luat-o pe Rebeca, iar ea a devenit soția lui. El a iubit-o, și astfel Isaac a fost mângâiat după moartea mamei sale."],
    25: ["Avraam și-a mai luat o soție, al cărei nume era Chetura.", "Ea i-a născut pe Zimran, Iocșan, Medan, Madian, Ișbac și Șuah.", "Iocșan a devenit tatăl lui Șeba și Dedan. Fiii lui Dedan au fost așurimii, letușimii și leumimii.", "Fiii lui Madian au fost Efa, Efer, Enoh, Abida și Eldaa. Toți aceștia au fost urmașii Cheturei.", "Avraam i-a dat lui Isaac tot ce avea.", "Fiilor concubinelor sale, Avraam le-a dat daruri și, cât încă trăia, i-a trimis departe de fiul său Isaac, spre răsărit, în țara răsăritului.", "Anii vieții lui Avraam au fost o sută șaptezeci și cinci de ani.", "Avraam și-a dat ultima suflare și a murit la o bătrânețe fericită, bătrân și sătul de zile, și a fost adunat la poporul său.", "Fiii săi Isaac și Ismael l-au îngropat în peștera Macpela, în ogorul lui Efron, fiul lui Țohar, hetitul, în fața lui Mamre,", "ogorul pe care Avraam îl cumpărase de la fiii lui Het. Acolo au fost îngropați Avraam și soția lui, Sara.", "După moartea lui Avraam, Dumnezeu l-a binecuvântat pe fiul său Isaac. Isaac locuia lângă Beer-Lahai-Roi.", "Aceasta este istoria urmașilor lui Ismael, fiul lui Avraam, pe care Agar, egipteanca, slujitoarea Sarei, i l-a născut lui Avraam.", "Acestea sunt numele fiilor lui Ismael, după numele lor și în ordinea nașterii: Nebaiot, întâiul născut al lui Ismael, apoi Chedar, Adbeel, Mibsam,", "Mișma, Duma, Masa,", "Hadad, Tema, Ietur, Nafiș și Chedma.", "Aceștia sunt fiii lui Ismael și acestea sunt numele lor, după așezările și taberele lor: doisprezece conducători ai popoarelor lor.", "Anii vieții lui Ismael au fost o sută treizeci și șapte de ani. El și-a dat ultima suflare, a murit și a fost adunat la poporul său.", "Ei au locuit de la Havila până la Șur, care este în fața Egiptului, în direcția Asiriei. Ismael s-a așezat în fața tuturor rudelor sale.", "Aceasta este istoria urmașilor lui Isaac, fiul lui Avraam. Avraam a devenit tatăl lui Isaac.", "Isaac avea patruzeci de ani când a luat-o de soție pe Rebeca, fiica lui Betuel, arameul din Padan-Aram, și sora lui Laban, arameul.", "Isaac s-a rugat stăruitor DOMNULUI pentru soția lui, deoarece era stearpă. DOMNUL i-a ascultat rugăciunea, iar soția lui, Rebeca, a rămas însărcinată.", "Copiii se izbeau unul de altul în pântecele ei, iar ea a spus: „Dacă este așa, de ce mi se întâmplă aceasta?” Și s-a dus să-L întrebe pe DOMNUL.", "DOMNUL i-a spus: „Două națiuni sunt în pântecele tău și două popoare se vor despărți din trupul tău. Un popor va fi mai puternic decât celălalt, iar cel mai mare îi va sluji celui mai mic.”", "Când i s-au împlinit zilele ca să nască, iată că în pântecele ei erau gemeni.", "Primul a ieșit roșcat, acoperit în întregime ca o haină de păr, și i-au pus numele Esau.", "După aceea a ieșit fratele lui, ținând cu mâna călcâiul lui Esau, și i-au pus numele Iacov. Isaac avea șaizeci de ani când Rebeca i-a născut.", "Băieții au crescut. Esau a devenit un vânător priceput, un om al câmpului, iar Iacov era un om liniștit, care locuia în corturi.", "Isaac îl iubea pe Esau, pentru că vânatul era pe gustul lui, iar Rebeca îl iubea pe Iacov.", "Într-o zi, Iacov fierbea o mâncare, iar Esau s-a întors de la câmp epuizat.", "Esau i-a spus lui Iacov: „Te rog, dă-mi să mănânc din mâncarea aceea roșie, din aceea roșie, pentru că sunt epuizat!” De aceea i s-a pus numele Edom.", "Iacov i-a răspuns: „Vinde-mi mai întâi dreptul tău de întâi născut.”", "Esau a spus: „Iată, sunt pe punctul de a muri. La ce-mi folosește dreptul de întâi născut?”", "Iacov a spus: „Jură-mi mai întâi!” Esau i-a jurat și i-a vândut lui Iacov dreptul său de întâi născut.", "Atunci Iacov i-a dat lui Esau pâine și mâncare de linte. El a mâncat și a băut, apoi s-a ridicat și a plecat. Astfel și-a disprețuit Esau dreptul de întâi născut."],
    26: ["În țară a venit o foamete, pe lângă foametea dintâi, care fusese în zilele lui Avraam. Isaac s-a dus la Abimelec, regele filistenilor, în Gherar.", "DOMNUL i S-a arătat și i-a spus: „Nu coborî în Egipt. Locuiește în țara despre care îți voi spune.", "Rămâi ca străin în țara aceasta, iar Eu voi fi cu tine și te voi binecuvânta, pentru că ție și urmașilor tăi vă voi da toate țările acestea și voi împlini jurământul pe care i l-am făcut tatălui tău, Avraam.", "Îți voi înmulți urmașii ca stelele cerului, le voi da toate țările acestea, iar prin urmașii tăi vor fi binecuvântate toate națiunile pământului,", "pentru că Avraam a ascultat glasul Meu și a păzit rânduiala Mea, poruncile Mele, hotărârile Mele și legile Mele.”", "Isaac a locuit în Gherar.", "Oamenii locului l-au întrebat despre soția lui, iar el a spus: „Este sora mea”, fiindcă se temea să spună: „Este soția mea.” El își zicea: „Oamenii locului m-ar putea ucide din cauza Rebecăi, pentru că este frumoasă la înfățișare.”", "După ce petrecuse acolo multă vreme, Abimelec, regele filistenilor, s-a uitat pe fereastră și l-a văzut pe Isaac mângâind-o pe Rebeca, soția lui.", "Abimelec l-a chemat pe Isaac și i-a spus: „Iată, ea este cu adevărat soția ta! De ce ai spus: «Este sora mea»?” Isaac i-a răspuns: „Pentru că mi-am zis: «Ca nu cumva să mor din cauza ei.»”", "Abimelec a spus: „Ce ne-ai făcut? Puțin a lipsit ca unul din popor să se culce cu soția ta și ai fi adus vină asupra noastră!”", "Atunci Abimelec a poruncit întregului popor: „Oricine se va atinge de omul acesta sau de soția lui va fi omorât negreșit.”", "Isaac a semănat în țara aceea și, în același an, a strâns însutit. DOMNUL l-a binecuvântat.", "Omul s-a îmbogățit și a continuat să se îmbogățească până când a ajuns foarte bogat.", "Avea turme de oi, cirezi de vite și mulți slujitori, iar filistenii îl invidiau.", "Filistenii astupaseră și umpluseră cu pământ toate fântânile pe care slujitorii tatălui său le săpaseră în zilele lui Avraam.", "Abimelec i-a spus lui Isaac: „Pleacă de la noi, pentru că ai ajuns mult mai puternic decât noi.”", "Isaac a plecat de acolo, și-a așezat tabăra în valea Gherarului și a locuit acolo.", "Isaac a săpat din nou fântânile de apă care fuseseră săpate în zilele tatălui său, Avraam, și pe care filistenii le astupaseră după moartea lui Avraam. Le-a pus aceleași nume pe care li le dăduse tatăl său.", "Slujitorii lui Isaac au săpat în vale și au găsit acolo o fântână cu apă vie.", "Păstorii din Gherar s-au certat cu păstorii lui Isaac și au spus: „Apa este a noastră!” De aceea Isaac a numit fântâna Esec, pentru că se certaseră cu el.", "Au săpat apoi o altă fântână, dar s-au certat și pentru ea. Isaac i-a pus numele Sitna.", "A plecat de acolo și a săpat o altă fântână. Pentru aceasta nu s-au mai certat, iar el i-a pus numele Rehobot și a spus: „Acum DOMNUL ne-a făcut loc și vom fi roditori în țară.”", "De acolo s-a urcat la Beer-Șeba.", "În noaptea aceea, DOMNUL i S-a arătat și i-a spus: „Eu sunt Dumnezeul tatălui tău, Avraam. Nu te teme, pentru că Eu sunt cu tine. Te voi binecuvânta și îți voi înmulți urmașii datorită slujitorului Meu Avraam.”", "Isaac a construit acolo un altar, a chemat Numele DOMNULUI și și-a întins cortul acolo. Slujitorii lui Isaac au săpat acolo o fântână.", "Abimelec a venit la el din Gherar împreună cu prietenul său Ahuzat și cu Picol, comandantul armatei sale.", "Isaac le-a spus: „De ce ați venit la mine, de vreme ce mă urâți și m-ați alungat de la voi?”", "Ei au răspuns: „Am văzut limpede că DOMNUL este cu tine și ne-am spus: «Să fie un jurământ între noi, între noi și tine, și să încheiem un legământ cu tine,", "ca să nu ne faci niciun rău, așa cum nici noi nu ne-am atins de tine, ci ți-am făcut numai bine și te-am lăsat să pleci în pace.» Acum tu ești binecuvântatul DOMNULUI.”", "Isaac le-a pregătit un ospăț, iar ei au mâncat și au băut.", "S-au sculat dis-de-dimineață și și-au jurat unul altuia. Isaac i-a lăsat să plece, iar ei au plecat de la el în pace.", "În aceeași zi, slujitorii lui Isaac au venit și i-au dat de veste despre fântâna pe care o săpaseră, spunând: „Am găsit apă.”", "El a numit-o Șiba. De aceea numele cetății este Beer-Șeba până în ziua de astăzi.", "Când Esau avea patruzeci de ani, a luat-o de soție pe Iudita, fiica hetitului Beeri, și pe Basmat, fiica hetitului Elon.", "Ele au fost o amărăciune pentru duhul lui Isaac și al Rebecăi."],
    27: ["Când Isaac a îmbătrânit și ochii i s-au întunecat, astfel încât nu mai putea vedea, l-a chemat pe Esau, fiul său cel mare, și i-a spus: „Fiul meu!” El a răspuns: „Iată-mă.”", "Isaac a spus: „Iată, am îmbătrânit și nu cunosc ziua morții mele.", "Acum, te rog, ia-ți armele, tolba și arcul, ieși la câmp și vânează-mi ceva.", "Pregătește-mi o mâncare gustoasă, așa cum îmi place, și adu-mi-o să mănânc, pentru ca sufletul meu să te binecuvânteze înainte să mor.”", "Rebeca asculta în timp ce Isaac îi vorbea fiului său Esau. Esau a plecat la câmp ca să vâneze și să aducă vânat.", "Rebeca i-a spus fiului ei Iacov: „Iată, l-am auzit pe tatăl tău vorbindu-i fratelui tău Esau și spunând:", "«Adu-mi vânat și pregătește-mi o mâncare gustoasă, ca să mănânc și să te binecuvântez înaintea DOMNULUI înainte să mor.»", "Acum, fiul meu, ascultă glasul meu și fă ceea ce îți poruncesc.", "Du-te la turmă și adu-mi de acolo doi iezi buni. Voi pregăti din ei o mâncare gustoasă pentru tatăl tău, așa cum îi place.", "Tu o vei duce tatălui tău ca să mănânce și să te binecuvânteze înainte să moară.”", "Iacov i-a spus mamei sale Rebeca: „Iată, fratele meu Esau este un om păros, iar eu sunt un om cu pielea netedă.", "Poate că tatăl meu mă va pipăi. Atunci voi părea înaintea lui un înșelător și voi aduce asupra mea un blestem, nu o binecuvântare.”", "Mama lui i-a spus: „Blestemul tău să cadă asupra mea, fiul meu! Numai ascultă glasul meu, du-te și adu-mi-i.”", "El s-a dus, i-a luat și i-a adus mamei sale, iar mama lui a pregătit o mâncare gustoasă, așa cum îi plăcea tatălui său.", "Rebeca a luat hainele cele bune ale fiului ei cel mare, Esau, care erau la ea în casă, și l-a îmbrăcat cu ele pe fiul ei cel mic, Iacov.", "A pus pieile iezilor pe mâinile lui și pe partea netedă a gâtului lui.", "Apoi a pus în mâna fiului ei Iacov mâncarea gustoasă și pâinea pe care le pregătise.", "El a venit la tatăl său și a spus: „Tată!” Isaac a răspuns: „Iată-mă. Cine ești tu, fiul meu?”", "Iacov i-a spus tatălui său: „Eu sunt Esau, întâiul tău născut. Am făcut ce mi-ai spus. Te rog, ridică-te, așază-te și mănâncă din vânatul meu, pentru ca sufletul tău să mă binecuvânteze.”", "Isaac i-a spus fiului său: „Cum de ai găsit atât de repede, fiul meu?” El a răspuns: „Pentru că DOMNUL, Dumnezeul tău, mi-a dat izbândă.”", "Isaac i-a spus lui Iacov: „Apropie-te, te rog, ca să te pipăi, fiul meu, și să aflu dacă ești cu adevărat fiul meu Esau sau nu.”", "Iacov s-a apropiat de tatăl său Isaac, iar acesta l-a pipăit și a spus: „Glasul este glasul lui Iacov, dar mâinile sunt mâinile lui Esau.”", "Nu l-a recunoscut, pentru că mâinile lui erau păroase ca mâinile fratelui său Esau, și l-a binecuvântat.", "A întrebat: „Ești tu cu adevărat fiul meu Esau?” El a răspuns: „Eu sunt.”", "Isaac a spus: „Adu-mi mâncarea, ca să mănânc din vânatul fiului meu și sufletul meu să te binecuvânteze.” Iacov i-a adus-o, iar el a mâncat; i-a adus și vin, iar el a băut.", "Apoi tatăl său Isaac i-a spus: „Apropie-te și sărută-mă, fiul meu.”", "El s-a apropiat și l-a sărutat. Isaac a simțit mirosul hainelor lui, l-a binecuvântat și a spus: „Iată, mirosul fiului meu este ca mirosul unui câmp pe care l-a binecuvântat DOMNUL.", "Dumnezeu să-ți dea din roua cerului, din belșugul pământului și grâu și vin din abundență.", "Popoare să-ți slujească și națiuni să se plece înaintea ta. Fii stăpân peste frații tăi, iar fiii mamei tale să se plece înaintea ta. Blestemat să fie cel care te blestemă și binecuvântat cel care te binecuvântează!”", "De îndată ce Isaac a terminat de binecuvântat pe Iacov și Iacov tocmai ieșise dinaintea tatălui său Isaac, fratele lui, Esau, s-a întors de la vânătoare.", "Și el a pregătit o mâncare gustoasă, a adus-o tatălui său și i-a spus: „Să se ridice tatăl meu și să mănânce din vânatul fiului său, pentru ca sufletul tău să mă binecuvânteze.”", "Tatăl său Isaac l-a întrebat: „Cine ești tu?” El a răspuns: „Eu sunt fiul tău, întâiul tău născut, Esau.”", "Isaac a fost cuprins de un tremur nespus de puternic și a spus: „Atunci cine a fost cel care a vânat, mi-a adus și am mâncat din toate înainte să vii tu? L-am binecuvântat și binecuvântat va rămâne.”", "Când a auzit cuvintele tatălui său, Esau a scos un strigăt foarte mare și amar și i-a spus tatălui său: „Binecuvântează-mă și pe mine, tată!”", "Isaac a spus: „Fratele tău a venit cu înșelăciune și ți-a luat binecuvântarea.”", "Esau a spus: „Nu pe drept i s-a pus numele Iacov? M-a înșelat de două ori: mi-a luat dreptul de întâi născut, iar acum mi-a luat și binecuvântarea!” Apoi a întrebat: „Nu ai păstrat și pentru mine o binecuvântare?”", "Isaac i-a răspuns lui Esau: „Iată, l-am făcut stăpân peste tine și i-am dat pe toți frații lui ca slujitori. L-am susținut cu grâu și vin. Ce mai pot face pentru tine, fiul meu?”", "Esau i-a spus tatălui său: „Ai numai o singură binecuvântare, tată? Binecuvântează-mă și pe mine, tată!” Esau și-a ridicat glasul și a plâns.", "Tatăl său Isaac i-a răspuns: „Iată, locuința ta va fi departe de belșugul pământului și de roua cerului de sus.", "Vei trăi prin sabia ta și îi vei sluji fratelui tău. Dar când te vei smulge, îi vei rupe jugul de pe gâtul tău.”", "Esau l-a urât pe Iacov din cauza binecuvântării cu care îl binecuvântase tatăl său. Esau a spus în inima lui: „Se apropie zilele de jale pentru tatăl meu; atunci îl voi ucide pe fratele meu Iacov.”", "Rebecăi i-au fost spuse cuvintele fiului ei cel mare, Esau. Ea a trimis să-l cheme pe fiul ei cel mic, Iacov, și i-a spus: „Iată, fratele tău Esau își găsește mângâierea în gândul că te va ucide.", "Acum, fiul meu, ascultă glasul meu: ridică-te și fugi la fratele meu Laban, în Haran.", "Rămâi la el câteva zile, până când se va potoli furia fratelui tău,", "până când mânia fratelui tău se va întoarce de la tine și va uita ce i-ai făcut. Atunci voi trimite să te aduc de acolo. De ce să fiu lipsită de voi amândoi într-o singură zi?”", "Rebeca i-a spus lui Isaac: „M-am săturat de viață din cauza fiicelor lui Het. Dacă Iacov își ia o soție dintre fiicele lui Het, dintre femeile țării, la ce-mi mai folosește viața?”"],
    28: ["Isaac l-a chemat pe Iacov, l-a binecuvântat și i-a poruncit: „Să nu-ți iei soție dintre fiicele Canaanului.", "Ridică-te, du-te în Padan-Aram, la casa lui Betuel, tatăl mamei tale, și ia-ți de acolo o soție dintre fiicele lui Laban, fratele mamei tale.", "Dumnezeul Atotputernic să te binecuvânteze, să te facă roditor și să te înmulțească, astfel încât să devii o adunare de popoare.", "Să-ți dea binecuvântarea lui Avraam, ție și urmașilor tăi împreună cu tine, ca să moștenești țara în care locuiești ca străin, pe care Dumnezeu i-a dat-o lui Avraam.”", "Isaac l-a trimis pe Iacov, iar el s-a dus în Padan-Aram, la Laban, fiul arameului Betuel, fratele Rebecăi, mama lui Iacov și a lui Esau.", "Esau a văzut că Isaac îl binecuvântase pe Iacov și îl trimisese în Padan-Aram ca să-și ia de acolo o soție și că, binecuvântându-l, îi poruncise: „Să nu-ți iei soție dintre fiicele Canaanului.”", "A văzut și că Iacov ascultase de tatăl și de mama lui și plecase în Padan-Aram.", "Esau a înțeles că fiicele Canaanului nu erau plăcute tatălui său Isaac.", "Atunci Esau s-a dus la Ismael și, pe lângă soțiile pe care le avea, a luat-o de soție pe Mahalat, fiica lui Ismael, fiul lui Avraam, și sora lui Nebaiot.", "Iacov a plecat din Beer-Șeba și s-a îndreptat spre Haran.", "A ajuns într-un anumit loc și a rămas acolo peste noapte, pentru că apusese soarele. A luat una dintre pietrele locului, și-a pus-o sub cap și s-a culcat acolo.", "A visat și, iată, pe pământ era așezată o scară al cărei vârf ajungea la cer. Îngerii lui Dumnezeu urcau și coborau pe ea.", "Și, iată, DOMNUL stătea deasupra ei și a spus: „Eu sunt DOMNUL, Dumnezeul tatălui tău Avraam și Dumnezeul lui Isaac. Țara pe care ești culcat ți-o voi da ție și urmașilor tăi.", "Urmașii tăi vor fi ca pulberea pământului și te vei întinde spre apus, spre răsărit, spre nord și spre sud. Prin tine și prin urmașii tăi vor fi binecuvântate toate familiile pământului.", "Iată, Eu sunt cu tine, te voi păzi oriunde vei merge și te voi aduce înapoi în țara aceasta. Nu te voi părăsi până nu voi împlini ceea ce ți-am spus.”", "Iacov s-a trezit din somn și a spus: „Cu adevărat DOMNUL este în locul acesta, iar eu nu am știut.”", "S-a temut și a spus: „Cât de cutremurător este locul acesta! Aici nu este altceva decât casa lui Dumnezeu și aceasta este poarta cerului.”", "Iacov s-a sculat dis-de-dimineață, a luat piatra pe care și-o pusese sub cap, a ridicat-o ca stâlp și a turnat untdelemn pe vârful ei.", "A numit locul acela Betel, deși numele cetății fusese mai înainte Luz.", "Iacov a făcut o promisiune solemnă și a spus: „Dacă Dumnezeu va fi cu mine, mă va păzi pe drumul pe care merg și îmi va da pâine să mănânc și haine să îmbrac,", "iar eu mă voi întoarce în pace la casa tatălui meu, atunci DOMNUL va fi Dumnezeul meu.", "Piatra aceasta, pe care am ridicat-o ca stâlp, va fi casa lui Dumnezeu, iar din tot ce-mi vei da Îți voi da negreșit a zecea parte.”"],
    29: ["Iacov și-a continuat drumul și a ajuns în țara fiilor răsăritului.", "S-a uitat și, iată, pe câmp era o fântână, iar lângă ea stăteau culcate trei turme de oi, pentru că din fântâna aceea erau adăpate turmele. Piatra de la gura fântânii era mare.", "Acolo se adunau toate turmele. Păstorii rostogoleau piatra de la gura fântânii, adăpau oile, apoi puneau piatra la loc peste gura fântânii.", "Iacov le-a spus: „Fraților, de unde sunteți?” Ei au răspuns: „Suntem din Haran.”", "El i-a întrebat: „Îl cunoașteți pe Laban, fiul lui Nahor?” Ei au răspuns: „Îl cunoaștem.”", "Iacov a întrebat: „Este bine?” Ei au răspuns: „Este bine. Iată, Rahela, fiica lui, vine cu oile.”", "El a spus: „Iată, încă este ziua în toi și nu este vremea să se adune vitele. Adăpați oile și mergeți să le pașteți.”", "Ei au răspuns: „Nu putem până nu se adună toate turmele și nu se rostogolește piatra de la gura fântânii. Atunci vom adăpa oile.”", "Pe când încă vorbea cu ei, a venit Rahela cu oile tatălui ei, pentru că ea era păstoriță.", "Când Iacov a văzut-o pe Rahela, fiica lui Laban, fratele mamei sale, și oile lui Laban, fratele mamei sale, s-a apropiat, a rostogolit piatra de la gura fântânii și a adăpat turma lui Laban.", "Iacov a sărutat-o pe Rahela, și-a ridicat glasul și a plâns.", "Iacov i-a spus Rahelei că era rudă cu tatăl ei și că era fiul Rebecăi. Ea a alergat și i-a dat de veste tatălui ei.", "Când Laban a auzit vestea despre Iacov, fiul surorii sale, a alergat să-l întâmpine, l-a îmbrățișat, l-a sărutat și l-a adus în casa lui. Iacov i-a povestit lui Laban toate aceste lucruri.", "Laban i-a spus: „Cu adevărat ești os din oasele mele și carne din carnea mea.” Iacov a stat la el o lună.", "Apoi Laban i-a spus lui Iacov: „Pentru că ești ruda mea, să-mi slujești oare fără plată? Spune-mi care să-ți fie plata.”", "Laban avea două fiice. Cea mai mare se numea Lea, iar cea mai mică se numea Rahela.", "Ochii Leei erau delicați, dar Rahela era frumoasă la chip și plăcută la înfățișare.", "Iacov o iubea pe Rahela și a spus: „Îți voi sluji șapte ani pentru Rahela, fiica ta cea mică.”", "Laban a răspuns: „Este mai bine să ți-o dau ție decât s-o dau altui bărbat. Rămâi la mine.”", "Iacov a slujit șapte ani pentru Rahela, dar aceștia i s-au părut doar câteva zile, datorită iubirii lui pentru ea.", "Apoi Iacov i-a spus lui Laban: „Dă-mi soția, pentru că mi s-au împlinit zilele, ca să intru la ea.”", "Laban i-a adunat pe toți oamenii locului și a făcut un ospăț.", "Seara, a luat-o pe fiica sa Lea și a adus-o la Iacov, iar el a intrat la ea.", "Laban i-a dat-o fiicei sale Lea pe slujitoarea sa Zilpa, ca slujitoare.", "Dimineața, iată că era Lea! Iacov i-a spus lui Laban: „Ce mi-ai făcut? Nu ți-am slujit pentru Rahela? De ce m-ai înșelat?”", "Laban a răspuns: „În locul nostru nu se face așa, să fie dată cea mică înaintea întâi-născutei.", "Du până la capăt săptămâna de nuntă a acesteia și ți-o vom da și pe cealaltă, pentru încă șapte ani de slujire la mine.”", "Iacov a făcut astfel și a împlinit săptămâna Leei. Apoi Laban i-a dat-o de soție pe fiica sa Rahela.", "Laban i-a dat-o fiicei sale Rahela pe slujitoarea sa Bilha, ca slujitoare.", "Iacov a intrat și la Rahela și a iubit-o pe Rahela mai mult decât pe Lea. Apoi i-a mai slujit lui Laban încă șapte ani.", "DOMNUL a văzut că Lea nu era iubită și i-a deschis pântecele, dar Rahela era stearpă.", "Lea a rămas însărcinată, a născut un fiu și i-a pus numele Ruben, pentru că a spus: „DOMNUL a privit la suferința mea; acum soțul meu mă va iubi.”", "A rămas din nou însărcinată, a născut un fiu și a spus: „DOMNUL a auzit că nu sunt iubită și mi l-a dat și pe acesta.” De aceea i-a pus numele Simeon.", "A rămas iarăși însărcinată, a născut un fiu și a spus: „De data aceasta soțul meu se va alipi de mine, pentru că i-am născut trei fii.” De aceea i s-a pus numele Levi.", "A rămas din nou însărcinată, a născut un fiu și a spus: „De data aceasta Îl voi lăuda pe DOMNUL.” De aceea i-a pus numele Iuda. Apoi a încetat să mai nască."],
    30: ["Când Rahela a văzut că nu-i năștea copii lui Iacov, a invidiat-o pe sora ei și i-a spus lui Iacov: „Dă-mi copii, altfel mor!”", "Mânia lui Iacov s-a aprins împotriva Rahelei și el a spus: „Sunt eu oare în locul lui Dumnezeu, care a oprit de la tine rodul pântecelui?”", "Ea a spus: „Iată slujitoarea mea Bilha. Intră la ea, ca să nască pe genunchii mei și să am și eu copii prin ea.”", "I-a dat-o de soție pe slujitoarea ei Bilha, iar Iacov a intrat la ea.", "Bilha a rămas însărcinată și i-a născut lui Iacov un fiu.", "Rahela a spus: „Dumnezeu mi-a făcut dreptate, mi-a ascultat glasul și mi-a dat un fiu.” De aceea i-a pus numele Dan.", "Bilha, slujitoarea Rahelei, a rămas din nou însărcinată și i-a născut lui Iacov un al doilea fiu.", "Rahela a spus: „M-am luptat cu sora mea în lupte aprige și am biruit.” De aceea i-a pus numele Neftali.", "Când Lea a văzut că încetase să mai nască, a luat-o pe slujitoarea sa Zilpa și i-a dat-o lui Iacov de soție.", "Zilpa, slujitoarea Leei, i-a născut lui Iacov un fiu.", "Lea a spus: „Ce noroc!” și i-a pus numele Gad.", "Zilpa, slujitoarea Leei, i-a născut lui Iacov un al doilea fiu.", "Lea a spus: „Sunt fericită, pentru că femeile mă vor numi fericită.” De aceea i-a pus numele Așer.", "În zilele secerișului grâului, Ruben a ieșit și a găsit mandragore pe câmp, pe care le-a adus mamei sale, Lea. Rahela i-a spus Leei: „Te rog, dă-mi și mie din mandragorele fiului tău.”", "Lea i-a răspuns: „Este puțin lucru că mi-ai luat soțul? Vrei să iei și mandragorele fiului meu?” Rahela a spus: „Atunci se va culca cu tine în noaptea aceasta în schimbul mandragorelor fiului tău.”", "Când Iacov s-a întors seara de la câmp, Lea i-a ieșit înainte și a spus: „Trebuie să intri la mine, pentru că te-am cumpărat cu mandragorele fiului meu.” El s-a culcat cu ea în noaptea aceea.", "Dumnezeu a ascultat-o pe Lea. Ea a rămas însărcinată și i-a născut lui Iacov un al cincilea fiu.", "Lea a spus: „Dumnezeu mi-a dat plata pentru că i-am dat soțului meu slujitoarea mea.” De aceea i-a pus numele Isahar.", "Lea a rămas din nou însărcinată și i-a născut lui Iacov un al șaselea fiu.", "Lea a spus: „Dumnezeu m-a înzestrat cu un dar bun. Acum soțul meu mă va cinsti, pentru că i-am născut șase fii.” De aceea i-a pus numele Zabulon.", "După aceea a născut o fiică și i-a pus numele Dina.", "Dumnezeu Și-a adus aminte de Rahela, a ascultat-o și i-a deschis pântecele.", "Ea a rămas însărcinată, a născut un fiu și a spus: „Dumnezeu mi-a îndepărtat rușinea.”", "I-a pus numele Iosif și a spus: „DOMNUL să-mi mai adauge un fiu!”", "După ce Rahela l-a născut pe Iosif, Iacov i-a spus lui Laban: „Lasă-mă să plec, ca să mă duc la locul meu și în țara mea.", "Dă-mi soțiile și copiii pentru care ți-am slujit și lasă-mă să plec, pentru că știi slujirea pe care ți-am făcut-o.”", "Laban i-a spus: „Te rog, dacă am găsit bunăvoință în ochii tăi, rămâi. Am aflat prin divinație că DOMNUL m-a binecuvântat datorită ție.”", "Apoi a spus: „Stabilește-ți plata, iar eu ți-o voi da.”", "Iacov i-a răspuns: „Tu știi cum ți-am slujit și cum au prosperat turmele tale sub îngrijirea mea.", "Ceea ce aveai înainte de venirea mea era puțin, dar s-a înmulțit foarte mult. DOMNUL te-a binecuvântat oriunde am mers. Dar când voi lucra și pentru casa mea?”", "Laban a întrebat: „Ce să-ți dau?” Iacov a răspuns: „Să nu-mi dai nimic. Fă pentru mine lucrul acesta și voi paște și voi păzi din nou turma ta.", "Voi trece astăzi prin toată turma ta și voi scoate din ea orice animal pestriț sau pătat, orice oaie neagră și orice capră pătată sau pestriță. Aceasta va fi plata mea.", "Cinstea mea va mărturisi pentru mine în viitor, când vei veni să-mi cercetezi plata. Orice capră care nu este pătată sau pestriță și orice oaie care nu este neagră, dacă se va găsi la mine, să fie socotită furată.”", "Laban a spus: „Bine, să fie după cuvântul tău.”", "În ziua aceea, Laban a scos țapii vărgați și pătați, toate caprele pestrițe și pătate, toate cele care aveau alb pe ele și toate oile negre și le-a dat în mâna fiilor săi.", "A pus o distanță de trei zile între el și Iacov, iar Iacov păștea restul turmelor lui Laban.", "Iacov și-a luat nuiele verzi de plop, de migdal și de platan, a cojit pe ele dungi albe și a făcut să se vadă albul nuielelor.", "A pus nuielele pe care le cojise în fața turmelor, în jgheaburile și adăpătorile unde veneau turmele să bea. Ele se împerecheau când veneau să bea.", "Turmele se împerecheau înaintea nuielelor și făceau pui vărgați, pestriți și pătați.", "Iacov separa mieii și îndrepta fețele turmelor spre animalele vărgate și spre toate cele negre din turma lui Laban. Și-a pus turmele deoparte și nu le-a amestecat cu turma lui Laban.", "Ori de câte ori se împerecheau animalele mai puternice, Iacov punea nuielele înaintea ochilor lor în adăpători, ca să se împerecheze lângă nuiele.", "Dar când animalele erau slabe, nu le punea. Astfel cele slabe erau ale lui Laban, iar cele puternice ale lui Iacov.", "Omul s-a îmbogățit nespus de mult și a avut turme mari, slujitoare și slujitori, cămile și măgari."],
    31: ["Iacov a auzit cuvintele fiilor lui Laban, care spuneau: „Iacov a luat tot ce era al tatălui nostru și din averea tatălui nostru și-a făcut toată bogăția aceasta.”", "Iacov a văzut că Laban nu-l mai privea ca înainte.", "DOMNUL i-a spus lui Iacov: „Întoarce-te în țara părinților tăi și la rudele tale, iar Eu voi fi cu tine.”", "Iacov a trimis să le cheme pe Rahela și Lea la câmp, la turma lui,", "și le-a spus: „Văd că fața tatălui vostru nu mai este față de mine ca înainte, dar Dumnezeul tatălui meu a fost cu mine.", "Voi știți că i-am slujit tatălui vostru cu toată puterea mea.", "Tatăl vostru m-a înșelat și mi-a schimbat plata de zece ori, dar Dumnezeu nu i-a îngăduit să-mi facă rău.", "Dacă spunea: «Cele pestrițe vor fi plata ta», atunci toată turma făta pestrițe; iar dacă spunea: «Cele vărgate vor fi plata ta», atunci toată turma făta vărgate.", "Astfel, Dumnezeu a luat turmele tatălui vostru și mi le-a dat mie.", "În vremea împerecherii turmei, mi-am ridicat ochii și am văzut într-un vis că țapii care se urcau pe turmă erau vărgați, pestriți și bălțați.", "Îngerul lui Dumnezeu mi-a spus în vis: «Iacov!» Eu am răspuns: «Iată-mă.»", "El a spus: «Ridică-ți ochii și privește: toți țapii care se urcă pe turmă sunt vărgați, pestriți și bălțați, pentru că am văzut tot ce îți face Laban.", "Eu sunt Dumnezeul din Betel, unde ai uns un stâlp și unde Mi-ai făcut o promisiune solemnă. Acum ridică-te, ieși din țara aceasta și întoarce-te în țara în care te-ai născut.»”", "Rahela și Lea i-au răspuns: „Mai avem noi oare vreo parte sau vreo moștenire în casa tatălui nostru?", "Nu suntem socotite de el ca niște străine? El ne-a vândut și a cheltuit până și banii noștri.", "Toată bogăția pe care Dumnezeu a luat-o de la tatăl nostru este a noastră și a copiilor noștri. Acum fă tot ce ți-a spus Dumnezeu.”", "Iacov s-a ridicat și și-a urcat fiii și soțiile pe cămile.", "A luat toate turmele și toate bunurile pe care le strânsese, turmele pe care le dobândise în Padan-Aram, ca să meargă la tatăl său Isaac, în țara Canaanului.", "Laban plecase să-și tundă oile, iar Rahela a furat terafimii tatălui ei.", "Iacov l-a înșelat pe arameul Laban, ascunzându-i faptul că fugea.", "A fugit cu tot ce avea, a trecut Râul și s-a îndreptat spre muntele Galaadului.", "În a treia zi, lui Laban i s-a spus că Iacov fugise.", "Laban și-a luat rudele cu el, l-a urmărit cale de șapte zile și l-a ajuns în muntele Galaadului.", "Dar Dumnezeu a venit noaptea într-un vis la arameul Laban și i-a spus: „Păzește-te să-i vorbești lui Iacov fie de bine, fie de rău.”", "Laban l-a ajuns pe Iacov. Iacov își întinsese cortul pe munte, iar Laban și rudele lui și-au așezat tabăra în muntele Galaadului.", "Laban i-a spus lui Iacov: „Ce ai făcut? M-ai înșelat și le-ai luat pe fiicele mele ca pe niște captive de război.", "De ce ai fugit pe ascuns, m-ai înșelat și nu mi-ai spus, ca să te fi lăsat să pleci cu bucurie și cântări, cu tamburină și harpă?", "Nu mi-ai îngăduit să-mi sărut fiii și fiicele. Ai lucrat nebunește.", "Este în puterea mâinii mele să vă fac rău, dar Dumnezeul tatălui vostru mi-a vorbit noaptea trecută și mi-a spus: «Păzește-te să-i vorbești lui Iacov fie de bine, fie de rău.»", "Acum ai plecat pentru că îți era foarte dor de casa tatălui tău, dar de ce mi-ai furat dumnezeii?”", "Iacov i-a răspuns lui Laban: „Am fugit pentru că m-am temut. Mi-am spus că poate îți vei lua fiicele cu forța de la mine.", "Cel la care îți vei găsi dumnezeii să nu rămână în viață. Înaintea rudelor noastre, cercetează ce este al tău la mine și ia-ți.” Iacov nu știa că Rahela îi furase.", "Laban a intrat în cortul lui Iacov, în cortul Leei și în cortul celor două slujitoare, dar nu i-a găsit. A ieșit din cortul Leei și a intrat în cortul Rahelei.", "Rahela luase terafimii, îi pusese în șaua cămilei și se așezase pe ei. Laban a pipăit tot cortul, dar nu i-a găsit.", "Ea i-a spus tatălui ei: „Să nu se mânie stăpânul meu că nu mă pot ridica înaintea ta, pentru că am rânduiala femeilor.” El a căutat, dar nu a găsit terafimii.", "Atunci Iacov s-a mâniat și s-a certat cu Laban. Iacov i-a spus: „Care este fărădelegea mea? Care este păcatul meu, de m-ai urmărit cu atâta înverșunare?", "Acum, după ce ai pipăit toate lucrurile mele, ce ai găsit din lucrurile casei tale? Pune-le aici înaintea rudelor mele și ale tale, ca să judece între noi doi.", "Am stat cu tine douăzeci de ani. Oile și caprele tale nu și-au lepădat puii, iar eu nu am mâncat berbecii turmei tale.", "Nu ți-am adus animalul sfâșiat, ci am suportat eu pierderea. Din mâna mea cereai ceea ce era furat ziua sau noaptea.", "Ziua mă mistuia arșița, noaptea frigul, iar somnul fugea de la ochii mei.", "Am stat douăzeci de ani în casa ta: paisprezece ani ți-am slujit pentru cele două fiice ale tale și șase ani pentru turma ta, iar tu mi-ai schimbat plata de zece ori.", "Dacă Dumnezeul tatălui meu, Dumnezeul lui Avraam și Frica lui Isaac, nu ar fi fost cu mine, m-ai fi trimis acum cu mâinile goale. Dumnezeu a văzut suferința mea și munca mâinilor mele și te-a mustrat noaptea trecută.”", "Laban i-a răspuns lui Iacov: „Fiicele sunt fiicele mele, copiii sunt copiii mei, turmele sunt turmele mele și tot ce vezi este al meu. Dar ce le pot face astăzi acestor fiice ale mele sau copiilor pe care i-au născut?", "Acum vino să încheiem un legământ, eu și tu, și el să fie martor între mine și tine.”", "Iacov a luat o piatră și a ridicat-o ca stâlp.", "Iacov le-a spus rudelor sale: „Adunați pietre.” Ei au luat pietre, au făcut o movilă și au mâncat acolo lângă movilă.", "Laban a numit-o Iegar-Sahaduta, iar Iacov a numit-o Galed.", "Laban a spus: „Movila aceasta este astăzi martor între mine și tine.” De aceea i s-a pus numele Galed", "și Mițpa, pentru că Laban a spus: „DOMNUL să vegheze între mine și tine când nu ne vom mai vedea unul pe altul.", "Dacă le vei asupri pe fiicele mele sau dacă îți vei lua alte soții pe lângă fiicele mele, chiar dacă nu este niciun om cu noi, iată, Dumnezeu este martor între mine și tine.”", "Laban i-a mai spus lui Iacov: „Iată movila aceasta și iată stâlpul pe care l-am ridicat între mine și tine.", "Movila aceasta și stâlpul să fie martori că eu nu voi trece dincolo de această movilă spre tine ca să-ți fac rău și nici tu nu vei trece dincolo de această movilă și de acest stâlp spre mine ca să-mi faci rău.", "Dumnezeul lui Avraam și dumnezeul lui Nahor, dumnezeul tatălui lor, să judece între noi.” Iacov a jurat pe Frica tatălui său Isaac.", "Iacov a adus o jertfă pe munte și și-a chemat rudele să mănânce. Au mâncat și au rămas peste noapte pe munte.", "Dis-de-dimineață, Laban s-a ridicat, și-a sărutat fiii și fiicele și i-a binecuvântat. Apoi a plecat și s-a întors la locul său."],
    32: ["Iacov și-a continuat drumul, iar îngerii lui Dumnezeu l-au întâmpinat.", "Când i-a văzut, Iacov a spus: „Aceasta este tabăra lui Dumnezeu.” De aceea a numit locul acela Mahanaim.", "Iacov a trimis înaintea lui mesageri la fratele său Esau, în țara Seirului, în câmpia Edomului.", "Le-a poruncit: „Așa să-i spuneți stăpânului meu Esau: «Așa spune slujitorul tău Iacov: Am locuit ca străin la Laban și am rămas acolo până acum.", "Am vite, măgari, turme, slujitori și slujitoare și am trimis să-i dau de veste stăpânului meu, ca să găsesc bunăvoință în ochii tăi.»”", "Mesagerii s-au întors la Iacov și au spus: „Am ajuns la fratele tău Esau. El vine să te întâmpine și are cu el patru sute de oameni.”", "Iacov s-a temut foarte mult și a fost tulburat. A împărțit în două tabere oamenii care erau cu el, precum și turmele, cirezile și cămilele.", "El a spus: „Dacă Esau vine împotriva unei tabere și o lovește, tabăra rămasă va putea scăpa.”", "Apoi Iacov a spus: „Dumnezeul tatălui meu Avraam și Dumnezeul tatălui meu Isaac, DOMNULE, Tu care mi-ai spus: «Întoarce-te în țara ta și la rudele tale, iar Eu îți voi face bine»,", "sunt nevrednic de cea mai mică dintre toate îndurările și de toată credincioșia pe care le-ai arătat slujitorului Tău. Când am trecut Iordanul acesta aveam numai toiagul meu, iar acum am ajuns două tabere.", "Te rog, scapă-mă din mâna fratelui meu, din mâna lui Esau, pentru că mă tem să nu vină și să mă lovească pe mine, pe mame și pe copii.", "Tu ai spus: «Îți voi face negreșit bine și îți voi face urmașii ca nisipul mării, care nu poate fi numărat din cauza mulțimii lui.»”", "Iacov a rămas acolo în noaptea aceea și a luat din ceea ce avea cu el un dar pentru fratele său Esau:", "două sute de capre și douăzeci de țapi, două sute de oi și douăzeci de berbeci,", "treizeci de cămile care alăptau, împreună cu puii lor, patruzeci de vaci și zece tauri, douăzeci de măgărițe și zece măgăruși.", "Le-a dat în mâna slujitorilor săi, fiecare turmă separat, și le-a spus: „Treceți înaintea mea și lăsați o distanță între turmă și turmă.”", "Celui dintâi i-a poruncit: „Când te va întâlni fratele meu Esau și te va întreba: «Al cui ești? Unde mergi? Ale cui sunt acestea dinaintea ta?»", "să răspunzi: «Sunt ale slujitorului tău Iacov; este un dar trimis stăpânului meu Esau. Iată, și el vine în urma noastră.»”", "A poruncit la fel celui de-al doilea, celui de-al treilea și tuturor celor care mergeau după turme: „Așa să-i vorbiți lui Esau când îl veți întâlni.", "Să spuneți și: «Iată, slujitorul tău Iacov vine în urma noastră.»” Pentru că Iacov își spunea: „Îl voi împăca prin darul care merge înaintea mea, apoi îi voi vedea fața; poate mă va primi.”", "Darul a trecut înaintea lui, iar el a rămas în noaptea aceea în tabără.", "S-a ridicat în noaptea aceea, le-a luat pe cele două soții ale sale, pe cele două slujitoare și pe cei unsprezece fii și a trecut vadul Iabocului.", "I-a luat, i-a trecut pârâul și a trecut dincolo tot ce avea.", "Iacov a rămas singur. Un bărbat s-a luptat cu el până la revărsatul zorilor.", "Când bărbatul a văzut că nu-l biruiește, i-a atins încheietura coapsei, iar încheietura coapsei lui Iacov s-a scrântit în timp ce se lupta cu el.", "Bărbatul a spus: „Lasă-mă să plec, pentru că se revarsă zorile.” Dar Iacov a răspuns: „Nu te voi lăsa să pleci până nu mă vei binecuvânta.”", "El l-a întrebat: „Care este numele tău?” Iacov a răspuns: „Iacov.”", "Bărbatul a spus: „Numele tău nu va mai fi Iacov, ci Israel, pentru că ai luptat cu Dumnezeu și cu oamenii și ai biruit.”", "Iacov l-a întrebat: „Te rog, spune-mi numele Tău.” El a răspuns: „De ce Îmi întrebi numele?” Și l-a binecuvântat acolo.", "Iacov a numit locul acela Peniel și a spus: „L-am văzut pe Dumnezeu față în față și viața mi-a fost cruțată.”", "Soarele a răsărit peste el când a trecut de Penuel, iar el șchiopăta din cauza coapsei.", "De aceea, până în ziua de astăzi, fiii lui Israel nu mănâncă tendonul șoldului, care este la încheietura coapsei, pentru că El a atins încheietura coapsei lui Iacov, la tendonul șoldului."],
    33: ["Iacov și-a ridicat ochii și, iată, Esau venea cu patru sute de oameni. Atunci a împărțit copiii între Lea, Rahela și cele două slujitoare.", "A pus în față slujitoarele și copiii lor, apoi pe Lea și copiii ei, iar la urmă pe Rahela și Iosif.", "El însuși a trecut înaintea lor și s-a plecat până la pământ de șapte ori, până când s-a apropiat de fratele său.", "Esau a alergat să-l întâmpine, l-a îmbrățișat, i-a căzut pe gât, l-a sărutat și au plâns.", "Esau și-a ridicat ochii, a văzut femeile și copiii și a întrebat: „Cine sunt aceștia care sunt cu tine?” Iacov a răspuns: „Sunt copiii pe care Dumnezeu i-a dăruit cu bunăvoință slujitorului tău.”", "Slujitoarele s-au apropiat împreună cu copiii lor și s-au plecat.", "Apoi s-au apropiat Lea și copiii ei și s-au plecat. La urmă s-au apropiat Iosif și Rahela și s-au plecat.", "Esau a întrebat: „Ce înseamnă toată tabăra aceasta pe care am întâlnit-o?” Iacov a răspuns: „Ca să găsesc bunăvoință în ochii stăpânului meu.”", "Esau a spus: „Eu am destul, fratele meu. Păstrează ce este al tău.”", "Iacov a spus: „Nu, te rog! Dacă am găsit bunăvoință în ochii tăi, primește darul din mâna mea, pentru că ți-am văzut fața ca și cum aș fi văzut fața lui Dumnezeu, iar tu m-ai primit cu bunăvoință.", "Te rog, primește binecuvântarea mea, care ți-a fost adusă, pentru că Dumnezeu S-a purtat cu bunăvoință față de mine și am de toate.” A stăruit, iar Esau a primit.", "Esau a spus: „Să pornim la drum și să mergem; eu voi merge înaintea ta.”", "Iacov i-a răspuns: „Stăpânul meu știe că acești copii sunt firavi și că am cu mine oi și vite care alăptează. Dacă vor fi mânate prea tare chiar și o singură zi, toate turmele vor muri.", "Te rog, stăpânul meu să treacă înaintea slujitorului său, iar eu voi merge încet, după pasul turmelor care sunt înaintea mea și după pasul copiilor, până voi ajunge la stăpânul meu în Seir.”", "Esau a spus: „Lasă-mă măcar să pun lângă tine câțiva dintre oamenii care sunt cu mine.” Iacov a răspuns: „Pentru ce? Numai să găsesc bunăvoință în ochii stăpânului meu.”", "În ziua aceea, Esau s-a întors pe drumul său spre Seir.", "Iacov a mers la Sucot, și-a construit o casă și a făcut adăposturi pentru turmele lui. De aceea locul a fost numit Sucot.", "După ce a venit din Padan-Aram, Iacov a ajuns în pace la cetatea Sihem, în țara Canaanului, și și-a așezat tabăra înaintea cetății.", "A cumpărat de la fiii lui Hamor, tatăl lui Sihem, cu o sută de chesita, bucata de pământ pe care își întinsese cortul.", "A ridicat acolo un altar și l-a numit El-Elohe-Israel."],
    34: ["Dina, fiica pe care Lea i-o născuse lui Iacov, a ieșit să le vadă pe fiicele țării.", "Sihem, fiul lui Hamor, hevitul, conducătorul țării, a văzut-o, a luat-o cu forța, s-a culcat cu ea și a umilit-o.", "Sufletul lui s-a lipit de Dina, fiica lui Iacov. A iubit-o pe tânără și i-a vorbit inimii ei.", "Sihem i-a spus tatălui său Hamor: „Ia-mi-o pe tânăra aceasta de soție.”", "Iacov a auzit că Sihem o pângărise pe fiica lui Dina, dar fiii lui erau cu turmele la câmp, așa că Iacov a tăcut până s-au întors.", "Hamor, tatăl lui Sihem, a ieșit la Iacov ca să vorbească cu el.", "Când au auzit, fiii lui Iacov s-au întors de la câmp. Bărbații s-au mâhnit și s-au mâniat foarte tare, pentru că Sihem făcuse o nebunie în Israel culcându-se cu fiica lui Iacov, lucru care nu trebuia făcut.", "Hamor le-a vorbit și a spus: „Sufletul fiului meu Sihem tânjește după fiica voastră. Vă rog, dați-i-o de soție.", "Înrudiți-vă prin căsătorii cu noi: dați-ne fiicele voastre și luați-vă fiicele noastre.", "Locuiți cu noi. Țara este înaintea voastră; locuiți, faceți comerț și dobândiți proprietăți în ea.”", "Sihem i-a spus tatălui și fraților Dinei: „Să găsesc bunăvoință în ochii voștri și vă voi da orice îmi veți cere.", "Cereți-mi oricât de mare să fie prețul de căsătorie și darul; voi da orice îmi veți spune, numai dați-mi-o pe tânără de soție.”", "Fiii lui Iacov le-au răspuns cu înșelăciune lui Sihem și tatălui său Hamor, pentru că Sihem o pângărise pe sora lor Dina.", "Ei le-au spus: „Nu putem face lucrul acesta, să o dăm pe sora noastră unui bărbat necircumcis, pentru că aceasta ar fi o rușine pentru noi.", "Vom fi de acord cu voi numai cu această condiție: să deveniți ca noi, circumcizând orice persoană de parte bărbătească dintre voi.", "Atunci vă vom da fiicele noastre, le vom lua pe fiicele voastre, vom locui cu voi și vom deveni un singur popor.", "Dar dacă nu ne veți asculta și nu vă veți circumcide, ne vom lua fiica și vom pleca.”", "Cuvintele lor le-au plăcut lui Hamor și fiului său Sihem.", "Tânărul nu a întârziat să facă lucrul acesta, pentru că își găsea plăcerea în fiica lui Iacov și era cel mai respectat din toată casa tatălui său.", "Hamor și fiul său Sihem au venit la poarta cetății și le-au vorbit oamenilor cetății:", "„Oamenii aceștia sunt pașnici față de noi. Să locuiască în țară și să facă negoț în ea, pentru că țara este destul de largă pentru ei. Să le luăm fiicele de soții și să le dăm fiicele noastre.", "Dar oamenii aceștia vor fi de acord să locuiască cu noi și să devenim un singur popor numai dacă orice persoană de parte bărbătească dintre noi este circumcisă, așa cum sunt ei.", "Nu vor fi oare ale noastre turmele, averile și toate animalele lor? Să le acceptăm numai condiția și vor locui cu noi.”", "Toți cei care ieșeau pe poarta cetății i-au ascultat pe Hamor și pe fiul său Sihem, și orice persoană de parte bărbătească a fost circumcisă.", "În a treia zi, când încă îi durea, doi dintre fiii lui Iacov, Simeon și Levi, frații Dinei, și-au luat fiecare sabia, au intrat fără împotrivire în cetate și au ucis toate persoanele de parte bărbătească.", "I-au ucis cu ascuțișul sabiei pe Hamor și pe fiul său Sihem, au luat-o pe Dina din casa lui Sihem și au plecat.", "Fiii lui Iacov au venit peste cei uciși și au jefuit cetatea, pentru că sora lor fusese pângărită.", "Le-au luat oile, vitele, măgarii și tot ce era în cetate și pe câmp.", "Le-au luat toate bogățiile, i-au dus captivi pe toți copiii și toate femeile și au jefuit tot ce era în case.", "Iacov le-a spus lui Simeon și Levi: „M-ați nenorocit, făcându-mă urât locuitorilor țării, canaaniților și fereziților. Eu am puțini oameni; ei se vor aduna împotriva mea, mă vor lovi și voi fi nimicit, eu și casa mea.”", "Ei au răspuns: „Trebuia oare să se poarte cu sora noastră ca și cu o prostituată?”"],
    35: ["Dumnezeu i-a spus lui Iacov: „Ridică-te, urcă-te la Betel și locuiește acolo. Construiește acolo un altar Dumnezeului care ți S-a arătat când fugeai dinaintea fratelui tău Esau.”", "Iacov le-a spus casei lui și tuturor celor care erau cu el: „Îndepărtați dumnezeii străini care sunt între voi, curățiți-vă și schimbați-vă hainele.", "Să ne ridicăm și să urcăm la Betel. Acolo voi construi un altar Dumnezeului care mi-a răspuns în ziua necazului meu și a fost cu mine pe drumul pe care am mers.”", "Ei i-au dat lui Iacov toți dumnezeii străini pe care îi aveau și cerceii din urechi, iar Iacov i-a ascuns sub stejarul de lângă Sihem.", "Au plecat, iar o groază de la Dumnezeu a căzut peste cetățile din jurul lor, astfel încât acestea nu i-au urmărit pe fiii lui Iacov.", "Iacov a ajuns la Luz, adică Betel, în țara Canaanului, el și tot poporul care era cu el.", "A construit acolo un altar și a numit locul El-Betel, pentru că acolo i Se descoperise Dumnezeu când fugea dinaintea fratelui său.", "Debora, doica Rebecăi, a murit și a fost îngropată mai jos de Betel, sub stejar. De aceea i s-a pus numele Alon-Bacut.", "Dumnezeu i S-a arătat din nou lui Iacov, după ce acesta venise din Padan-Aram, și l-a binecuvântat.", "Dumnezeu i-a spus: „Numele tău este Iacov, dar nu te vei mai numi Iacov, ci numele tău va fi Israel.” Și i-a pus numele Israel.", "Dumnezeu i-a spus: „Eu sunt Dumnezeul Atotputernic. Fii roditor și înmulțește-te. Din tine vor ieși o națiune și o adunare de națiuni, iar din trupul tău vor ieși regi.", "Țara pe care le-am dat-o lui Avraam și lui Isaac ți-o voi da ție, iar după tine le voi da țara urmașilor tăi.”", "Dumnezeu S-a înălțat de la el, din locul în care îi vorbise.", "Iacov a ridicat un stâlp în locul în care Dumnezeu îi vorbise, un stâlp de piatră. A turnat peste el o jertfă de băutură și a turnat untdelemn peste el.", "Iacov a numit Betel locul în care Dumnezeu îi vorbise.", "Au plecat din Betel și mai era o oarecare distanță până la Efrata, când Rahela a început să nască și a avut o naștere grea.", "În timpul nașterii grele, moașa i-a spus: „Nu te teme, pentru că și acesta este un fiu.”", "Pe când sufletul ei pleca, pentru că murea, i-a pus copilului numele Ben-Oni, dar tatăl său i-a pus numele Beniamin.", "Rahela a murit și a fost îngropată pe drumul spre Efrata, adică Betleem.", "Iacov a ridicat un stâlp pe mormântul ei. Acesta este stâlpul mormântului Rahelei până în ziua de astăzi.", "Israel a plecat și și-a întins cortul dincolo de turnul Eder.", "Pe când Israel locuia în țara aceea, Ruben s-a dus și s-a culcat cu Bilha, concubina tatălui său, iar Israel a auzit. Fiii lui Iacov erau doisprezece.", "Fiii Leei erau Ruben, întâiul născut al lui Iacov, Simeon, Levi, Iuda, Isahar și Zabulon.", "Fiii Rahelei erau Iosif și Beniamin.", "Fiii Bilhei, slujitoarea Rahelei, erau Dan și Neftali.", "Fiii Zilpei, slujitoarea Leei, erau Gad și Așer. Aceștia sunt fiii lui Iacov, care i s-au născut în Padan-Aram.", "Iacov a venit la tatăl său Isaac, la Mamre, la Chiriat-Arba, adică Hebron, unde Avraam și Isaac locuiseră ca străini.", "Zilele lui Isaac au fost o sută optzeci de ani.", "Isaac și-a dat ultima suflare și a murit. A fost adunat la poporul său, bătrân și sătul de zile, iar fiii săi Esau și Iacov l-au îngropat."],
    36: ["Aceasta este istoria urmașilor lui Esau, adică Edom.", "Esau și-a luat soții dintre fiicele Canaanului: pe Ada, fiica hetitului Elon, pe Oholibama, fiica Anei și nepoata hevitului Țibeon,", "și pe Basmat, fiica lui Ismael și sora lui Nebaiot.", "Ada i l-a născut lui Esau pe Elifaz, iar Basmat l-a născut pe Reuel.", "Oholibama i-a născut pe Ieuș, Ialam și Core. Aceștia sunt fiii lui Esau, care i s-au născut în țara Canaanului.", "Esau și-a luat soțiile, fiii, fiicele, toți oamenii casei lui, turmele, toate animalele și toate bunurile pe care le dobândise în țara Canaanului și a plecat într-o altă țară, departe de fratele său Iacov.", "Averile lor erau prea mari ca să locuiască împreună, iar țara în care locuiau ca străini nu-i putea susține din cauza turmelor lor.", "Esau a locuit în muntele Seir. Esau este Edom.", "Aceasta este istoria urmașilor lui Esau, tatăl edomiților, în muntele Seir.", "Acestea sunt numele fiilor lui Esau: Elifaz, fiul Adei, soția lui Esau, și Reuel, fiul Basmatei, soția lui Esau.", "Fiii lui Elifaz au fost Teman, Omar, Țefo, Gatam și Chenaz.", "Timna era concubina lui Elifaz, fiul lui Esau, și i l-a născut pe Amalec. Aceștia sunt urmașii Adei, soția lui Esau.", "Fiii lui Reuel au fost Nahat, Zerah, Șama și Miza. Aceștia sunt urmașii Basmatei, soția lui Esau.", "Fiii Oholibamei, fiica Anei și nepoata lui Țibeon, soția lui Esau, au fost Ieuș, Ialam și Core.", "Aceștia sunt căpeteniile fiilor lui Esau. Dintre fiii lui Elifaz, întâiul născut al lui Esau: căpetenia Teman, căpetenia Omar, căpetenia Țefo și căpetenia Chenaz,", "căpetenia Core, căpetenia Gatam și căpetenia Amalec. Acestea sunt căpeteniile ieșite din Elifaz în țara Edomului. Aceștia sunt urmașii Adei.", "Dintre fiii lui Reuel, fiul lui Esau: căpetenia Nahat, căpetenia Zerah, căpetenia Șama și căpetenia Miza. Acestea sunt căpeteniile ieșite din Reuel în țara Edomului. Aceștia sunt urmașii Basmatei, soția lui Esau.", "Dintre fiii Oholibamei, soția lui Esau: căpetenia Ieuș, căpetenia Ialam și căpetenia Core. Acestea sunt căpeteniile ieșite din Oholibama, fiica Anei și soția lui Esau.", "Aceștia sunt fiii lui Esau, adică Edom, și acestea sunt căpeteniile lor.", "Aceștia sunt fiii horitului Seir, locuitorii țării: Lotan, Șobal, Țibeon, Ana,", "Dișon, Ețer și Dișan. Acestea sunt căpeteniile horiților, fiii lui Seir, în țara Edomului.", "Fiii lui Lotan au fost Hori și Heman, iar sora lui Lotan era Timna.", "Fiii lui Șobal au fost Alvan, Manahat, Ebal, Șefo și Onam.", "Fiii lui Țibeon au fost Aia și Ana. Acesta este Ana care a găsit izvoarele fierbinți în pustiu, pe când păștea măgarii tatălui său, Țibeon.", "Fiii lui Ana au fost Dișon și Oholibama, fiica lui Ana.", "Fiii lui Dișon au fost Hemdan, Eșban, Itran și Cheran.", "Fiii lui Ețer au fost Bilhan, Zaavan și Acan.", "Fiii lui Dișan au fost Uț și Aran.", "Acestea sunt căpeteniile horiților: căpetenia Lotan, căpetenia Șobal, căpetenia Țibeon, căpetenia Ana,", "căpetenia Dișon, căpetenia Ețer și căpetenia Dișan. Acestea sunt căpeteniile horiților, după căpeteniile lor, în țara Seirului.", "Aceștia sunt regii care au domnit în țara Edomului înainte să domnească vreun rege peste fiii lui Israel.", "Bela, fiul lui Beor, a domnit în Edom, iar numele cetății lui era Dinhaba.", "Bela a murit și, în locul lui, a domnit Iobab, fiul lui Zerah din Boțra.", "Iobab a murit și, în locul lui, a domnit Hușam din țara temaniților.", "Hușam a murit și, în locul lui, a domnit Hadad, fiul lui Bedad, care i-a învins pe madianiți în câmpia Moabului. Numele cetății lui era Avit.", "Hadad a murit și, în locul lui, a domnit Samla din Masreca.", "Samla a murit și, în locul lui, a domnit Șaul din Rehobotul de lângă râu.", "Șaul a murit și, în locul lui, a domnit Baal-Hanan, fiul lui Acbor.", "Baal-Hanan, fiul lui Acbor, a murit și, în locul lui, a domnit Hadar. Numele cetății lui era Pau, iar soția lui se numea Mehetabel, fiica lui Matred și nepoata lui Mezahab.", "Acestea sunt numele căpeteniilor ieșite din Esau, după familiile, locurile și numele lor: căpetenia Timna, căpetenia Alva, căpetenia Ietet,", "căpetenia Oholibama, căpetenia Ela, căpetenia Pinon,", "căpetenia Chenaz, căpetenia Teman, căpetenia Mibțar,", "căpetenia Magdiel și căpetenia Iram. Acestea sunt căpeteniile Edomului, după locuințele lor în țara pe care o stăpâneau. Acesta este Esau, tatăl edomiților."],
    37: ["Iacov a locuit în țara în care tatăl său trăise ca străin, în țara Canaanului.", "Aceasta este istoria urmașilor lui Iacov. Iosif, la vârsta de șaptesprezece ani, păștea turma împreună cu frații săi. Era tânăr și lucra alături de fiii Bilhei și ai Zilpei, soțiile tatălui său. Iosif îi aducea tatălui lor vești rele despre ei.", "Israel îl iubea pe Iosif mai mult decât pe toți ceilalți fii ai săi, pentru că era fiul bătrâneții lui, și i-a făcut o tunică lungă, deosebită.", "Frații lui au văzut că tatăl lor îl iubea mai mult decât pe toți frații lui, l-au urât și nu-i puteau vorbi pașnic.", "Iosif a avut un vis și l-a povestit fraților săi, iar ei l-au urât și mai mult.", "El le-a spus: „Ascultați, vă rog, visul pe care l-am avut:", "iată, legam snopi în mijlocul câmpului. Snopul meu s-a ridicat și a rămas drept, iar snopii voștri s-au strâns în jurul lui și s-au plecat înaintea snopului meu.”", "Frații lui l-au întrebat: „Vei domni tu oare peste noi? Ne vei stăpâni tu oare?” Și l-au urât și mai mult din cauza viselor și cuvintelor lui.", "A mai avut un alt vis și l-a povestit fraților săi: „Iată, am mai avut un vis: soarele, luna și unsprezece stele se plecau înaintea mea.”", "L-a povestit tatălui său și fraților săi, iar tatăl său l-a mustrat și i-a spus: „Ce este visul acesta pe care l-ai avut? Vom veni oare eu, mama ta și frații tăi să ne plecăm până la pământ înaintea ta?”", "Frații lui îl invidiau, dar tatăl său a păstrat cuvântul în minte.", "Frații lui s-au dus să pască turma tatălui lor la Sihem.", "Israel i-a spus lui Iosif: „Frații tăi pasc turma la Sihem, nu-i așa? Vino, te voi trimite la ei.” El a răspuns: „Iată-mă.”", "Israel i-a spus: „Du-te, vezi dacă frații tăi sunt bine și dacă turma este bine, apoi adu-mi vești.” L-a trimis din valea Hebronului, iar el a ajuns la Sihem.", "Un bărbat l-a găsit rătăcind pe câmp și l-a întrebat: „Ce cauți?”", "El a răspuns: „Îi caut pe frații mei. Spune-mi, te rog, unde pasc turma.”", "Bărbatul a spus: „Au plecat de aici, pentru că i-am auzit spunând: «Să mergem la Dotan.»” Iosif a mers după frații lui și i-a găsit la Dotan.", "Ei l-au văzut de departe și, înainte să se apropie de ei, au uneltit să-l omoare.", "Și-au spus unul altuia: „Iată, vine stăpânul viselor!", "Haideți să-l omorâm și să-l aruncăm într-una dintre gropi. Vom spune că l-a mâncat un animal sălbatic și vom vedea ce se va alege de visele lui.”", "Ruben a auzit și l-a scăpat din mâna lor, spunând: „Să nu-i luăm viața.”", "Ruben le-a spus: „Nu vărsați sânge. Aruncați-l în groapa aceasta din pustiu, dar nu puneți mâna pe el.” Intenția lui era să-l scape din mâna lor și să-l ducă înapoi la tatăl său.", "Când Iosif a ajuns la frații lui, aceștia i-au scos tunica, tunica cea deosebită pe care o purta,", "l-au luat și l-au aruncat în groapă. Groapa era goală și nu avea apă.", "Apoi s-au așezat să mănânce. Și-au ridicat ochii și, iată, o caravană de ismaeliți venea din Galaad. Cămilele lor purtau mirodenii, balsam și smirnă, pe care le duceau în Egipt.", "Iuda le-a spus fraților săi: „Ce câștig avem dacă ne omorâm fratele și îi ascundem sângele?", "Haideți să-l vindem ismaeliților și să nu punem mâna pe el, pentru că este fratele nostru, carnea noastră.” Frații lui l-au ascultat.", "Când au trecut niște negustori madianiți, l-au tras și l-au scos pe Iosif din groapă, apoi l-au vândut ismaeliților pentru douăzeci de arginți. Aceștia l-au dus pe Iosif în Egipt.", "Ruben s-a întors la groapă și, iată, Iosif nu mai era în groapă. Atunci și-a sfâșiat hainele.", "S-a întors la frații lui și a spus: „Băiatul nu mai este! Iar eu, unde să mă duc?”", "Ei au luat tunica lui Iosif, au înjunghiat un țap și au înmuiat tunica în sânge.", "Au trimis tunica cea deosebită tatălui lor și au spus: „Am găsit-o. Cercetează, te rog, dacă este tunica fiului tău sau nu.”", "El a recunoscut-o și a spus: „Este tunica fiului meu! Un animal sălbatic l-a mâncat. Iosif a fost sfâșiat negreșit.”", "Iacov și-a sfâșiat hainele, și-a pus pânză de sac în jurul mijlocului și și-a jelit fiul multe zile.", "Toți fiii și toate fiicele lui au venit să-l mângâie, dar el a refuzat să fie mângâiat și a spus: „Jelind mă voi coborî la fiul meu în Șeol.” Și tatăl său l-a plâns.", "Madianiții l-au vândut în Egipt lui Potifar, un dregător al faraonului și comandantul gărzii."],
    38: ["În vremea aceea, Iuda a coborât de la frații lui și s-a oprit la un adulamit numit Hira.", "Acolo, Iuda a văzut-o pe fiica unui canaanit numit Șua, a luat-o de soție și a intrat la ea.", "Ea a rămas însărcinată, a născut un fiu, iar Iuda i-a pus numele Er.", "A rămas din nou însărcinată, a născut un fiu și i-a pus numele Onan.", "A mai născut un fiu și i-a pus numele Șela. Iuda era la Chezib când ea l-a născut.", "Iuda i-a luat întâiului său născut, Er, o soție numită Tamar.", "Dar Er, întâiul născut al lui Iuda, era rău în ochii DOMNULUI, iar DOMNUL l-a omorât.", "Atunci Iuda i-a spus lui Onan: „Intră la soția fratelui tău, împlinește față de ea datoria de cumnat și ridică urmași fratelui tău.”", "Onan știa că urmașul nu va fi al lui. De aceea, ori de câte ori intra la soția fratelui său, își vărsa sămânța pe pământ, ca să nu-i dea urmași fratelui său.", "Ceea ce făcea era rău în ochii DOMNULUI, iar DOMNUL l-a omorât și pe el.", "Iuda i-a spus nurorii sale Tamar: „Rămâi văduvă în casa tatălui tău până când va crește fiul meu Șela”, pentru că își spunea: „Ca nu cumva să moară și el ca frații lui.” Tamar a plecat și a locuit în casa tatălui ei.", "După multă vreme, fiica lui Șua, soția lui Iuda, a murit. După ce și-a încheiat jelirea, Iuda s-a urcat la cei care îi tundeau oile, la Timna, împreună cu prietenul său Hira, adulamitul.", "Tamar a fost înștiințată: „Iată, socrul tău se urcă la Timna ca să-și tundă oile.”", "Ea și-a scos hainele de văduvă, s-a acoperit cu un văl, s-a înfășurat și s-a așezat la intrarea în Enaim, pe drumul spre Timna, pentru că văzuse că Șela crescuse, dar ea nu-i fusese dată de soție.", "Când a văzut-o, Iuda a crezut că este o prostituată, pentru că își acoperise fața.", "S-a abătut spre ea de pe drum și i-a spus: „Lasă-mă, te rog, să intru la tine”, pentru că nu știa că era nora lui. Ea a întrebat: „Ce-mi vei da ca să intri la mine?”", "El a răspuns: „Îți voi trimite un ied din turmă.” Ea a spus: „Îmi vei da un zălog până îl vei trimite?”", "El a întrebat: „Ce zălog să-ți dau?” Ea a răspuns: „Pecetea ta, șnurul ei și toiagul din mâna ta.” El i le-a dat, a intrat la ea, iar ea a rămas însărcinată de la el.", "Ea s-a ridicat, a plecat, și-a scos vălul și a îmbrăcat din nou hainele de văduvă.", "Iuda a trimis iedul prin prietenul său adulamit ca să ia zălogul din mâna femeii, dar acesta nu a găsit-o.", "I-a întrebat pe oamenii locului: „Unde este prostituata cultică ce stătea la Enaim, lângă drum?” Ei au răspuns: „Nu a fost aici nicio prostituată cultică.”", "S-a întors la Iuda și a spus: „Nu am găsit-o. Oamenii locului au spus și ei: «Nu a fost aici nicio prostituată cultică.»”", "Iuda a spus: „Să le păstreze, ca să nu ajungem de râs. Iată, am trimis iedul acesta, dar tu nu ai găsit-o.”", "După aproape trei luni, lui Iuda i s-a spus: „Tamar, nora ta, s-a prostituat și, iată, a rămas însărcinată din prostituție.” Iuda a spus: „Scoateți-o afară și să fie arsă!”", "Pe când era scoasă, ea a trimis vorbă socrului ei: „Am rămas însărcinată de la bărbatul căruia îi aparțin acestea.” Apoi a spus: „Cercetează, te rog, ale cui sunt pecetea, șnurul și toiagul acestea.”", "Iuda le-a recunoscut și a spus: „Ea este mai dreaptă decât mine, pentru că nu i-am dat-o fiului meu Șela.” Și nu a mai avut relații cu ea.", "Când i-a venit vremea să nască, iată că avea gemeni în pântece.", "În timpul nașterii, unul dintre ei și-a scos mâna, iar moașa a luat un fir stacojiu, l-a legat de mâna lui și a spus: „Acesta a ieșit primul.”", "Dar el și-a tras mâna înapoi și, iată, a ieșit fratele lui. Moașa a spus: „Cum ai făcut o spărtură pentru tine?” De aceea i s-a pus numele Pereț.", "După aceea a ieșit fratele lui, care avea firul stacojiu la mână, și i s-a pus numele Zerah."],
    39: ["Iosif a fost coborât în Egipt, iar Potifar, un egiptean, dregător al faraonului și comandant al gărzii, l-a cumpărat de la ismaeliții care îl aduseseră acolo.", "DOMNUL era cu Iosif, iar el prospera. Locuia în casa stăpânului său egiptean.", "Stăpânul său a văzut că DOMNUL era cu el și că DOMNUL făcea să-i reușească în mâini tot ce făcea.", "Iosif a găsit bunăvoință în ochii lui și i-a slujit. Potifar l-a pus supraveghetor peste casa lui și i-a încredințat tot ce avea.", "Din vremea când l-a pus supraveghetor peste casa lui și peste tot ce avea, DOMNUL a binecuvântat casa egipteanului datorită lui Iosif. Binecuvântarea DOMNULUI era peste tot ce avea, în casă și pe câmp.", "Potifar a lăsat tot ce avea în mâna lui Iosif și nu se îngrijea de nimic, în afară de hrana pe care o mânca. Iosif era bine făcut și frumos la înfățișare.", "După aceste lucruri, soția stăpânului său și-a pus ochii pe Iosif și i-a spus: „Culcă-te cu mine!”", "Dar el a refuzat și i-a spus soției stăpânului său: „Iată, stăpânul meu nu se îngrijește de nimic din casă, fiindcă mi-a încredințat tot ce are.", "Nimeni nu este mai mare decât mine în casa aceasta și nu mi-a oprit nimic, în afară de tine, pentru că ești soția lui. Cum aș putea să fac răul acesta atât de mare și să păcătuiesc împotriva lui Dumnezeu?”", "Deși ea îi vorbea lui Iosif zi de zi, el nu a ascultat-o să se culce lângă ea sau să fie cu ea.", "Într-o zi, Iosif a intrat în casă ca să-și facă lucrul, iar înăuntru nu era niciunul dintre oamenii casei.", "Ea l-a apucat de haină și a spus: „Culcă-te cu mine!” Dar el și-a lăsat haina în mâna ei și a fugit afară.", "Când a văzut că își lăsase haina în mâna ei și fugise afară,", "i-a chemat pe oamenii casei și le-a spus: „Uitați-vă! Ne-a adus un evreu ca să ne batjocorească. A venit la mine ca să se culce cu mine, dar eu am strigat tare.", "Când a auzit că mi-am ridicat glasul și am strigat, și-a lăsat haina lângă mine și a fugit afară.”", "Ea a păstrat haina lângă sine până când stăpânul lui s-a întors acasă.", "Apoi i-a spus aceleași cuvinte: „Slujitorul evreu pe care ni l-ai adus a venit la mine ca să mă batjocorească.", "Când mi-am ridicat glasul și am strigat, și-a lăsat haina lângă mine și a fugit afară.”", "Când stăpânul lui a auzit cuvintele soției sale, care îi spunea: „Așa s-a purtat slujitorul tău cu mine”, mânia lui s-a aprins.", "Stăpânul lui Iosif l-a luat și l-a pus în închisoare, în locul în care erau ținuți prizonierii regelui. Iosif a rămas acolo în închisoare.", "Dar DOMNUL era cu Iosif, Și-a revărsat bunătatea statornică asupra lui și i-a dat bunăvoință în ochii comandantului închisorii.", "Comandantul închisorii i-a încredințat lui Iosif toți prizonierii din închisoare, iar tot ce se făcea acolo se făcea sub răspunderea lui.", "Comandantul închisorii nu se îngrijea de nimic din ceea ce era în mâna lui Iosif, pentru că DOMNUL era cu el, iar DOMNUL făcea să reușească tot ce făcea."],
    40: ["După aceste lucruri, paharnicul regelui Egiptului și brutarul lui au greșit față de stăpânul lor, regele Egiptului.", "Faraonul s-a mâniat pe cei doi dregători ai săi, pe mai-marele paharnicilor și pe mai-marele brutarilor.", "I-a pus sub pază în casa comandantului gărzii, în închisoarea în care era ținut Iosif.", "Comandantul gărzii i-a dat în grija lui Iosif, iar el le slujea. Au rămas sub pază multe zile.", "În aceeași noapte, amândoi au avut câte un vis, fiecare cu înțelesul lui: paharnicul și brutarul regelui Egiptului, care erau ținuți în închisoare.", "Iosif a venit la ei dimineața, i-a privit și a văzut că erau tulburați.", "I-a întrebat pe dregătorii faraonului care erau cu el sub pază în casa stăpânului său: „De ce aveți fețele atât de triste astăzi?”", "Ei i-au răspuns: „Am avut câte un vis și nu este nimeni care să-l interpreteze.” Iosif le-a spus: „Nu ale lui Dumnezeu sunt interpretările? Povestiți-mi, vă rog.”", "Mai-marele paharnicilor i-a povestit lui Iosif visul său: „În visul meu, iată, înaintea mea era o viță.", "Vița avea trei ramuri. De îndată ce a înmugurit, florile i s-au deschis, iar ciorchinii au făcut struguri copți.", "Paharul faraonului era în mâna mea. Am luat strugurii, i-am stors în paharul faraonului și am pus paharul în mâna faraonului.”", "Iosif i-a spus: „Aceasta este interpretarea: cele trei ramuri sunt trei zile.", "Peste trei zile, faraonul îți va înălța capul și te va pune din nou în slujba ta. Vei pune paharul faraonului în mâna lui, așa cum făceai înainte, când erai paharnicul lui.", "Dar adu-ți aminte de mine când îți va fi bine. Te rog, arată-mi bunătate, vorbește-i faraonului despre mine și scoate-mă din casa aceasta.", "Pentru că am fost răpit din țara evreilor, iar aici nu am făcut nimic pentru care să mă pună în groapă.”", "Când mai-marele brutarilor a văzut că interpretarea era favorabilă, i-a spus lui Iosif: „Și eu am avut un vis. Iată, aveam pe cap trei coșuri cu pâine albă.", "În coșul de sus erau tot felul de produse coapte pentru faraon, iar păsările le mâncau din coșul de pe capul meu.”", "Iosif a răspuns: „Aceasta este interpretarea: cele trei coșuri sunt trei zile.", "Peste trei zile, faraonul îți va înălța capul de pe tine, te va atârna pe un lemn, iar păsările îți vor mânca trupul.”", "În a treia zi, ziua de naștere a faraonului, el a făcut un ospăț pentru toți slujitorii săi și a înălțat capul mai-marelui paharnicilor și capul mai-marelui brutarilor în mijlocul slujitorilor săi.", "Pe mai-marele paharnicilor l-a pus din nou în slujba lui, iar acesta a pus paharul în mâna faraonului.", "Dar pe mai-marele brutarilor l-a spânzurat, așa cum le interpretase Iosif.", "Mai-marele paharnicilor nu și-a adus aminte de Iosif, ci l-a uitat."],
    41: ["După doi ani împliniți, faraonul a avut un vis. Iată, stătea lângă Nil.", "Din Nil au ieșit șapte vaci frumoase la înfățișare și grase, care pășteau în iarba de pe mal.", "După ele au ieșit din Nil alte șapte vaci, urâte la înfățișare și slabe, și s-au oprit lângă celelalte vaci, pe malul Nilului.", "Vacile urâte și slabe le-au mâncat pe cele șapte vaci frumoase și grase. Atunci faraonul s-a trezit.", "A adormit și a visat a doua oară. Iată, șapte spice sănătoase și frumoase creșteau dintr-un singur pai.", "După ele au răsărit șapte spice subțiri și arse de vântul de răsărit.", "Spicele subțiri le-au înghițit pe cele șapte spice sănătoase și pline. Faraonul s-a trezit și, iată, fusese un vis.", "Dimineața, duhul lui era tulburat. A trimis să-i cheme pe toți magicienii și înțelepții Egiptului. Faraonul le-a povestit visele, dar nimeni nu i le-a putut interpreta.", "Atunci mai-marele paharnicilor i-a spus faraonului: „Astăzi îmi aduc aminte de greșelile mele.", "Faraonul se mâniase pe slujitorii săi și mă pusese sub pază în casa comandantului gărzii, pe mine și pe mai-marele brutarilor.", "În aceeași noapte am avut amândoi câte un vis, fiecare cu înțelesul lui.", "Acolo era cu noi un tânăr evreu, slujitor al comandantului gărzii. I-am povestit visele, iar el ni le-a interpretat, fiecăruia după visul lui.", "Și s-a întâmplat întocmai cum ne interpretase: pe mine m-ai pus din nou în slujba mea, iar pe el l-ai spânzurat.”", "Faraonul a trimis să-l cheme pe Iosif. L-au scos repede din groapă; el s-a ras, și-a schimbat hainele și a venit înaintea faraonului.", "Faraonul i-a spus lui Iosif: „Am avut un vis și nimeni nu-l poate interpreta. Am auzit spunându-se despre tine că, atunci când auzi un vis, îl poți interpreta.”", "Iosif i-a răspuns faraonului: „Nu eu, ci Dumnezeu îi va da faraonului un răspuns de pace.”", "Faraonul i-a spus lui Iosif: „În visul meu stăteam pe malul Nilului.", "Din Nil au ieșit șapte vaci grase și frumoase la înfățișare, care pășteau în iarba de pe mal.", "După ele au ieșit alte șapte vaci, firave, foarte urâte la înfățișare și slabe; în toată țara Egiptului nu am văzut altele atât de urâte.", "Vacile slabe și urâte le-au mâncat pe cele dintâi șapte vaci grase.", "După ce le-au înghițit, nu se putea cunoaște că le mâncaseră, pentru că arătau la fel de urât ca la început. Atunci m-am trezit.", "Apoi am văzut în vis șapte spice pline și frumoase, care creșteau dintr-un singur pai.", "După ele au răsărit șapte spice uscate, subțiri și arse de vântul de răsărit.", "Spicele subțiri le-au înghițit pe cele șapte spice frumoase. Le-am povestit magicienilor, dar nimeni nu mi-a putut explica.”", "Iosif i-a spus faraonului: „Visul faraonului este unul singur. Dumnezeu i-a arătat faraonului ceea ce urmează să facă.", "Cele șapte vaci frumoase sunt șapte ani, iar cele șapte spice frumoase sunt șapte ani. Visul este unul singur.", "Cele șapte vaci slabe și urâte care au ieșit după ele sunt șapte ani, iar cele șapte spice goale, arse de vântul de răsărit, vor fi șapte ani de foamete.", "Acesta este lucrul despre care i-am vorbit faraonului: Dumnezeu i-a arătat faraonului ceea ce urmează să facă.", "Iată, vin șapte ani de mare belșug în toată țara Egiptului.", "După ei vor veni șapte ani de foamete, iar tot belșugul va fi uitat în țara Egiptului. Foametea va mistui țara.", "Belșugul nu va mai fi cunoscut în țară din cauza foametei care va urma, pentru că va fi foarte grea.", "Visul i-a fost dat de două ori faraonului pentru că lucrul este hotărât de Dumnezeu și Dumnezeu îl va împlini curând.", "Acum, faraonul să caute un om priceput și înțelept și să-l pună peste țara Egiptului.", "Faraonul să facă astfel: să numească supraveghetori peste țară și să ia a cincea parte din roadele țării Egiptului în cei șapte ani de belșug.", "Ei să strângă toată hrana acestor ani buni care vin, să depoziteze grâul sub autoritatea faraonului în cetăți și să-l păzească pentru hrană.", "Hrana va fi o rezervă pentru țară în cei șapte ani de foamete care vor veni peste țara Egiptului, astfel încât țara să nu piară de foamete.”", "Propunerea a fost bună în ochii faraonului și ai tuturor slujitorilor lui.", "Faraonul le-a spus slujitorilor săi: „Am putea găsi un alt om ca acesta, în care este Duhul lui Dumnezeu?”", "Faraonul i-a spus lui Iosif: „Pentru că Dumnezeu ți-a făcut cunoscute toate acestea, nimeni nu este atât de priceput și înțelept ca tine.", "Tu vei fi peste casa mea și tot poporul meu se va supune poruncii tale. Numai prin tron voi fi mai mare decât tine.”", "Faraonul i-a spus lui Iosif: „Iată, te-am pus peste toată țara Egiptului.”", "Faraonul și-a scos inelul cu pecete de pe mână și l-a pus pe mâna lui Iosif, l-a îmbrăcat în haine de in fin și i-a pus un lanț de aur la gât.", "L-a urcat în al doilea car pe care îl avea, iar oamenii strigau înaintea lui: „În genunchi!” Astfel l-a pus peste toată țara Egiptului.", "Faraonul i-a spus lui Iosif: „Eu sunt faraonul, dar fără tine nimeni nu-și va ridica mâna sau piciorul în toată țara Egiptului.”", "Faraonul i-a pus lui Iosif numele Țafnat-Paaneah și i-a dat-o de soție pe Asnat, fiica lui Poti-Fera, preotul din On. Iosif a străbătut țara Egiptului.", "Iosif avea treizeci de ani când s-a înfățișat înaintea faraonului, regele Egiptului. A ieșit dinaintea faraonului și a trecut prin toată țara Egiptului.", "În cei șapte ani de belșug, pământul a produs din abundență.", "Iosif a strâns toată hrana celor șapte ani din țara Egiptului și a depozitat-o în cetăți. În fiecare cetate a pus hrana de pe câmpurile din jurul ei.", "A strâns grâu foarte mult, ca nisipul mării, până când a încetat să-l mai numere, pentru că era fără număr.", "Înainte să vină anul foametei, lui Iosif i s-au născut doi fii, pe care i i-a născut Asnat, fiica lui Poti-Fera, preotul din On.", "Iosif i-a pus întâiului născut numele Manase, spunând: „Dumnezeu m-a făcut să uit toată suferința mea și toată casa tatălui meu.”", "Celui de-al doilea i-a pus numele Efraim, spunând: „Dumnezeu m-a făcut roditor în țara suferinței mele.”", "Cei șapte ani de belșug din țara Egiptului s-au sfârșit.", "Au început cei șapte ani de foamete, așa cum spusese Iosif. Era foamete în toate țările, dar în toată țara Egiptului era pâine.", "Când toată țara Egiptului a flămânzit, poporul a strigat la faraon după pâine. Faraonul le-a spus tuturor egiptenilor: „Duceți-vă la Iosif și faceți ce vă va spune.”", "Foametea era peste toată fața pământului. Iosif a deschis toate depozitele și le-a vândut grâu egiptenilor. Foametea era grea în țara Egiptului.", "Din toate țările veneau în Egipt la Iosif ca să cumpere grâu, pentru că foametea era grea pe tot pământul."],
    42: ["Când Iacov a aflat că era grâu în Egipt, le-a spus fiilor săi: „De ce vă uitați unul la altul?”", "Apoi a spus: „Iată, am auzit că este grâu în Egipt. Coborâți acolo și cumpărați-ne de acolo, ca să trăim și să nu murim.”", "Zece dintre frații lui Iosif au coborât să cumpere grâu din Egipt.", "Dar pe Beniamin, fratele lui Iosif, Iacov nu l-a trimis cu frații lui, pentru că își spunea: „Ca nu cumva să i se întâmple vreo nenorocire.”", "Fiii lui Israel au venit să cumpere grâu împreună cu ceilalți care veneau, pentru că foametea era și în țara Canaanului.", "Iosif era guvernatorul țării și el vindea grâu întregului popor al țării. Frații lui Iosif au venit și s-au plecat înaintea lui cu fețele la pământ.", "Iosif i-a văzut pe frații lui și i-a recunoscut, dar s-a purtat cu ei ca un străin și le-a vorbit aspru. I-a întrebat: „De unde veniți?” Ei au răspuns: „Din țara Canaanului, ca să cumpărăm hrană.”", "Iosif i-a recunoscut pe frații lui, dar ei nu l-au recunoscut.", "Iosif și-a adus aminte de visele pe care le avusese despre ei și le-a spus: „Sunteți spioni! Ați venit să vedeți părțile neapărate ale țării.”", "Ei i-au răspuns: „Nu, stăpâne! Slujitorii tăi au venit să cumpere hrană.", "Noi toți suntem fiii unui singur om. Suntem oameni cinstiți; slujitorii tăi nu sunt spioni.”", "El le-a spus: „Nu! Ați venit să vedeți părțile neapărate ale țării.”", "Ei au răspuns: „Slujitorii tăi sunt doisprezece frați, fiii unui singur om din țara Canaanului. Cel mai mic este astăzi cu tatăl nostru, iar unul nu mai este.”", "Iosif le-a spus: „Este așa cum v-am spus: sunteți spioni!", "Prin aceasta veți fi încercați: pe viața faraonului, nu veți pleca de aici până când nu va veni aici fratele vostru cel mai mic.", "Trimiteți pe unul dintre voi să-l aducă pe fratele vostru, iar voi veți rămâne legați, ca să fie încercate cuvintele voastre și să se vadă dacă este adevăr în voi. Dacă nu, pe viața faraonului, sunteți spioni!”", "I-a pus pe toți sub pază timp de trei zile.", "În a treia zi, Iosif le-a spus: „Faceți aceasta și veți trăi, pentru că eu mă tem de Dumnezeu.", "Dacă sunteți oameni cinstiți, unul dintre frații voștri să rămână legat în închisoarea voastră, iar voi mergeți și duceți grâu pentru foametea caselor voastre.", "Aduceți-l la mine pe fratele vostru cel mai mic. Astfel cuvintele voastre vor fi confirmate și nu veți muri.” Ei au făcut așa.", "Și-au spus unul altuia: „Cu adevărat suntem vinovați pentru fratele nostru, pentru că am văzut necazul sufletului lui când ne implora, dar nu l-am ascultat. De aceea a venit peste noi necazul acesta.”", "Ruben le-a răspuns: „Nu v-am spus eu: «Nu păcătuiți împotriva băiatului»? Dar nu ați ascultat. Iată că acum ni se cere socoteală pentru sângele lui.”", "Ei nu știau că Iosif îi înțelegea, pentru că între ei era un interpret.", "Iosif s-a întors de la ei și a plâns. Apoi s-a întors, le-a vorbit, l-a luat pe Simeon dintre ei și l-a legat înaintea ochilor lor.", "Iosif a poruncit să li se umple sacii cu grâu, să se pună fiecăruia banii înapoi în sac și să li se dea hrană pentru drum. Așa li s-a făcut.", "Ei și-au încărcat măgarii cu grâu și au plecat de acolo.", "La locul de popas, unul dintre ei și-a deschis sacul ca să-i dea hrană măgarului și și-a văzut banii la gura sacului.", "Le-a spus fraților săi: „Banii mei au fost puși înapoi! Iată-i în sacul meu!” Li s-a tăiat inima și, tremurând, și-au spus unul altuia: „Ce ne-a făcut Dumnezeu?”", "Au venit la tatăl lor Iacov, în țara Canaanului, și i-au povestit tot ce li se întâmplase:", "„Omul care este stăpânul țării ne-a vorbit aspru și ne-a luat drept spioni ai țării.", "Noi i-am spus: «Suntem oameni cinstiți, nu suntem spioni.", "Suntem doisprezece frați, fii ai tatălui nostru; unul nu mai este, iar cel mai mic este astăzi cu tatăl nostru în țara Canaanului.»", "Atunci omul, stăpânul țării, ne-a spus: «Prin aceasta voi ști că sunteți oameni cinstiți: lăsați-l la mine pe unul dintre frații voștri, luați grâu pentru foametea caselor voastre și plecați.", "Aduceți-l la mine pe fratele vostru cel mai mic. Atunci voi ști că nu sunteți spioni, ci oameni cinstiți. Vi-l voi da înapoi pe fratele vostru și veți putea face negoț în țară.»”", "Pe când își goleau sacii, iată că fiecare avea legătura cu banii în sac. Când ei și tatăl lor au văzut legăturile cu bani, s-au temut.", "Tatăl lor Iacov le-a spus: „Mă lipsiți de copii! Iosif nu mai este, Simeon nu mai este, iar acum vreți să-l luați și pe Beniamin. Toate acestea sunt împotriva mea.”", "Ruben i-a spus tatălui său: „Să-i omori pe cei doi fii ai mei dacă nu ți-l voi aduce înapoi. Încredințează-l în mâna mea și ți-l voi aduce înapoi.”", "Dar Iacov a spus: „Fiul meu nu va coborî cu voi, pentru că fratele lui a murit și numai el a rămas. Dacă i se va întâmpla vreo nenorocire pe drumul pe care mergeți, îmi veți coborî cu durere părul alb în Șeol.”"],
    43: ["Foametea era grea în țară.", "După ce au terminat de mâncat grâul pe care îl aduseseră din Egipt, tatăl lor le-a spus: „Duceți-vă din nou și cumpărați-ne puțină hrană.”", "Iuda i-a răspuns: „Omul ne-a avertizat solemn: «Nu-mi veți vedea fața dacă fratele vostru nu este cu voi.»", "Dacă îl trimiți pe fratele nostru cu noi, vom coborî și îți vom cumpăra hrană.", "Dar dacă nu-l trimiți, nu vom coborî, pentru că omul ne-a spus: «Nu-mi veți vedea fața dacă fratele vostru nu este cu voi.»”", "Israel a spus: „De ce mi-ați făcut răul acesta, spunându-i omului că mai aveți un frate?”", "Ei au răspuns: „Omul ne-a întrebat stăruitor despre noi și despre familia noastră: «Mai trăiește tatăl vostru? Mai aveți un frate?» Noi i-am răspuns la întrebări. De unde puteam ști că va spune: «Aduceți-l pe fratele vostru»?”", "Iuda i-a spus tatălui său Israel: „Trimite băiatul cu mine. Ne vom ridica și vom merge, ca să trăim și să nu murim, noi, tu și copiii noștri.", "Eu voi răspunde pentru el; din mâna mea să-l ceri. Dacă nu ți-l voi aduce și nu-l voi pune înaintea ta, voi purta vina față de tine pentru totdeauna.", "Dacă nu am fi întârziat, ne-am fi întors deja de două ori.”", "Tatăl lor Israel le-a spus: „Dacă trebuie să fie așa, faceți aceasta: luați în sacii voștri din cele mai bune roade ale țării și duceți-i omului un dar: puțin balsam, puțină miere, mirodenii, smirnă, fistic și migdale.", "Luați cu voi de două ori mai mulți bani și duceți înapoi banii care au fost puși la gura sacilor voștri. Poate a fost o greșeală.", "Luați-l și pe fratele vostru, ridicați-vă și întoarceți-vă la omul acela.", "Dumnezeul Atotputernic să vă dea îndurare înaintea omului, ca să vi-l elibereze pe celălalt frate al vostru și pe Beniamin. Iar dacă trebuie să fiu lipsit de copii, lipsit să fiu.”", "Bărbații au luat darul, au luat cu ei de două ori mai mulți bani și pe Beniamin, s-au ridicat, au coborât în Egipt și s-au înfățișat înaintea lui Iosif.", "Când Iosif l-a văzut pe Beniamin cu ei, i-a spus administratorului casei sale: „Adu-i pe oamenii aceștia în casă, înjunghie un animal și pregătește-l, pentru că vor mânca împreună cu mine la amiază.”", "Omul a făcut cum îi poruncise Iosif și i-a adus pe oameni în casa lui Iosif.", "Oamenii s-au temut pentru că fuseseră aduși în casa lui Iosif și au spus: „Suntem aduși aici din cauza banilor care ne-au fost puși înapoi în saci prima dată, ca să găsească prilej împotriva noastră, să se arunce asupra noastră și să ne ia ca sclavi, împreună cu măgarii noștri.”", "S-au apropiat de administratorul casei lui Iosif și i-au vorbit la intrarea casei.", "Ei au spus: „Te rugăm, stăpâne! Noi am coborât prima dată numai ca să cumpărăm hrană.", "Când am ajuns la locul de popas, ne-am deschis sacii și, iată, banii fiecăruia erau la gura sacului, toți banii noștri, după greutatea lor. I-am adus înapoi cu noi.", "Am adus și alți bani ca să cumpărăm hrană. Nu știm cine ne-a pus banii în saci.”", "El a răspuns: „Pace vouă! Nu vă temeți. Dumnezeul vostru și Dumnezeul tatălui vostru v-a pus o comoară în saci. Eu am primit banii voștri.” Apoi l-a adus la ei pe Simeon.", "Omul i-a adus în casa lui Iosif, le-a dat apă să-și spele picioarele și le-a dat nutreț măgarilor.", "Ei au pregătit darul până la venirea lui Iosif la amiază, pentru că auziseră că vor mânca acolo.", "Când Iosif a venit acasă, i-au adus în casă darul pe care îl aveau și s-au plecat înaintea lui până la pământ.", "El i-a întrebat de sănătate și a spus: „Este bine tatăl vostru, bătrânul despre care mi-ați vorbit? Mai trăiește?”", "Ei au răspuns: „Slujitorul tău, tatăl nostru, este bine și încă trăiește.” Apoi s-au plecat cu smerenie.", "Iosif și-a ridicat ochii, l-a văzut pe fratele său Beniamin, fiul mamei sale, și a întrebat: „Acesta este fratele vostru cel mai mic, despre care mi-ați vorbit?” Apoi a spus: „Dumnezeu să-ți arate bunăvoință, fiul meu.”", "Iosif s-a grăbit să plece, pentru că era copleșit de milă pentru fratele său și căuta un loc unde să plângă. A intrat în camera lui și a plâns acolo.", "Apoi și-a spălat fața, a ieșit, s-a stăpânit și a spus: „Aduceți mâncarea.”", "Lui i-au servit separat, fraților separat, iar egiptenilor care mâncau cu el separat, pentru că egiptenii nu puteau mânca împreună cu evreii, lucrul acesta fiind o urâciune pentru egipteni.", "Frații au fost așezați înaintea lui, de la întâiul născut, potrivit dreptului său de naștere, până la cel mai mic, potrivit vârstei lui, și se priveau uimiți unul pe altul.", "Iosif le-a trimis porții de la masa lui, dar porția lui Beniamin era de cinci ori mai mare decât a oricăruia dintre ei. Au băut din belșug și s-au înveselit împreună cu el."],
    44: ["Iosif i-a poruncit administratorului casei sale: „Umple sacii oamenilor cu hrană, atât cât pot duce, și pune banii fiecăruia la gura sacului său.", "Pune cupa mea, cupa de argint, la gura sacului celui mai tânăr, împreună cu banii lui pentru grâu.” Administratorul a făcut după cuvântul lui Iosif.", "Dimineața, când s-a luminat, oamenii au fost lăsați să plece împreună cu măgarii lor.", "Ieșiseră din cetate, dar nu ajunseseră departe, când Iosif i-a spus administratorului casei sale: „Ridică-te, urmărește-i pe oamenii aceia și, când îi vei ajunge, spune-le: «De ce ați răsplătit binele cu rău?", "Nu este aceasta cupa din care bea stăpânul meu și prin care practică divinația? Ați făcut rău făcând lucrul acesta.»”", "El i-a ajuns și le-a spus aceste cuvinte.", "Ei i-au răspuns: „De ce vorbește stăpânul nostru astfel? Departe de slujitorii tăi să facă un asemenea lucru!", "Iată, banii pe care i-am găsit la gura sacilor noștri ți i-am adus înapoi din țara Canaanului. Cum am putea fura argint sau aur din casa stăpânului tău?", "Acela dintre slujitorii tăi la care se va găsi cupa să moară, iar noi ceilalți vom fi sclavii stăpânului nostru.”", "El a spus: „Bine, să fie după cuvintele voastre: acela la care se va găsi cupa va fi sclavul meu, iar voi ceilalți veți fi nevinovați.”", "Fiecare și-a coborât repede sacul la pământ și fiecare și-a deschis sacul.", "Administratorul a cercetat, începând cu cel mai mare și terminând cu cel mai mic, iar cupa a fost găsită în sacul lui Beniamin.", "Atunci și-au sfâșiat hainele, fiecare și-a încărcat măgarul și s-au întors în cetate.", "Iuda și frații lui au intrat în casa lui Iosif, unde acesta se afla încă, și au căzut înaintea lui la pământ.", "Iosif le-a spus: „Ce faptă este aceasta pe care ați făcut-o? Nu știați că un om ca mine poate afla prin divinație?”", "Iuda a răspuns: „Ce putem spune stăpânului nostru? Ce putem vorbi și cum ne-am putea dovedi nevinovăția? Dumnezeu a descoperit vina slujitorilor tăi. Iată, suntem sclavii stăpânului nostru, atât noi, cât și acela la care s-a găsit cupa.”", "Dar Iosif a spus: „Departe de mine să fac aceasta! Numai omul la care s-a găsit cupa va fi sclavul meu. Voi ceilalți urcați-vă în pace la tatăl vostru.”", "Atunci Iuda s-a apropiat de el și a spus: „Te rog, stăpâne, îngăduie-i slujitorului tău să rostească un cuvânt în auzul stăpânului meu și să nu se aprindă mânia ta împotriva slujitorului tău, pentru că tu ești asemenea faraonului.", "Stăpânul meu i-a întrebat pe slujitorii săi: «Mai aveți tată sau frate?»", "Noi i-am răspuns stăpânului meu: «Avem un tată bătrân și un copil al bătrâneții lui, cel mai mic. Fratele lui a murit și numai el a rămas din copiii mamei lui, iar tatăl său îl iubește.»", "Tu le-ai spus slujitorilor tăi: «Aduceți-l la mine, ca să-l văd cu ochii mei.»", "Noi i-am spus stăpânului meu: «Băiatul nu-și poate părăsi tatăl; dacă și-ar părăsi tatăl, acesta ar muri.»", "Dar tu le-ai spus slujitorilor tăi: «Dacă fratele vostru cel mai mic nu coboară cu voi, nu-mi veți mai vedea fața.»", "Când ne-am urcat la slujitorul tău, tatăl meu, i-am spus cuvintele stăpânului meu.", "Tatăl nostru a spus: «Întoarceți-vă și cumpărați-ne puțină hrană.»", "Noi am răspuns: «Nu putem coborî. Vom coborî numai dacă fratele nostru cel mai mic este cu noi, pentru că nu putem vedea fața omului dacă fratele nostru cel mai mic nu este cu noi.»", "Atunci slujitorul tău, tatăl meu, ne-a spus: «Voi știți că soția mea mi-a născut doi fii.", "Unul a plecat de la mine și eu am spus: Cu siguranță a fost sfâșiat! Și nu l-am mai văzut până astăzi.", "Dacă îl veți lua și pe acesta dinaintea mea și i se va întâmpla vreo nenorocire, îmi veți coborî cu durere părul alb în Șeol.»", "Acum, dacă mă voi întoarce la slujitorul tău, tatăl meu, și băiatul nu va fi cu noi, fiindcă viața lui este legată de viața băiatului,", "când va vedea că băiatul nu este, va muri. Slujitorii tăi vor coborî cu durere părul alb al slujitorului tău, tatăl nostru, în Șeol.", "Pentru că slujitorul tău a garantat pentru băiat înaintea tatălui meu, spunând: «Dacă nu ți-l voi aduce înapoi, voi purta vina față de tatăl meu pentru totdeauna.»", "Acum, te rog, lasă-l pe slujitorul tău să rămână sclavul stăpânului meu în locul băiatului, iar băiatul să urce împreună cu frații lui.", "Cum aș putea să mă urc la tatăl meu dacă băiatul nu este cu mine? Să nu văd nenorocirea care îl va lovi pe tatăl meu!”"],
    45: ["Iosif nu s-a mai putut stăpâni înaintea tuturor celor care stăteau lângă el și a strigat: „Scoateți-i pe toți afară de la mine!” Astfel, nimeni nu a rămas cu el când Iosif li s-a făcut cunoscut fraților săi.", "Și-a ridicat glasul și a plâns. Egiptenii l-au auzit, iar casa faraonului a auzit despre aceasta.", "Iosif le-a spus fraților săi: „Eu sunt Iosif! Mai trăiește tatăl meu?” Dar frații lui nu i-au putut răspunde, pentru că erau îngroziți înaintea lui.", "Iosif le-a spus fraților săi: „Apropiați-vă de mine, vă rog.” Ei s-au apropiat, iar el a spus: „Eu sunt Iosif, fratele vostru, pe care l-ați vândut în Egipt.", "Acum să nu vă întristați și să nu vă mâniați pe voi înșivă pentru că m-ați vândut aici, fiindcă Dumnezeu m-a trimis înaintea voastră ca să păstreze viața.", "De doi ani este foamete în țară și mai sunt încă cinci ani în care nu va fi nici arat, nici secerat.", "Dumnezeu m-a trimis înaintea voastră ca să vă păstreze o rămășiță pe pământ și să vă țină în viață printr-o mare izbăvire.", "Așadar, nu voi m-ați trimis aici, ci Dumnezeu. El m-a făcut ca un tată pentru faraon, stăpân peste toată casa lui și conducător peste toată țara Egiptului.", "Grăbiți-vă, urcați-vă la tatăl meu și spuneți-i: «Așa spune fiul tău Iosif: Dumnezeu m-a făcut stăpân peste tot Egiptul. Coboară la mine și nu întârzia.", "Vei locui în ținutul Goșen și vei fi aproape de mine, tu, fiii tăi, fiii fiilor tăi, turmele tale, cirezile tale și tot ce ai.", "Acolo te voi hrăni, pentru că mai sunt încă cinci ani de foamete, ca să nu ajungeți în sărăcie, tu, casa ta și tot ce ai.»", "Iată, ochii voștri și ochii fratelui meu Beniamin văd că gura mea este cea care vă vorbește.", "Povestiți-i tatălui meu despre toată gloria mea în Egipt și despre tot ce ați văzut. Grăbiți-vă și aduceți-l aici pe tatăl meu.”", "Apoi a căzut pe gâtul fratelui său Beniamin și a plâns, iar Beniamin a plâns pe gâtul lui.", "I-a sărutat pe toți frații lui și a plâns cu ei. După aceea, frații lui au vorbit cu el.", "Vestea s-a auzit în casa faraonului: „Au venit frații lui Iosif.” Lucrul acesta a fost bun în ochii faraonului și ai slujitorilor lui.", "Faraonul i-a spus lui Iosif: „Spune-le fraților tăi: «Faceți aceasta: încărcați-vă animalele și mergeți în țara Canaanului.", "Luați-l pe tatăl vostru și casele voastre și veniți la mine. Vă voi da ce este mai bun în țara Egiptului și veți mânca din belșugul țării.»", "Ție ți se poruncește să le spui: «Luați-vă care din țara Egiptului pentru copiii și soțiile voastre, aduceți-l pe tatăl vostru și veniți.", "Să nu vă pară rău pentru lucrurile voastre, pentru că ce este mai bun în toată țara Egiptului va fi al vostru.»”", "Fiii lui Israel au făcut așa. Iosif le-a dat care, după porunca faraonului, și le-a dat provizii pentru drum.", "Fiecăruia i-a dat câte un rând de haine, dar lui Beniamin i-a dat trei sute de arginți și cinci rânduri de haine.", "Tatălui său i-a trimis zece măgari încărcați cu cele mai bune lucruri ale Egiptului și zece măgărițe încărcate cu grâu, pâine și hrană pentru călătoria tatălui său.", "Apoi și-a lăsat frații să plece. Când au plecat, le-a spus: „Să nu vă certați pe drum.”", "Ei s-au urcat din Egipt și au venit în țara Canaanului, la tatăl lor Iacov.", "I-au spus: „Iosif este încă în viață și el este conducător peste toată țara Egiptului!” Inima lui Iacov a amorțit, pentru că nu-i credea.", "Dar când i-au spus toate cuvintele lui Iosif și a văzut carele pe care le trimisese Iosif ca să-l ducă, duhul tatălui lor Iacov s-a înviorat.", "Israel a spus: „Este de ajuns! Fiul meu Iosif este încă în viață. Mă voi duce să-l văd înainte să mor.”"],
    46: ["Israel a plecat cu tot ce avea și a ajuns la Beer-Șeba. A adus jertfe Dumnezeului tatălui său Isaac.", "Dumnezeu i-a vorbit lui Israel în vedenii de noapte și a spus: „Iacov! Iacov!” El a răspuns: „Iată-mă.”", "Dumnezeu a spus: „Eu sunt Dumnezeu, Dumnezeul tatălui tău. Nu te teme să cobori în Egipt, pentru că acolo voi face din tine o națiune mare.", "Eu Însumi voi coborî cu tine în Egipt și tot Eu te voi aduce negreșit înapoi. Iosif îți va închide ochii cu mâna lui.”", "Iacov s-a ridicat din Beer-Șeba. Fiii lui Israel i-au urcat pe tatăl lor Iacov, pe copiii și pe soțiile lor în carele pe care le trimisese faraonul ca să-l ducă.", "Și-au luat turmele și bunurile pe care le dobândiseră în țara Canaanului și au venit în Egipt: Iacov și toți urmașii lui împreună cu el.", "I-a adus cu el în Egipt pe fiii și nepoții lui, pe fiicele și nepoatele lui, pe toți urmașii săi.", "Acestea sunt numele fiilor lui Israel care au venit în Egipt, Iacov și fiii lui: Ruben, întâiul născut al lui Iacov.", "Fiii lui Ruben au fost: Enoh, Palu, Hețron și Carmi.", "Fiii lui Simeon au fost: Iemuel, Iamin, Ohad, Iachin, Țohar și Șaul, fiul unei canaanite.", "Fiii lui Levi au fost: Gherșon, Chehat și Merari.", "Fiii lui Iuda au fost: Er, Onan, Șela, Pereț și Zerah; dar Er și Onan au murit în țara Canaanului. Fiii lui Pereț au fost Hețron și Hamul.", "Fiii lui Isahar au fost: Tola, Puva, Iob și Șimron.", "Fiii lui Zabulon au fost: Sered, Elon și Iahleel.", "Aceștia sunt fiii pe care Lea i i-a născut lui Iacov în Padan-Aram, împreună cu fiica lui, Dina. Toți fiii și fiicele lui erau treizeci și trei de persoane.", "Fiii lui Gad au fost: Țifion, Haghi, Șuni, Ețbon, Eri, Arodi și Areli.", "Fiii lui Așer au fost: Imna, Ișva, Ișvi, Beria și sora lor, Serah. Fiii lui Beria au fost Heber și Malchiel.", "Aceștia sunt fiii Zilpei, pe care Laban i-o dăduse fiicei sale Lea. Ea i-a născut lui Iacov șaisprezece persoane.", "Fiii Rahelei, soția lui Iacov, au fost Iosif și Beniamin.", "În țara Egiptului, lui Iosif i s-au născut Manase și Efraim, pe care i i-a născut Asnat, fiica lui Poti-Fera, preotul din On.", "Fiii lui Beniamin au fost: Bela, Becher, Așbel, Ghera, Naaman, Ehi, Roș, Mupim, Hupim și Ard.", "Aceștia sunt fiii Rahelei, care i s-au născut lui Iacov: în total paisprezece persoane.", "Fiul lui Dan a fost Hușim.", "Fiii lui Neftali au fost: Iahțeel, Guni, Iețer și Șilem.", "Aceștia sunt fiii Bilhei, pe care Laban i-o dăduse fiicei sale Rahela. Ea i-a născut lui Iacov șapte persoane.", "Toate persoanele care au venit cu Iacov în Egipt, ieșite din trupul lui, fără soțiile fiilor lui Iacov, erau în total șaizeci și șase.", "Fiii lui Iosif care i s-au născut în Egipt erau două persoane. Toate persoanele din casa lui Iacov care au venit în Egipt erau șaptezeci.", "Iacov l-a trimis pe Iuda înaintea lui la Iosif, ca să-i arate drumul spre Goșen. Și au ajuns în ținutul Goșen.", "Iosif și-a pregătit carul și s-a urcat în Goșen ca să-l întâmpine pe tatăl său Israel. Când i s-a înfățișat, a căzut pe gâtul lui și a plâns mult timp pe gâtul lui.", "Israel i-a spus lui Iosif: „Acum pot să mor, după ce ți-am văzut fața și știu că ești încă în viață.”", "Iosif le-a spus fraților săi și casei tatălui său: „Mă voi urca să-i dau de veste faraonului și îi voi spune: «Frații mei și casa tatălui meu, care erau în țara Canaanului, au venit la mine.", "Oamenii sunt păstori, pentru că s-au ocupat cu creșterea animalelor. Și-au adus turmele, cirezile și tot ce au.»", "Când faraonul vă va chema și vă va întreba: «Care este ocupația voastră?»", "să răspundeți: «Slujitorii tăi s-au ocupat cu creșterea animalelor din tinerețe până acum, atât noi, cât și părinții noștri», ca să locuiți în ținutul Goșen, pentru că orice păstor de oi este o urâciune pentru egipteni.”"],
    47: ["Iosif a venit și i-a dat de veste faraonului: „Tatăl meu și frații mei au venit din țara Canaanului cu turmele, cirezile și tot ce au. Iată, sunt în ținutul Goșen.”", "A luat cinci dintre frații lui și i-a înfățișat înaintea faraonului.", "Faraonul i-a întrebat pe frații lui: „Care este ocupația voastră?” Ei i-au răspuns faraonului: „Slujitorii tăi sunt păstori de oi, atât noi, cât și părinții noștri.”", "I-au mai spus faraonului: „Am venit să locuim ca străini în țară, pentru că nu mai este pășune pentru turmele slujitorilor tăi, atât de grea este foametea în țara Canaanului. Acum, te rugăm, îngăduie-le slujitorilor tăi să locuiască în ținutul Goșen.”", "Faraonul i-a spus lui Iosif: „Tatăl tău și frații tăi au venit la tine.", "Țara Egiptului este înaintea ta. Așază-i pe tatăl tău și pe frații tăi în cea mai bună parte a țării. Să locuiască în ținutul Goșen. Iar dacă știi că printre ei sunt oameni pricepuți, pune-i supraveghetori peste turmele mele.”", "Iosif l-a adus pe tatăl său Iacov și l-a înfățișat înaintea faraonului. Iacov l-a binecuvântat pe faraon.", "Faraonul l-a întrebat pe Iacov: „Câți sunt anii vieții tale?”", "Iacov i-a răspuns faraonului: „Anii pribegiei mele sunt o sută treizeci. Puțini și grei au fost anii vieții mele și nu au ajuns la anii vieții părinților mei în zilele pribegiei lor.”", "Iacov l-a binecuvântat pe faraon și a ieșit dinaintea lui.", "Iosif i-a așezat pe tatăl și pe frații săi și le-a dat o proprietate în țara Egiptului, în cea mai bună parte a țării, în ținutul Ramses, așa cum poruncise faraonul.", "Iosif i-a hrănit cu pâine pe tatăl său, pe frații săi și pe toată casa tatălui său, după numărul copiilor lor.", "Nu mai era pâine în toată țara, pentru că foametea era foarte grea. Țara Egiptului și țara Canaanului erau sleite din cauza foametei.", "Iosif a strâns toți banii care se găseau în țara Egiptului și în țara Canaanului în schimbul grâului pe care îl cumpărau, iar banii i-a adus în casa faraonului.", "Când banii din țara Egiptului și din țara Canaanului s-au terminat, toți egiptenii au venit la Iosif și au spus: „Dă-ne pâine! De ce să murim înaintea ta? Pentru că nu mai avem bani.”", "Iosif a răspuns: „Dați-mi animalele voastre, iar eu vă voi da pâine în schimbul lor, dacă nu mai aveți bani.”", "Ei și-au adus animalele la Iosif, iar Iosif le-a dat pâine în schimbul cailor, al turmelor de oi, al cirezilor de vite și al măgarilor. În anul acela i-a hrănit cu pâine în schimbul tuturor animalelor lor.", "Când anul acela s-a încheiat, au venit la el în anul următor și i-au spus: „Nu vom ascunde de stăpânul nostru că banii s-au terminat, iar turmele de animale sunt ale stăpânului nostru. Nu a mai rămas înaintea stăpânului nostru decât trupul nostru și pământul nostru.", "De ce să murim înaintea ochilor tăi, atât noi, cât și pământul nostru? Cumpără-ne pe noi și pământul nostru în schimbul pâinii, iar noi și pământul nostru vom fi slujitorii faraonului. Dă-ne sămânță, ca să trăim și să nu murim, iar pământul să nu rămână pustiu.”", "Astfel, Iosif a cumpărat pentru faraon tot pământul Egiptului, pentru că fiecare egiptean și-a vândut ogorul, atât de grea era foametea peste ei. Pământul a ajuns al faraonului.", "Cât despre popor, Iosif l-a mutat în cetăți, de la un capăt al hotarului Egiptului până la celălalt.", "Numai pământul preoților nu l-a cumpărat, pentru că preoții primeau o rație stabilită de faraon și trăiau din rația pe care le-o dădea faraonul. De aceea nu și-au vândut pământul.", "Iosif a spus poporului: „Iată, astăzi v-am cumpărat pe voi și pământul vostru pentru faraon. Iată sămânță pentru voi; semănați pământul.", "La seceriș să dați a cincea parte faraonului, iar patru părți vor fi ale voastre: ca sămânță pentru ogor, hrană pentru voi, pentru cei din casele voastre și pentru copiii voștri.”", "Ei au spus: „Ne-ai păstrat în viață! Să găsim bunăvoință în ochii stăpânului nostru și vom fi slujitorii faraonului.”", "Iosif a făcut din aceasta o lege cu privire la pământul Egiptului, valabilă până în ziua de astăzi: a cincea parte era a faraonului. Numai pământul preoților nu a ajuns al faraonului.", "Israel a locuit în țara Egiptului, în ținutul Goșen. Au dobândit proprietăți acolo, au fost roditori și s-au înmulțit foarte mult.", "Iacov a trăit în țara Egiptului șaptesprezece ani. Zilele lui Iacov, anii vieții lui, au fost o sută patruzeci și șapte de ani.", "Când s-a apropiat vremea ca Israel să moară, l-a chemat pe fiul său Iosif și i-a spus: „Dacă am găsit bunăvoință în ochii tăi, pune-ți, te rog, mâna sub coapsa mea și poartă-te cu mine cu bunătate statornică și credincioșie. Te rog, să nu mă îngropi în Egipt.", "Când mă voi culca împreună cu părinții mei, să mă scoți din Egipt și să mă îngropi în mormântul lor.” Iosif a răspuns: „Voi face după cuvântul tău.”", "Israel a spus: „Jură-mi!” Iosif i-a jurat, iar Israel s-a plecat la capul patului său."],
    48: ["După aceste lucruri, lui Iosif i s-a spus: „Iată, tatăl tău este bolnav.” Atunci i-a luat cu el pe cei doi fii ai săi, Manase și Efraim.", "Lui Iacov i s-a dat de veste: „Iată, fiul tău Iosif a venit la tine.” Israel și-a adunat puterile și s-a așezat pe pat.", "Iacov i-a spus lui Iosif: „Dumnezeul Atotputernic mi S-a arătat la Luz, în țara Canaanului, și m-a binecuvântat.", "El mi-a spus: «Iată, te voi face roditor, te voi înmulți și voi face din tine o adunare de popoare. Voi da țara aceasta urmașilor tăi după tine ca stăpânire veșnică.»", "Acum, cei doi fii ai tăi, care ți s-au născut în țara Egiptului înainte să vin eu la tine în Egipt, sunt ai mei. Efraim și Manase vor fi ai mei, la fel ca Ruben și Simeon.", "Dar copiii care ți se vor naște după ei vor fi ai tăi. În moștenirea lor vor fi numiți după numele fraților lor.", "Cât despre mine, când veneam din Padan, Rahela a murit lângă mine în țara Canaanului, pe drum, când mai era o oarecare distanță până la Efrata. Am îngropat-o acolo, pe drumul spre Efrata, adică Betleem.”", "Israel i-a văzut pe fiii lui Iosif și a întrebat: „Cine sunt aceștia?”", "Iosif i-a răspuns tatălui său: „Sunt fiii mei, pe care mi i-a dat Dumnezeu aici.” Israel a spus: „Adu-i la mine, te rog, ca să-i binecuvântez.”", "Ochii lui Israel erau slăbiți din cauza bătrâneții și nu mai putea vedea bine. Iosif i-a apropiat de el, iar Israel i-a sărutat și i-a îmbrățișat.", "Israel i-a spus lui Iosif: „Nu credeam că îți voi mai vedea fața, dar iată, Dumnezeu mi-a îngăduit să-ți văd și urmașii.”", "Iosif i-a luat de lângă genunchii lui Israel și s-a plecat cu fața la pământ.", "Iosif i-a luat pe amândoi: pe Efraim cu mâna dreaptă, spre mâna stângă a lui Israel, și pe Manase cu mâna stângă, spre mâna dreaptă a lui Israel, și i-a apropiat de el.", "Dar Israel și-a întins mâna dreaptă și a pus-o pe capul lui Efraim, care era cel mai mic, iar mâna stângă a pus-o pe capul lui Manase. Și-a încrucișat mâinile în mod intenționat, deși Manase era întâiul născut.", "L-a binecuvântat pe Iosif și a spus: „Dumnezeul înaintea căruia au umblat părinții mei Avraam și Isaac, Dumnezeul care m-a păstorit din ziua nașterii mele până în ziua aceasta,", "Îngerul care m-a răscumpărat din orice rău să-i binecuvânteze pe băieții aceștia. Numele meu și numele părinților mei Avraam și Isaac să fie purtat prin ei și să se înmulțească nespus de mult pe pământ.”", "Când Iosif a văzut că tatăl său își pusese mâna dreaptă pe capul lui Efraim, lucrul acesta nu i-a plăcut. A apucat mâna tatălui său ca s-o mute de pe capul lui Efraim pe capul lui Manase.", "Iosif i-a spus tatălui său: „Nu așa, tată, pentru că acesta este întâiul născut. Pune-ți mâna dreaptă pe capul lui.”", "Dar tatăl său a refuzat și a spus: „Știu, fiul meu, știu. Și el va deveni un popor și va fi mare. Totuși, fratele lui mai mic va fi mai mare decât el, iar urmașii lui vor deveni o mulțime de națiuni.”", "În ziua aceea i-a binecuvântat și a spus: „Prin tine va binecuvânta Israel, spunând: «Dumnezeu să te facă asemenea lui Efraim și lui Manase.»” Astfel l-a pus pe Efraim înaintea lui Manase.", "Israel i-a spus lui Iosif: „Iată, eu mor, dar Dumnezeu va fi cu voi și vă va aduce înapoi în țara părinților voștri.", "Ție îți dau o parte mai mult decât fraților tăi, pe care am luat-o din mâna amoriților cu sabia și cu arcul meu.”"],
    49: ["Iacov și-a chemat fiii și a spus: „Adunați-vă, ca să vă spun ce vi se va întâmpla în zilele care vor veni.", "Strângeți-vă și ascultați, fii ai lui Iacov! Ascultați-l pe Israel, tatăl vostru!", "Ruben, tu ești întâiul meu născut, puterea mea și începutul vigorii mele, întâiul în demnitate și întâiul în putere.", "Năvalnic ca apele, nu vei mai avea întâietatea, pentru că te-ai urcat în patul tatălui tău; atunci l-ai pângărit. S-a urcat în așternutul meu!", "Simeon și Levi sunt frați; săbiile lor sunt unelte ale violenței.", "Sufletul meu să nu intre în sfatul lor, iar onoarea mea să nu se unească cu adunarea lor, pentru că în mânia lor au ucis oameni și, din încăpățânare, au schilodit tauri.", "Blestemată să fie mânia lor, pentru că a fost aprigă, și furia lor, pentru că a fost crudă! Îi voi împărți în Iacov și îi voi împrăștia în Israel.", "Iuda, frații tăi te vor lăuda. Mâna ta va fi pe grumazul dușmanilor tăi, iar fiii tatălui tău se vor pleca înaintea ta.", "Iuda este un pui de leu. De la pradă te-ai ridicat, fiul meu. S-a plecat și s-a culcat asemenea unui leu, asemenea unei leoaice. Cine îl va trezi?", "Sceptrul nu se va depărta de Iuda, nici toiagul de conducător dintre picioarele lui, până când va veni cel căruia îi aparține, iar popoarele i se vor supune.", "Își leagă măgărușul de viță și puiul măgăriței de vița aleasă. Își spală haina în vin și veșmântul în sângele strugurilor.", "Ochii lui sunt mai întunecați decât vinul, iar dinții lui mai albi decât laptele.", "Zabulon va locui lângă țărmul mării; va fi lângă un liman pentru corăbii, iar hotarul lui se va întinde spre Sidon.", "Isahar este un măgar puternic, culcat între poveri.", "A văzut că odihna este bună și că țara este plăcută. Și-a plecat umărul sub povară și a ajuns la muncă silnică.", "Dan își va judeca poporul ca una dintre semințiile lui Israel.", "Dan va fi un șarpe pe drum, o viperă pe cărare, care mușcă încheieturile calului, iar călărețul lui cade pe spate.", "Aștept mântuirea Ta, DOMNULE!", "Pe Gad îl va ataca o ceată, dar el o va ataca din urmă.", "Hrana lui Așer va fi bogată și el va oferi delicatese împărătești.", "Neftali este o cerboaică lăsată liberă, care rostește cuvinte frumoase.", "Iosif este un vlăstar roditor, un vlăstar roditor lângă un izvor; ramurile lui se întind peste zid.", "Arcașii l-au atacat cu înverșunare, au tras asupra lui și l-au urmărit cu dușmănie.", "Dar arcul lui a rămas tare, iar brațele mâinilor lui au fost întărite de mâinile Celui Puternic al lui Iacov; de acolo vine Păstorul, Stânca lui Israel,", "de la Dumnezeul tatălui tău, care te va ajuta, și de la Cel Atotputernic, care te va binecuvânta cu binecuvântările cerurilor de sus, cu binecuvântările adâncului întins dedesubt și cu binecuvântările sânilor și ale pântecelui.", "Binecuvântările tatălui tău au întrecut binecuvântările strămoșilor mei, până la hotarele dealurilor veșnice. Ele vor fi pe capul lui Iosif și pe creștetul celui despărțit de frații săi.", "Beniamin este un lup care sfâșie. Dimineața devorează prada, iar seara împarte jaful.”", "Acestea sunt cele douăsprezece seminții ale lui Israel și acesta este cuvântul pe care li l-a spus tatăl lor când i-a binecuvântat. Pe fiecare l-a binecuvântat după binecuvântarea lui.", "Apoi le-a poruncit: „Eu voi fi adunat la poporul meu. Îngropați-mă alături de părinții mei, în peștera din ogorul hetitului Efron,", "în peștera din ogorul Macpela, care este în fața lui Mamre, în țara Canaanului, ogor pe care Avraam l-a cumpărat împreună cu peștera de la hetitul Efron ca proprietate pentru înmormântare.", "Acolo au fost îngropați Avraam și soția lui Sara; acolo au fost îngropați Isaac și soția lui Rebeca, iar acolo am îngropat-o și eu pe Lea.", "Ogorul și peștera din el au fost cumpărate de la fiii lui Het.”", "Când Iacov a terminat de dat porunci fiilor săi, și-a strâns picioarele în pat, și-a dat ultima suflare și a fost adunat la poporul său."],
    50: ["Iosif s-a aruncat peste fața tatălui său, a plâns asupra lui și l-a sărutat.", "Iosif le-a poruncit slujitorilor săi, medicii, să-l îmbălsămeze pe tatăl său, iar medicii l-au îmbălsămat pe Israel.", "Au fost necesare patruzeci de zile pentru el, pentru că atât durează îmbălsămarea. Egiptenii l-au plâns șaptezeci de zile.", "După ce au trecut zilele de plângere, Iosif le-a vorbit celor din casa faraonului: „Dacă am găsit bunăvoință în ochii voștri, vorbiți, vă rog, în auzul faraonului și spuneți-i:", "«Tatăl meu m-a pus să jur și a spus: „Iată, eu mor. Să mă îngropi în mormântul pe care mi l-am săpat în țara Canaanului.” Acum, te rog, lasă-mă să mă urc ca să-mi îngrop tatăl, apoi mă voi întoarce.»”", "Faraonul a răspuns: „Urcă-te și îngroapă-l pe tatăl tău, așa cum te-a pus să juri.”", "Iosif s-a urcat ca să-și îngroape tatăl. Împreună cu el s-au urcat toți slujitorii faraonului, bătrânii casei lui și toți bătrânii țării Egiptului,", "toată casa lui Iosif, frații lui și casa tatălui său. Numai copiii, turmele și cirezile lor au rămas în ținutul Goșen.", "Împreună cu el s-au urcat și care și călăreți; alaiul era foarte mare.", "Au ajuns la aria lui Atad, care este dincolo de Iordan, și au făcut acolo o jelire foarte mare și adâncă. Iosif a ținut pentru tatăl său un doliu de șapte zile.", "Când locuitorii țării, canaaniții, au văzut jelirea de la aria lui Atad, au spus: „Aceasta este o jelire grea a egiptenilor.” De aceea locul a fost numit Abel-Mițraim; el este dincolo de Iordan.", "Fiii lui Iacov au făcut pentru el așa cum le poruncise.", "L-au dus în țara Canaanului și l-au îngropat în peștera din ogorul Macpela, lângă Mamre, ogor pe care Avraam îl cumpărase împreună cu peștera de la hetitul Efron ca proprietate pentru înmormântare.", "După ce și-a îngropat tatăl, Iosif s-a întors în Egipt împreună cu frații săi și cu toți cei care se urcaseră cu el ca să-i îngroape tatăl.", "Când frații lui Iosif au văzut că tatăl lor murise, au spus: „Poate că Iosif ne va urî și ne va răsplăti pe deplin pentru tot răul pe care i l-am făcut.”", "Au trimis să i se spună lui Iosif: „Înainte să moară, tatăl tău a poruncit:", "«Așa să-i spuneți lui Iosif: Te rog, iartă fărădelegea fraților tăi și păcatul lor, pentru că ți-au făcut rău.» Acum, te rugăm, iartă fărădelegea slujitorilor Dumnezeului tatălui tău.” Iosif a plâns când i-au vorbit.", "Frații lui au venit și s-au aruncat înaintea lui, spunând: „Iată, suntem slujitorii tăi.”", "Iosif le-a spus: „Nu vă temeți! Sunt eu oare în locul lui Dumnezeu?", "Voi ați plănuit răul împotriva mea, dar Dumnezeu l-a rânduit spre bine, ca să împlinească ceea ce se vede astăzi: să păstreze în viață un popor numeros.", "Acum, nu vă temeți. Eu vă voi hrăni pe voi și pe copiii voștri.” I-a mângâiat și le-a vorbit inimii.", "Iosif a locuit în Egipt, el și casa tatălui său. A trăit o sută zece ani.", "Iosif i-a văzut pe copiii lui Efraim până la a treia generație. Și copiii lui Machir, fiul lui Manase, s-au născut pe genunchii lui Iosif.", "Iosif le-a spus fraților săi: „Eu mor, dar Dumnezeu va veni negreșit în ajutorul vostru și vă va ridica din țara aceasta în țara pe care a jurat că le-o va da lui Avraam, lui Isaac și lui Iacov.”", "Iosif i-a pus pe fiii lui Israel să jure și a spus: „Dumnezeu va veni negreșit în ajutorul vostru; atunci să-mi duceți oasele de aici.”", "Iosif a murit la vârsta de o sută zece ani. L-au îmbălsămat și a fost pus într-un sicriu în Egipt."],
  },
}
